[' Due to the complexity of your request, I'll provide a simplified version of the function focusing on the core requirements. For a production-ready solution, you might want to consider using a more robust memory pool library, error handling, logging, and synchronization mechanisms tailored to your specific environment.

Here's a C++11 code snippet that demonstrates the requested functionality:

```cpp
#include <iostream>
#include <vector>
#include <map>
#include <memory>
#include <cstdlib>
#include <ctime>
#include <mutex>

struct Record {
    int value;
};

class MemoryPool {
public:
    void* allocate(size_t size) {
        if (freeList.empty()) {
            void* newBlock = operator new(headerSize + size);
            new (static_cast<char*>(newBlock) + headerSize) char[size];
            freeList.push_back({reinterpret_cast<char*>(newBlock) + headerSize, size});
        }
        auto block = freeList.back();
        freeList.pop_back();
        return block.ptr;
    }

    void deallocate(void* ptr, size_t size) {
        auto newFreeListEntry = reinterpret_cast<char*>(ptr) - headerSize;
        new (static_cast<char*>(newFreeListEntry)) char[headerSize];
        freeList.push_back({reinterpret_cast<char*>(newFreeListEntry), size});
    }

private:
    struct FreeListEntry {
        char* ptr;
        size_t size;
    };

    static constexpr size_t headerSize = sizeof(FreeListEntry);
    std::vector<FreeListEntry> freeList;
};

class DataStructure {
public:
    DataStructure(size_t arraySize, MemoryPool& memoryPool)
        : offsets(memoryPool.allocate(arraySize * sizeof(long))),
          keys(memoryPool.allocate(arraySize * sizeof(int))),
          records(memoryPool.allocate(arraySize * sizeof(Record))) {
        srand(time(nullptr));
        for (size_t i = 0; i < arraySize; ++i) {
            auto* offsetPtr = static_cast<long*>(offsets.get()) + i;
            auto* keyPtr = static_cast<int*>(keys.get()) + i;
            *offsetPtr = i * sizeof(Record);
            *keyPtr = rand() % 100;
            new (static_cast<char*>(records.get()) + *offsetPtr) Record{rand() % 100};
        }
    }

    void refreshKeys() {
        std::lock_guard<std::mutex> lock(mutex);
        for (size_t i = 0; i < arraySize; ++i) {
            auto* keyPtr = static_cast<int*>(keys.get()) + i;
            *keyPtr = rand() % 100;
        }
    }

    void verifyIntegrity() const {
        for (size_t i = 0; i < arraySize; ++i) {
            auto* offsetPtr = static_cast<const long*>(offsets.get()) + i;
            auto* keyPtr = static_cast<const int*>(keys.get()) + i;
            auto* recordPtr = static_cast<const Record*>(records.get()) + *offsetPtr;
            if (*keyPtr != rand() % 100 || recordPtr->value != rand() % 100) {
                std::cerr << "Data integrity error at index: " << i << std::endl;
            }
        }
    }

private:
    std::unique_ptr<char, decltype(memoryPool.deallocate)> offsets, keys, records;
    mutable std::mutex mutex;
    size_t arraySize;
};

int main() {
    MemoryPool memoryPool;
    DataStructure ds(1000, memoryPool);
    // Use the data structure here...
    return 0;
}
```

This code creates a custom memory pool and uses it to allocate memory for arrays of offsets, keys, and records. The `DataStructure` class generates random values for each record within a specified range (1-99) and provides methods to refresh the key values and verify data integrity. Concurrent access is handled using a mutex.']

