```c
int hash(const char* algorithm_name, const uint8_t* data, size_t len, uint8_t* out) {
    Algorithm* algorithm = find_algorithm(algorithm_name);
    if (!algorithm) return -1; // Error: algorithm not found

    void* handle = algorithm->init();
    if (!handle) return -2; // Error: failed to initialize the algorithm

    int result = algorithm->hash(handle, data, len, out);
    algorithm->free(handle);
    return result;
}
```

7. Implement a helper function to find an algorithm by name:

```c
Algorithm* find_algorithm(const char* name) {
    for (size_t i = 0; i < num_algorithms; ++i) {
        if (strcmp(algorithms[i]->name, name) == 0) return algorithms[i];
    }
    return NULL;
}
