const express = require('express');
const mongoose = require('mongoose');
const joi = require('joi');
const rateLimit = require('express-rate-limit');
const axios = require('axios');

// Define your resource schema and model
const resourceSchema = new mongoose.Schema({
  id: String,
  data: Object,
  version: Number,
  createdAt: Date,
  updatedAt: Date,
  deletedAt: Date,
});

const Resource = mongoose.model('Resource', resourceSchema);

// Define Joi schema for request body validation
const updateSchema = joi.object().keys({
  data: joi.object().required(),
});

// Rate limiting middleware
const limiter = rateLimit({
  max: 60, // limit each IP to 60 requests per hour
  windowMs: 60 * 60 * 1000, // 1 hour window
});

// Express app setup
const app = express();
app.use(express.json());
app.use(limiter);

// Update resource (PUT)
app.put('/resources/:id', async (req, res) => {
  const { error } = updateSchema.validate(req.body);
  if (error) return res.status(400).json({ error: error.details[0].message });

  // Check for version mismatch and optimistic locking
  const resource = await Resource.findOneAndUpdate(
    { id: req.params.id, deletedAt: null },
    { $set: req.body, version: resource.version + 1 },
    { new: true, upsert: false, setDefaultsOnInsert: true }
  );

  if (!resource) return res.status(404).json({ error: 'Resource not found' });
  if (resource.version !== req.body.version)
    return res.status(409).json({ error: 'Version mismatch, resource already updated' });

  // Logging and auditing
  resource.updatedAt = new Date();
  await resource.save();

  // Handle potential concurrency issues (database level)
  // ...

  res.status(200).json(resource);
});

// Delete resource (DELETE)
app.delete('/resources/:id', async (req, res) => {
  const resource = await Resource.findOneAndUpdate(
    { id: req.params.id, deletedAt: null },
    { $set: { deletedAt: new Date() } },
    { new: true }
  );

  if (!resource) return res.status(404).json({ error: 'Resource not found' });

  // Logging and auditing
  resource.deletedAt = new Date();
  await resource.save();

  // Handle potential concurrency issues (database level)
  // ...

  // Fetch additional metadata from external service
  try {
    const metadata = await axios.get(`https://external-service.com/metadata/${req.params.id}`);
    res.status(200).json({ ...resource.toJSON(), metadata: metadata.data });
  } catch (error) {
    console.error(error);
    res.status(503).json({ error: 'External service unavailable' });
  }
});
