import com.bumptech.glide.request.transition.Transition;

import java.io.FileInputStream;
import java.io.IOException;
import java.io.ObjectInputStream;
import java.lang.reflect.Type;
import java.util.concurrent.ConcurrentHashMap;
import java.util.concurrent.ExecutorService;
import java.util.concurrent.Executors;

@AutoValue
abstract class MoSTState {
    abstract String getThemeName();
    abstract Bitmap getThemeBitmap();
}

public class StateLoader {
    private static final String CACHE_ROOT = "theme_cache";
    private static final ExecutorService executor = Executors.newSingleThreadExecutor();
    private static final ConcurrentHashMap<String, MoSTState> themeCache = new ConcurrentHashMap<>();

    public static MoSTState loadTheme(Resources resources, String themeName) {
        synchronized (themeCache) {
            MoSTState cachedTheme = themeCache.get(themeName);
            if (cachedTheme != null) {
                return cachedTheme;
            }

            HandlerThread handlerThread = new HandlerThread("ThemeLoader");
            handlerThread.start();
            Runnable loadTask = () -> {
                try {
                    FileInputStream fileInputStream = resources.openRawResource(getThemeFileId(themeName));
                    BufferedSource source = Okio.buffer(Okio.source(fileInputStream));
                    ObjectInputStream objectInput = new ObjectInputStream(source);
                    MoSTState mostState = (MoSTState) objectInput.readObject();
                    objectInput.close();

                    Bitmap themeBitmap = mostState.getThemeBitmap();
                    Glide.with(resources).asBitmap().load(themeName).into(new SimpleTarget<Bitmap>() {
                        @Override
                        public void onResourceReady(@Nullable Bitmap resource, Transition<? super Bitmap> transition) {
                            mostState = MoSTState.builder().setThemeBitmap(resource).build();
                            themeCache.putIfAbsent(themeName, mostState);
                        }
                    });

                } catch (IOException | ClassNotFoundException e) {
                    // Handle exceptions gracefully and return null if deserialization fails
                }
            };
            executor.submit(loadTask);
            return null;
        }
    }

    private static int getThemeFileId(String themeName) {
        // Implement a mapping between theme names and resource IDs for PNG files
    }
}
```

