[' Here's a modularized JavaScript function that meets the requirements:

```javascript
// config.json
{
  "excludedStatusCodes": [418, 599]
}

const fs = require('fs');
const readline = require('readline');

function countHttpStatusCodes(filePath) {
  const excludedStatusCodes = JSON.parse(fs.readFileSync('config.json', 'utf-8')).excludedStatusCodes;
  let statusCodeCounts = {};

  const rl = readline.createInterface({
    input: fs.createReadStream(filePath),
    console: false
  });

  rl.on('line', (line) => {
    if (!line.includes('HTTP/')) return; // Skip non-HTTP lines

    const statusCode = line.match(/HTTP\/\d+\s+(\d{3})/)[1];

    if (excludedStatusCodes.includes(parseInt(statusCode))) return; // Skip excluded status codes

    if (!statusCodeCounts[`${statusCode}-${String(statusCode).length}`]) {
      statusCodeCounts[`${statusCode}-${String(statusCode).length}`] = 0;
    }

    statusCodeCounts[`${statusCode}-${String(statusCode).length}`]++;
  });

  rl.on('close', () => {
    let total = 0;
    for (const [key, value] of Object.entries(statusCodeCounts)) {
      total += value;
      console.log(`${key}: ${value}`);
    }
    console.log(`Total: ${total}`);
  });
}

countHttpStatusCodes('path_to_your_logfile.log');
```

This code reads a configuration file to exclude certain status codes, processes the log file line by line, and counts HTTP status codes based on their numerical ranges. It handles malformed or incomplete log entries by skipping non-HTTP lines. The function is designed to be extensible, allowing for easy addition of new status code ranges or exclusion criteria without significant refactoring.

To optimize for both speed and memory usage, the function uses a readline stream to process the file line by line instead of loading the entire file into memory at once. This makes it suitable for handling large files without consuming excessive memory or processing time.']

