```javascript
function generateFooter(scripts) {
  const footer = scripts
    .filter(({ include, environment }) => (environment === 'all' || environment === process.env.NODE_ENV))
    .map(({ id, type, code, attributes }) => {
      let scriptTag = `<script`;

      if (id) scriptTag += ` id="${id}"`;
      if (type) scriptTag += ` type="${type}"`;
      if (attributes) Object.entries(attributes).forEach(([key, value]) => (scriptTag += ` ${key}="${value}"`));

      scriptTag += `>${code}</script>`;

      return scriptTag;
    })
    .join('');

  return footer;
}
