    return Observable.forkJoin(requests).pipe(
      map(() => {}), // Empty result since we're only updating the UI
      catchError((error: HttpErrorResponse) => {
        console.error('An error occurred while fetching data:', error);
        return of(null);
      })
    );
  }

  private fetchData(fieldName: string): Observable<any> {
    if (this.cache[fieldName]) {
      return of(this.cache[fieldName]);
