    const url = `${this.apiUrl}/${fieldName}`;
    return this.http.get(url).pipe(
      map(data => {
        this.cache[fieldName] = data;
        return data;
      }),
      catchError((error: HttpErrorResponse) => {
        console.error('An error occurred while fetching data for field:', fieldName, error);
        return of(null);
      })
    );
