use reqwest::{Client, RequestBuilder};
use std::collections::HashMap;
use std::sync::Arc;
use log::{debug, error};
use tokio::sync::RwLock;

// Define a Configuration struct for environment-specific settings
#[derive(Debug)]
struct Config {
    base_urls: Vec<String>,
    timeout: u128,
    max_connections: usize,
    max_requests: usize,
    headers: HashMap<String, String>,
    proxy: Option<String>,
    auth: Option<(String, String)>,
}

// Create a Client struct with an inner RwLock for concurrent access
struct Client {
    config: Arc<RwLock<Config>>,
    client: Client,
}

impl Client {
    async fn new(config: Config) -> Self {
        let config = Arc::new(RwLock::new(config));
        let client = Client::builder()
            .timeout(std::time::Duration::from_secs_f64(config.read().await.timeout as u64))
            .keep_alive(std::time::Duration::from_secs(15)) // Keep-alive for idle connections
            .build();

        if let Some(ref proxy) = config.read().await.proxy {
            client = client.proxy(reqwest::Proxy::http(proxy)).unwrap();
        }

        if let Some((username, password)) = config.read().await.auth {
            client = client.basic_auth(username, password);
        }

        Self { config, client }
    }

    async fn execute(&self, request: RequestBuilder) -> Result<reqwest::Response, reqwest::Error> {
        let headers = self.config.read().await.headers;
        let mut builder = request.headers(headers);

        // Implement retry logic and circuit breaker here

        self.client.execute(builder).await
    }
}

// Define a Request struct for customizing requests
