[' Here's a Rust function that integrates with a third-party build system (assumed to be CMake) to compile a set of custom Rust crates. The function uses `subprocess` and `tempfile` crates for managing subprocesses and temporary files respectively. It also utilizes a custom logging hook based on the C-style logging mechanism with `snprintf` and `va_start/va_end`.

```rust
use std::env;
use std::fs::{self, File};
use std::io::{BufWriter, Write};
use std::os::unix::prelude::AsRawFd;
use std::process::{Command, Stdio};
use tempfile::TempDir;
use log::{LevelFilter, SetLoggerError, LogSetHooks, LogBuilder, LogFormatter, LogLevel};
use log4rs::{append::file::RollingFileAppender, config::Configurer, encode::pattern::PatternEncoder};

const LOG_FILE: &str = ".build/log.txt";

fn compile(crates: &[&str]) -> i32 {
    let mut log_level = LevelFilter::Info;
    let temp_dir = TempDir::new_in(".").unwrap();

    // Set up logging
    let log_file = temp_dir.path().join(LOG_FILE);
    let roller = RollingFileAppender::builder()
        .encoder(Box::new(PatternEncoder::new("{d/MMM/yy H:mm:ss.SSS} [{level}] {message}\n")))
        .file(log_file)
        .build();
    let log_config = Configurer::builder()
        .appenders(vec![roller])
        .build(LogBuilder::new().filter(Some("rust_build"), LogLevel::Off))
        .unwrap();
    log_config.init().map_err(|e| {
        eprintln!("Failed to initialize logger: {}", e);
        std::process::exit(1);
    })
    .unwrap();

    let cmake_list = temp_dir.path().join("CMakeLists.txt");
    fs::write(&cmake_list, format!(
        "cmake_minimum_required(VERSION 3.0)\nadd_subdirectory({})\n",
        crates.iter().map(|c| c.to_string()).collect::<Vec<String>>().join(" ")
    ))
    .unwrap();

    let mut cmd = Command::new("cmake")
        .arg("-DCMAKE_BUILD_TYPE=Release")
        .arg("-H.")
        .arg("-Bbuild")
        .current_dir(temp_dir.path())
        .stdout(Stdio::piped())
        .stderr(Stdio::piped());
    let output = cmd.output().expect("Failed to execute cmake");
    if !output.status.success() {
        eprintln!("cmake failed with status: {}", output.status);
        std::process::exit(1);
    }

    let mut build_cmd = Command::new("cmake")
        .arg("-Bbuild")
        .arg("--build")
        .current_dir(temp_dir.path())
        .stdout(Stdio::null())
        .stderr(Stdio::piped());
    let mut build_output = build_cmd.stderr.take().unwrap();
    let mut build_error = String::new();
    build_output.read_to_string(&mut build_error).expect("Failed to read build output");

    if log_level >= LevelFilter::Debug {
        println!("Build command: {}", build_cmd.get_command());
        println!("Build error: {}", build_error);
    }

    let exit_code = build_cmd.spawn().unwrap().wait().expect("Failed to execute build");

    // Clean up temporary files and log file
    temp_dir.into_path();
    fs::remove_file(log_file).unwrap();

    exit_code.code().unwrap()
}
```

This function creates a temporary directory, sets up logging, generates a CMakeLists.txt file for the given crates, executes cmake and build commands, measures the compilation time and resident set size of the process (not directly in this example), and cleans up temporary files after execution. The log level can be adjusted for debugging purposes.']

