#include <arpa/inet.h>
#include <netdb.h>
#include <stdio.h>
#include <stdlib.h>

int dns_resolve(const char *hostname, u_char **ipAddress) {
    struct hostent *host = gethostbyname(hostname);

    if (!host) {
        perror("gethostbyname");
        return 1;
    }

    *ipAddress = malloc(host->h_length);
    memcpy(*ipAddress, host->h_addr_list[0], host->h_length);

    return 0;
}
