      done();
    });
  });

  it('should handle non-numeric values gracefully', function(done) {
    const arr = ['3', '7', '5'];
    const initialValue = 0;
    const callback = (acc, val) => {
      if (typeof val !== 'number') return Promise.resolve(acc);
      return Promise.resolve(acc + val);
    };
    asyncReduce(arr, initialValue, callback, 2).then((result) => {
      assert.strictEqual(result, 8);
      done();
    });
  });

  it('should handle high concurrency demands', function(done) {
    const arr = Array.from({ length: 10000 }, (_, i) => i + 1);
    const initialValue = 0;
    const callback = (acc, val) => acc + val;
    asyncReduce(arr, initialValue, callback, 100).then((result) => {
