[' Here's the C code for initializing an AES-256-CBC cipher, managing bitmaps, and implementing error handling, cleanup functions:

```c
#include <openssl/aes.h>
#include <openssl/sha.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <sys/stat.h>
#include <sys/types.h>

typedef struct {
    AES_KEY key;
    unsigned char iv[AES_BLOCK_SIZE];
} aes_ctx;

aes_ctx* aes_init(const char *password) {
    unsigned char password_hash[SHA256_DIGEST_LENGTH];
    SHA256_CTX ctx;
    SHA256_Init(&ctx);
    SHA256_Update(&ctx, (unsigned char*)password, strlen(password));
    SHA256_Final(password_hash, &ctx);

    AES_KEY key;
    AES_set_encrypt_key(password_hash, 256, &key);

    unsigned char iv[AES_BLOCK_SIZE];
    memset(iv, 0, AES_BLOCK_SIZE);
    aes_ctx *ctx = malloc(sizeof(aes_ctx));
    memcpy(ctx->iv, iv, AES_BLOCK_SIZE);
    memcpy(ctx->key.key, key.key, sizeof(key.key));
    return ctx;
}

void aes_cleanup(aes_ctx *ctx) {
    free(ctx);
}

