using System.Threading;
using System.Threading.Tasks;
using Microsoft.Win32;

public class WebsiteManager
{
    private readonly ConcurrentDictionary<string, Task> _tasks = new ConcurrentDictionary<string, Task>();
    private readonly IConfigurationService _configurationService;
    private readonly IProcessManager _processManager;
    private readonly ILogger _logger;

    public WebsiteManager(IConfigurationService configurationService, IProcessManager processManager, ILogger logger)
    {
        _configurationService = configurationService;
        _processManager = processManager;
        _logger = logger;
    }

    public DirectoryEntry AddWebsite(string directoryPath)
    {
        if (!Directory.Exists(directoryPath))
            return new DirectoryEntry { Success = false, Message = "Invalid directory path." };

        var webConfigFile = Path.Combine(directoryPath, "web.config");
        if (!File.Exists(webConfigFile))
            return new DirectoryEntry { Success = false, Message = "Missing web.config file." };

        string configData;
        try
        {
            configData = _configurationService.GetConfiguration(directoryPath);
        }
        catch (Exception ex)
        {
            _logger.LogError($"Failed to fetch configuration for directory: {directoryPath}", ex);
            return new DirectoryEntry { Success = false, Message = "Failed to fetch configuration." };
        }

        var websiteConfig = DeserializeWebsiteConfig(configData);
        if (websiteConfig == null)
        {
            _logger.LogWarning($"Invalid configuration for directory: {directoryPath}");
            return new DirectoryEntry { Success = false, Message = "Invalid configuration." };
        }

        lock (_tasks)
        {
            if (_tasks.ContainsKey(websiteConfig.Id))
                return _tasks[websiteConfig.Id]; // Return existing task if it exists
        }

        var task = StartWebsiteAsync(directoryPath, websiteConfig);
        _tasks[websiteConfig.Id] = task;
        return task;
    }

    private async Task<DirectoryEntry> StartWebsiteAsync(string directoryPath, WebsiteConfig websiteConfig)
    {
        try
        {
            var processResult = await _processManager.StartProcessAsync(directoryPath, websiteConfig);
            if (processResult.Success)
                return new DirectoryEntry { Success = true };

            // Handle timeout or other failures here and gracefully terminate existing processes if needed
        }
        catch (Exception ex)
        {
            _logger.LogError($"Failed to start website for directory: {directoryPath}", ex);
        }

        return new DirectoryEntry { Success = false, Message = "Failed to start website." };
    }

    // Implement deserialization of the web.config here
}
```

