#include <stdlib.h>
#include <time.h>
#include "jwt-c/jwt.h"

// Load configuration from a file
void load_config(const char *filename, jwt_issuer_t **trusted_domains);

// Check if the given domain is trusted
bool is_trusted_domain(const char *domain, const jwt_issuer_t *trusted_domains);

// Validate JWT claims
bool validate_claims(jwt_t *jwt, const jwt_issuer_t *issuer);

// Check if the expiration time is valid
bool is_future_date(time_t current_time, int exp);

// Main function to process and verify JWT
bool validate_jwt(const char *token, const char *secret_key, const char *config_filename) {
    jwt_t *jwt = NULL;
    jwt_issuer_t *trusted_domains = NULL;
    bool result = false;

    // Load configuration
    load_config(config_filename, &trusted_domains);

    // Parse the JWT string
    jwt = jwt_parse((char *)token, strlen(token));
    if (!jwt) {
        fprintf(stderr, "Error parsing JWT\n");
        goto cleanup;
    }

    // Check if the issuer is trusted and has the required claims
    if (is_trusted_domain(jwt->header.iss, trusted_domains) && validate_claims(jwt, trusted_domains)) {
        // Verify the signature with the secret key
        result = jwt_verify(jwt, secret_key);
        if (!result) {
            fprintf(stderr, "Error verifying JWT signature\n");
            goto cleanup;
        }

        // Check if the expiration time is valid
        if (is_future_date(time(NULL), jwt->header.exp)) {
            result = true;
        } else {
            fprintf(stderr, "Expired JWT\n");
        }
    } else {
        fprintf(stderr, "Invalid or missing claims\n");
    }

cleanup:
