public string DecryptMessage(string base64EncodedMessage)
{
    var messageParts = base64EncodedMessage.Split(':'); // Split the message into header and body
    var header = messageParts[0];
    var body = messageParts[1];

    var performanceStopwatch = new Stopwatch();
    performanceStopwatch.Start();

    string decryptionMethod;
    byte[] key;
    var hmacKey = new HMACSHA256(); // Initialize HMAC SHA-256 for integrity check

