using System;
using System.Collections.Generic;
using System.Linq;
using System.Security.Cryptography;
using Ace.Cryptography;
using Microsoft.Extensions.Configuration;
using Microsoft.Extensions.Logging;

public class ConfigManager
{
    private readonly IConfiguration _config;
    private readonly ILogger<ConfigManager> _logger;
    private readonly Dictionary<string, (Aes Aes, byte[] IV)> _aesInstances = new();

    public ConfigManager(IConfiguration config, ILogger<ConfigManager> logger)
    {
        _config = config;
        _logger = logger;
    }

    public T GetEncryptedValue<T>(string section, string key)
    {
        var encryptedValue = _config[section][key];
        if (!_aesInstances.TryGetValue(section, out var (Aes aes, byte[] iv)))
        {
            GenerateKeyAndIV(section);
        }

        using (var ms = new MemoryStream(Convert.FromBase64String(encryptedValue)))
        {
            using (var decryptor = aes.CreateDecryptor())
            {
                using (var cs = new CryptoStream(ms, decryptor, CryptoStreamMode.Read))
                {
                    var data = new byte[cs.ReadByte()];
                    cs.Read(data, 0, data.Length);
                    return JsonSerializer.Deserialize<T>(data);
                }
            }
        }
    }

    public void SetEncryptedValue<T>(string section, string key, T value)
    {
        if (!_aesInstances.TryGetValue(section, out var (Aes aes, byte[] iv)))
        {
            GenerateKeyAndIV(section);
        }

        using (var ms = new MemoryStream())
        {
            using (var sw = new Utf8JsonWriter(ms))
            {
                JsonSerializer.Serialize(sw, value);
            }

            var encryptedData = Encrypt(aes, iv, ms.ToArray());
            _config[section][key] = Convert.ToBase64String(encryptedData);
        }
    }

    private void GenerateKeyAndIV(string section)
    {
        using (var rngCsp = new RNGCryptoServiceProvider())
        {
            var keyBytes = new byte[32];
            var ivBytes = new byte[16];
            rngCsp.GenerateBlock(keyBytes, 0, keyBytes.Length);
            rngCsp.GenerateBlock(ivBytes, 0, ivBytes.Length);

            _aesInstances[section] = (Aes.Create(), ivBytes);
        }
    }

    private byte[] Encrypt(Aes aes, byte[] iv, byte[] data)
    {
        using (var encryptor = aes.CreateEncryptor())
        {
            using (var ms = new MemoryStream())
            {
                using (var cs = new CryptoStream(ms, encryptor, CryptoStreamMode.Write))
                {
                    using (var cryptoTransform = new PKCS7PaddingTransformer(encryptor))
                    {
                        cryptoTransform.TransformBlock(data, 0, data.Length, ms, 0);
                        cryptoTransform.FlushFinalBlock();
                    }
                }

                return ms.ToArray().Concat(iv).ToArray();
            }
        }
    }
}
```

This implementation uses the Ace.Cryptography library for encryption and decryption, Microsoft.Extensions.Configuration for configuration management, and Microsoft.Extensions.Logging for logging purposes. The `ConfigManager` class manages multiple sections concurrently, ensuring each service instance has its own key and IV generation securely.

Unit tests can be written using xUnit or MSTest to validate the correctness of encryption and decryption processes, covering typical and atypical use cases."]

