5. Create a web interface using Express.js for displaying the health status of each server. Use EJS templates for customizable dashboard views and handle alert notifications based on user-defined thresholds.
6. Design the system to be scalable by using process managers like PM2 or cluster modules to manage multiple instances of your application.
7. Optimize resource usage by dynamically adjusting the number of concurrent requests using load balancing strategies such as round-robin, least connections, or consistent hashing. You can use libraries like `hapijs` or custom implementations for this purpose.

Here's a basic example of how you might structure your health check function:

```javascript
const axios = require('axios');
const json5 = require('json5');
const lruCache = require('lru-cache');
const express = require('express');
const app = express();

// Initialize cache with 100 items and a 60 seconds expiration time
const cache = lruCache({ max: 100, maxAge: 60000 });

function healthCheck(url) {
  return new Promise((resolve, reject) => {
    // Check if the response is in the cache
    const cachedResponse = cache.get(url);
    if (cachedResponse) {
      resolve(cachedResponse);
      return;
    }

    axios.get(url)
      .then((response) => {
        // Parse non-standard JSON responses using json5
        const parsedResponse = json5.parse(response.data);
        // Extract relevant health metrics based on server-specific response codes
        if (parsedResponse.statusCode === 200) {
          resolve({ status: 'healthy', data: parsedResponse });
        } else {
          resolve({ status: 'unhealthy', data: parsedResponse });
        }
      })
      .catch((error) => {
        reject(error);
      })
      .finally(() => {
        // Cache the response for future use
        cache.set(url, { status: 'unhealthy', data: error });
      });
  });
}

// Example route to check server health
app.get('/health-check/:server', async (req, res) => {
  try {
    const result = await healthCheck(`http://${req.params.server}/health`);
    res.json(result);
  } catch (error) {
    res.status(500).send('Error while checking server health');
  }
});

// Start the Express server on port 3000
app.listen(3000, () => console.log('Server started on port 3000'));
```"]

