[' Due to the complexity of your request, I'll provide you with separate functions for DNS resolution, DNS caching, connection establishment, and error handling in C++ (as it supports Java Channel) and a simplified Java class for managing connections.

C++:

```cpp
#include <iostream>
#include <string>
#include <unordered_map>
#include <arpa/inet.h>
#include <resolv.h>
#include <sys/socket.h>
#include <netdb.h>
#include <poll.h>
#include <cstdlib>
#include <csignal>
#include <jni.h>

struct DnsCache {
    std::unordered_map<std::string, in_addr_t> cache;
    int ttl = 60; // Time to live (seconds)
};

int resolve(const std::string& hostname, DnsCache* cache) {
    struct hostent *he;
    struct in_addr **addr_list;
    int res = gethostbyname_r(hostname.c_str(), nullptr, nullptr, &he, &addr_list);

    if (res != 0 && h_errno != HOST_NOT_FOUND) { // Error occurred
        return -1;
    }

    if (res == HOST_NOT_FOUND) { // Hostname not found in DNS cache or DNS server
        return -2;
    }

    in_addr_t ip = addr_list[0]->a_addr.ipv4.s_addr;

    if (cache->cache.find(hostname) != cache->cache.end()) { // Check for cached IP address
        auto it = cache->cache.find(hostname);
        if ((time(nullptr) - it->second) <= cache->ttl) {
            ip = it->second;
        } else {
            cache->cache.erase(it); // Remove expired entry from the cache
        }
    }

    cache->cache[hostname] = time(nullptr); // Update DNS cache with current timestamp
    return ip;
}

// Java Channel connection establishment and management (Java code)
public class ConnectionManager {
    private final Selector selector;
    private final SocketChannel[] connections;

    public ConnectionManager(int maxConnections) {
        try {
            selector = Selector.open();
            connections = new SocketChannel[maxConnections];
        } catch (IOException e) {
            throw new RuntimeException("Failed to initialize connection manager", e);
        }
    }

    public void connect(String hostname, int port) throws IOException {
        SocketChannel channel = SocketChannel.open();
        channel.configureBlocking(false);
        channel.connect(new InetSocketAddress(hostname, port));
        connections[connections.length - 1] = channel;
        selector.register(channel.selectionKey(), SelectionKey.OP_CONNECT);
    }

    public void process() throws IOException {
        selector.select();
        Iterator<SelectionKey> it = selector.selectedKeys().iterator();
        while (it.hasNext()) {
            SelectionKey key = it.next();
            it.remove();

            SocketChannel channel = (SocketChannel) key.channel();
            if (key.isValid() && key.isConnectable()) { // Connection is established
                channel.finishConnect();
                key.interestOps(SelectionKey.OP_READ);
            } else if (key.isValid() && key.isReadable()) { // Data can be read from the connection
                ByteBuffer buffer = ByteBuffer.allocate(1024);
                channel.read(buffer);
                buffer.flip();
                while (buffer.hasRemaining()) {
                    System.out.print((char) buffer.get());
                    buffer.compact();
