        MD5_Update(md5_, str.c_str(), static_cast<unsigned int>(str.length()));
        MD5_Final(digest, md5_);
        std::stringstream ss;
        for (size_t i = 0; i < MD5_DIGEST_LENGTH; ++i) {
            ss << std::hex << std::setw(2) << std::uppercase << static_cast<int>(digest[i]);
        }
        return ss.str();
