                if (res == CURLE_OK) {
                    data.resize(size);
                    res = curl_easy_getinfo(curl, CURLINFO_DATA, &data[0]);
                }
            } while (res != CURLE_OK && res != CURLE_OPERATION_TIMEDOUT);

            if (res == CURLE_OK) {
