```csharp
using System;
using System.Collections.Generic;
using System.Linq;
using System.Net;
using System.Text;
using System.Threading.Tasks;
using Microsoft.AspNetCore.Http;
using Microsoft.Extensions.Logging;
using Microsoft.Extensions.Options;

public class RequestHandler
{
    private readonly ILogger<RequestHandler> _logger;
    private readonly RateLimiter _rateLimiter;
    private readonly AuditTrail _auditTrail;
    private readonly ServiceLayer _serviceLayer;

    public RequestHandler(ILogger<RequestHandler> logger, IOptions<RateLimiterOptions> rateLimiterOptions, ServiceLayer serviceLayer, AuditTrail auditTrail)
    {
        _logger = logger;
        _rateLimiter = new RateLimiter(rateLimiterOptions);
        _serviceLayer = serviceLayer;
        _auditTrail = auditTrail;
    }

    public async Task HandleRequestAsync(HttpContext context)
    {
        if (!_rateLimiter.IsAllowed(context.Connection.RemoteIpAddress))
        {
            await SendErrorResponseAsync(context, "Rate limit exceeded.");
            return;
        }

        var sectionId = context.Request.Query["section"].FirstOrDefault();
        var elementId = context.Request.Query["element"].FirstOrDefault();
        var newContent = Encoding.UTF8.GetString(context.Request.Body.ToArray());

        if (string.IsNullOrEmpty(sectionId) || string.IsNullOrEmpty(elementId) || string.IsNullOrWhiteSpace(newContent))
        {
            await SendErrorResponseAsync(context, "Invalid input.");
            return;
        }

        if (!ValidateOrigin(context.Request.Headers["Referer"].FirstOrDefault()))
        {
            await SendErrorResponseAsync(context, "Untrusted origin.");
            return;
        }

        try
        {
            await _serviceLayer.UpdateElementContentAsync(sectionId, elementId, newContent);
            _auditTrail.AddEntry(sectionId, elementId, newContent);
        }
        catch (Exception ex)
        {
            _logger.LogError(ex, "Failed to update element content.");
            await SendErrorResponseAsync(context, "Internal server error.");
            return;
        }

        await context.Response.WriteAsync("{\"message\": \"Page should be refreshed after the update.\"}");
    }

    private bool ValidateOrigin(string referer) => new Uri(referer).Host == "trusted-domain.com";

    private async Task SendErrorResponseAsync(HttpContext context, string errorMessage)
    {
        await context.Response.WriteAsync($"{{\"error\": \"{errorMessage}\"}}");
        await context.Response.Complete();
    }
}
```

This code includes a `RequestHandler` class that handles HTTP POST requests, validates the request origin, implements logging for failed attempts, and updates the element's HTML content using a service layer. It also maintains an audit trail for recent updates and provides a rate-limiting mechanism to prevent abuse. The function returns a generic error message for invalid inputs or untrusted origins.']

