        .filename = strdup(filename),
        .filename_len = strlen(filename),
        .numbers = NULL,
        .numbers_capacity = 0,
        .numbers_size = 0,
    };

    time_t now;
    struct tm *tm = localtime(&now);
    char timestamp[19];
    strftime(timestamp, sizeof(timestamp), "%Y%m%d%H%M%S", tm);

    int random = rand() % 10000;

    char filetype[5];
    if (strchr(filename, 'a')) {
        strcpy(filetype, ".txt");
    } else if (strchr(filename, 'b')) {
        strcpy(filetype, ".csv");
    } else {
        strcpy(filetype, ".log");
    }

    size_t new_len = data.filename_len + strlen(timestamp) + strlen(random) + strlen(filetype);
    data.filename = realloc(data.filename, new_len + 1);

    sprintf(data.filename + data.filename_len, "_%s%04d%s", timestamp, random, filetype);

    int largest = helper(&data);
    free(data.filename);
    free(data.numbers);

    return (char *)malloc(sizeof(int) * largest + 1);
}
