#include <curl/curl.h>
#include <stdbool.h>

typedef struct {
    char mac[18];
    char ip[16];
    char mask[10];
} NetworkConfig;

typedef struct {
    pthread_mutex_t lock;
    size_t size;
    NetworkConfig* data;
    bool cached;
    FILE* file;
} ConfigManager;

ConfigManager cm = { .size = 0, .data = NULL, .cached = false };

static size_t writeFunc(void *ptr, size_t size, size_t nmemb, void *userp) {
    size_t totalSize = size * nmemb;
    ((char*)userp) += totalSize;
    return totalSize;
}

static int readFile(const char* path, char** data, size_t* size) {
    FILE* file = fopen(path, "rb");
    if (!file) return -1;

    fseek(file, 0, SEEK_END);
    *size = ftell(file);
    rewind(file);

    *data = malloc(*size + 1);
    size_t result = fread(*data, *size, 1, file);
    if (result != 1) {
        free(*data);
        return -1;
    }
    (*data)[*size] = '\0';

    fclose(file);
    return 0;
}

static CURLcode fetchConfig(const char* url, char** data, size_t* size) {
    CURL* curl = curl_easy_init();
    if (!curl) return CURLE_FAILED_INIT;

    CURLcode res;
    curl_easy_setopt(curl, CURLOPT_URL, url);
    curl_easy_setopt(curl, CURLOPT_WRITEFUNCTION, writeFunc);
    curl_easy_setopt(curl, CURLOPT_WRITEDATA, data);

    res = curl_easy_perform(curl);
    if (res != CURLE_OK) {
        curl_easy_cleanup(curl);
        return res;
    }

    size_t len;
    res = curl_easy_getinfo(curl, CURLINFO_RESPONSE_CODE, &len);
    if (res != CURLE_OK || len != 200) {
        curl_easy_cleanup(curl);
        return res;
    }

    curl_easy_getinfo(curl, CURLINFO_CONTENT_LENGTH_DOWNLOAD_TOTAL, size);
    (*data)[*size] = '\0';
    curl_easy_cleanup(curl);
    return CURLE_OK;
}

static void validateConfig(NetworkConfig* config) {
    // Validate MAC address format (e.g., 00:11:22:33:44:55)
    if (strlen(config->mac) != 17 || strchr(config->mac, ':') == NULL) {
        fprintf(stderr, "Invalid MAC address format\n");
        exit(EXIT_FAILURE);
    }

    // Validate IP address format (e.g., 192.168.1.1)
    char ip[INET_ADDRSTRLEN];
    inet_pton(AF_INET, config->ip, (void*)&((struct in_addr*){0}));
    inet_ntop(AF_INET, (void*)&((struct in_addr*){0}), ip, sizeof(ip));
    if (strlen(config->ip) != strlen(ip)) {
        fprintf(stderr, "Invalid IP address format\n");
        exit(EXIT_FAILURE);
    }

    // Validate subnet mask format (e.g., 255.255.255.0)
    char mask[INET_ADDRSTRLEN];
    inet_pton(AF_INET, config->mask, (void*)&((struct in_addr*){0xFFFFFFFF}));
    inet_ntop(AF_INET, (void*)&((struct in_addr*){0xFFFFFFFF}), mask, sizeof(mask));
    if (strlen(config->mask) != strlen(mask)) {
        fprintf(stderr, "Invalid subnet mask format\n");
        exit(EXIT_FAILURE);
    }
}

static void lockManager() { pthread_mutex_lock(&cm.lock); }
static void unlockManager() { pthread_mutex_unlock(&cm.lock); }

void networkConfigManager() {
    char* configData = NULL;
    size_t configSize = 0;

    if (!cm.cached) {
        const char* url = "http://example.com/config"; // Replace with your API endpoint
        CURLcode res = fetchConfig(url, &configData, &configSize);
        if (res != CURLE_OK) {
            fprintf(stderr, "Error fetching configuration: %s\n", curl_easy_strerror(res));
            exit(EXIT_FAILURE);
        }
        cm.cached = true;
    }

    if (readFile("config.txt", &configData, &configSize) != 0) {
        fprintf(stderr, "Error reading configuration file\n");
        exit(EXIT_FAILURE);
    }

    NetworkConfig* newData = realloc(cm.data, sizeof(NetworkConfig) * (cm.size + 1));
    if (!newData) {
        fprintf(stderr, "Memory allocation error\n");
        exit(EXIT_FAILURE);
    }
    cm.data = newData;

    lockManager();

    char* token = strtok(configData, "\n");
    for (size_t i = 0; i < configSize; ++i) {
        NetworkConfig* config = &cm.data[cm.size];
        strcpy(config->mac, token);
        token = strtok(NULL, ":");
        strcpy(config->ip, token);
        token = strtok(NULL, ":");
        strcpy(config->mask, token);

        validateConfig(config);

        for (size_t j = 0; j < cm.size; ++j) {
            if (!strcmp(cm.data[j].mac, config->mac)) {
                fprintf(stderr, "Duplicate MAC address found\n");
                exit(EXIT_FAILURE);
            }
        }

        ++cm.size;

        token = strtok(NULL, "\n");
        if (!token) break;
    }

    free(configData);
    unlockManager();
}
