size_t countVowels(const char *str) {
    size_t count = 0;
    for (size_t i = 0; str[i]; ++i) {
        if (tolower(str[i]) == 'a' || tolower(str[i]) == 'e' ||
            tolower(str[i]) == 'i' || tolower(str[i]) == 'o' ||
            tolower(str[i]) == 'u') {
            ++count;
        }
    }
    return count;
}

char* generateNewFilename(const char *original) {
    size_t len = strlen(original);
    if (len < 5 || len > 100 || len % 3 != 0) {
        return ""; // Invalid filename
    }

    char prefix[4];
    strncpy(prefix, original, 3);
    prefix[3] = '\0';

    size_t vowelCount = countVowels(original);
    size_t extensionLength = (vowelCount > 0) ? vowelCount + 2 : 5;

    char *extension = malloc(extensionLength);
    snprintf(extension, extensionLength, ".%c%d", 'A' + rand() % 26, vowelCount > 0 ? vowelCount : 5);

    size_t specialCharsCount = 0;
    for (size_t i = 0; original[i]; ++i) {
        if (!isalnum(original[i]) && original[i] != '.') {
            ++specialCharsCount;
        }
    }

    size_t newFilenameLength = strlen(prefix) + strlen(extension) + specialCharsCount;
    char *newFilename = malloc(newFilenameLength + len);

    strcpy(newFilename, prefix);
    strcat(newFilename, extension);

    if (specialCharsCount > 0) {
        for (size_t i = len - 1; i > 0 && specialCharsCount > 0; --i) {
            if (!isalnum(original[i]) && original[i] != '.') {
                newFilename[strlen(newFilename)] = original[i];
                --specialCharsCount;
            }
        }
    }

    return newFilename;
}
