[' Here's a simplified C++ example using modern C++ features, including `nlohmann::json` library for JSON parsing, `std::shared_ptr` for managing memory, and `std::mutex` for atomic operations. The semaphore is managed with `boost::lockfree::spsc_queue`.

```cpp
#include <iostream>
#include <nlohmann/json.hpp>
#include <vector>
#include <memory>
#include <mutex>
#include <boost/lockfree/spsc_queue.hpp>
#include <thread>
#include <atomic>

using json = nlohmann::json;
using Token = std::shared_ptr<struct AuthToken>;
struct AuthToken {
    int user_id;
    time_t expiration;
    // Session information
};

std::mutex tokens_mutex;
boost::lockfree::spsc_queue<Token> token_queue;
std::atomic<int> semaphore(0);

void initializeTokens(const json& config) {
    std::lock_guard<std::mutex> lock(tokens_mutex);

    for (auto& token : config.at("tokens")) {
        auto new_token = std::make_shared<AuthToken>();
        new_token->user_id = token["user_id"].get<int>();
        new_token->expiration = token["expiration"].get<time_t>();
        // Initialize session information
        token_queue.enqueue(new_token);
    }

    semaphore = config.at("semaphore").get<int>();
}

Token acquireToken() {
    Token result;

    if (!token_queue.try_dequeue(result)) {
        std::unique_lock<std::mutex> lock(tokens_mutex);
        token_queue.front().wait(lock);
        result = std::move(token_queue.front());
        token_queue.pop();
    }

    semaphore--;
    return result;
}

void releaseToken(Token token) {
    std::unique_lock<std::mutex> lock(tokens_mutex);
    token_queue.enqueue(std::move(token));
    semaphore++;
    lock.unlock();
    semaphore.notify_all();
}

void evictExpiredTokens() {
    std::vector<Token> expired_tokens;

    std::lock_guard<std::mutex> lock(tokens_mutex);

    for (auto& token : token_queue) {
        if (token->expiration < time(nullptr)) {
            expired_tokens.push_back(std::move(token));
        }
    }

    for (auto& token : expired_tokens) {
        token_queue.pop();
        delete token;
    }
}
```

This example demonstrates a basic structure for managing user authentication tokens in C++. It initializes the tokens from JSON, manages concurrent requests using a semaphore, and handles eviction of expired tokens. The code is not optimized for performance or memory usage, but it provides a good starting point for further improvements.']

