    return (c >= 'a' && c <= 'z') || (c >= 'A' && c <= 'Z');
}

void *generate_new_filename(void *data) {
    rename_data *rd = data;
    char *original_filename = rd->filename;
    char *new_filename = rd->new_filename;
    int len = strlen(original_filename);
    int file_type_len = 3; // "txt" or "log"
    int digits_count = 1;

    if (len < file_type_len + 2) {
        strcpy(new_filename, original_filename);
        return NULL;
    }

    char last_char = original_filename[len - 1];
    char second_to_last_char = original_filename[len - 2];

    if (isdigit(last_char)) {
        digits_count = last_char - '0';
        if (digits_count > 9) digits_count = 9;
        file_type_len++;
    } else if (isalpha(last_char)) {
        if (isdigit(second_to_last_char)) {
            strcpy(new_filename, original_filename);
            new_filename[len - file_type_len] = 't';
            new_filename[len - file_type_len + 1] = 'x';
            new_filename[len - file_type_len + 2] = 't';
        } else {
            strcpy(new_filename, original_filename);
            new_filename[len - file_type_len] = 'l';
            new_filename[len - file_type_len + 1] = 'o';
            new_filename[len - file_type_len + 2] = 'g';
        }
    }

    char temp_filename[257];
    snprintf(temp_filename, sizeof(temp_filename), "/tmp/new_%0*d_%s", digits_count, (int)strlen(original_filename - len + file_type_len), new_filename + len - file_type_len);
    strcpy(new_filename, temp_filename);

    return NULL;
}

void safe_rename(char *old_filename, char *new_filename) {
    pthread_t thread_id;
    rename_data rd = {old_filename, new_filename};
    int err = pthread_create(&thread_id, NULL, generate_new_filename, &rd);
    if (err != 0) {
        perror("pthread_create");
        exit(EXIT_FAILURE);
    }
}
