    let reader = BufReader::new(xml_file);
    let config: Vec<Element> = from_reader(reader).unwrap();

    // Find the first occurrence of the server configuration element
    let server_config = config.iter()
        .find(|element| element.name() == "server")
        .map_err(|e| format!("No server configuration found: {}", e))?;

    // Validate the server configuration and load settings
    if !validate_settings(server_config) {
        return Err("Invalid or incomplete server configuration".to_string());
    }

    let temp_dir_path = temp_dir.path().to_str().unwrap();

    // Validate the temporary file directory path
    if !validate_temp_dir_path(temp_dir_path) {
        error!("Invalid temporary file directory path: {}", temp_dir_path);
        return Err("Invalid temporary file directory path".to_string());
    }

    // Update the centralized configuration store with the validated temporary file directory path if necessary
