const sanitizeAttributeValue = (value) => {
  return value
    .replace(/<(?:[^>]|>\s+<)[^>]*>/g, '') // Remove any HTML tags
    .replace(/&(lt|gt|amp|quot|apos);/g, function (match) {
      const entities = { lt: '<', gt: '>', amp: '&', quot: '"', apost: "'" };
      return entities[match.slice(1)];
    });
};

const resolveDependencies = (scripts, dependencies) => {
  const scriptOrder = [];

  // Create a set to avoid duplicates and track processed scripts
  const processedScripts = new Set();

  // Iterate through the dependencies and recursively add dependent scripts
  for (const dependency of dependencies) {
    if (!processedScripts.has(dependency)) {
      processedScripts.add(dependency);
      scriptOrder.push(...resolveDependencies(scripts, scripts[dependency].dependencies));
    }
  }

  // Add the script itself to the order if it's not already included
  if (!processedScripts.has(scripts[dependency].id)) {
    processedScripts.add(scripts[dependency].id);
    scriptOrder.push(scripts[dependency]);
  }

  return scriptOrder;
};

const generateFooter = (config) => {
  const scripts = Object.values(config);
  const orderedScripts = scripts.reduce((acc, script) => {
    // Resolve dependencies and add the script to the appropriate position in the order
    acc = [...acc, ...resolveDependencies(scripts, script.dependencies)];
    return acc;
  }, []);

  let html = '';

  for (const script of orderedScripts) {
    const attributes = Object.entries(script.attributes || {})
      .map(([key, value]) => `${key}="${sanitizeAttributeValue(value)}"`)
      .join(' ');

    html += `<script${attributes}>${script.code}</script>`;
  }

  return html;
};
```

