@Service
public class DatabaseUpdater {
    @Autowired
    private ServiceLayer serviceLayer;

    private final Map<UUID, Record> cache = new ConcurrentHashMap<>();

    @LoadBalancerClient
    private final DistributedDatabase distributedDatabase;

    public DatabaseUpdater(@LoadBalancerClient(name = "distributed-database") DistributedDatabase distributedDatabase) {
        this.distributedDatabase = distributedDatabase;
    }

    public void updateRecords(String[] fieldNames, Function<Record, Record> updaterFunction) {
        for (Record record : distributedDatabase.getAllRecords()) {
            if (!cache.containsKey(record.getId())) {
                cache.put(record.getId(), record);
            }
            Record cachedRecord = cache.get(record.getId());
            if (matchesFields(fieldNames, cachedRecord, record)) {
                AsyncTask task = new AsyncTask(serviceLayer, updaterFunction, cachedRecord);
                Executors.newSingleThreadExecutor().submit(task);
            }
        }
    }

    private boolean matchesFields(String[] fieldNames, Record oldRecord, Record newRecord) {
        for (String fieldName : fieldNames) {
            if (!oldRecord.hasField(fieldName) || !newRecord.hasField(fieldName) || !Objects.equals(oldRecord.getField(fieldName), newRecord.getField(fieldName))) {
                return false;
            }
        }
        return true;
    }
}
