public class TransactionProcessor {
    private static final ExecutorService executor = Executors.newFixedThreadPool(10);
    private static final MessageDigest md5 = MessageDigest.getInstance("MD5");

    public CompletableFuture<SummaryReport> processTransactions(String input, List<UserTransaction> transactions) {
        Map<String, TransactionSummary> transactionSummaries = new HashMap<>();

        List<CompletableFuture<Void>> futures = transactions.stream()
                .map(transaction -> CompletableFuture.runAsync(() -> {
                    try {
                        processTransaction(transaction)
                            .ifPresentOrElse(summaries::put, logError);
                    } catch (Exception e) {
                        logError("Failed to process transaction: " + e.getMessage());
                    }
                }, executor))
                .limit(3) // Retry failed requests up to three times
                .collect(Collectors.toList());

        CompletableFuture.allOf(futures.toArray(new CompletableFuture[0]))
                .thenApply(__ -> generateSummaryReport(input, transactionSummaries))
                .exceptionally(e -> {
                    logError("Failed to generate summary report: " + e.getMessage());
                    return null;
                });

        return CompletableFuture.completedFuture(null);
    }

