    }

    private SummaryReport generateSummaryReport(String input, Map<String, TransactionSummary> transactionSummaries) {
        BigDecimal totalAmount = transactionSummaries.values().stream()
                .map(TransactionSummary::getTotalAmount)
                .reduce(BigDecimal.ZERO, BigDecimal::add);

        int depositCount = transactionSummaries.values().stream()
                .filter(ts -> ts.getType().equals("deposit"))
                .count();

        int withdrawalCount = transactionSummaries.values().stream()
                .filter(ts -> ts.getType().equals("withdrawal"))
                .count();

        byte[] inputBytes = input.getBytes(StandardCharsets.UTF_8);
        byte[] md5Hash = md5.digest(inputBytes);
        StringBuilder sb = new StringBuilder();
        for (byte b : md5Hash) {
            sb.append(String.format("%02x", b));
        }
        String md5Result = sb.toString();

        return new SummaryReport(totalAmount, depositCount, withdrawalCount, md5Result);
    }
}
