void* custom_malloc(size_t size) {
    void* ptr = malloc(size);
    if (!ptr) {
        fprintf(stderr, "Memory allocation failed\n");
        pthread_exit(NULL);
    }
    return ptr;
}

void init_arrays(Config config, long* offsets, int* keys, Record** records) {
    *offsets = (long*)custom_malloc(config.offset_size * sizeof(long));
    if (!*offsets) return;

    *keys = (int*)custom_malloc(config.key_size * sizeof(int));
    if (!*keys) {
        free(*offsets);
        pthread_exit(NULL);
    }

    *records = (Record*)custom_malloc(config.record_size * sizeof(Record));
    if (!*records) {
        free(*keys);
        free(*offsets);
        pthread_exit(NULL);
    }

    for (size_t i = 0; i < config.record_size; ++i) {
        (*records)[i].timestamp = time(NULL);
        (*records)[i].value = rand() % (config.max_value - config.min_value + 1) + config.min_value;
    }
}

void free_arrays(long* offsets, int* keys, Record** records) {
    if (offsets) free(offsets);
    if (keys) free(keys);
    if (*records) free(*records);
}
