```cpp
#include <iostream>
#include <vector>
#include <deque>
#include <mutex>
#include <atomic>
#include <thread>
#include <chrono>
#include <stdexcept>

struct SensorData {
    float temperature;
    float humidity;
    float pressure;
};

std::vector<SensorData> buffer;
std::deque<SensorData> input_queue;
std::mutex mtx;
std::atomic<size_t> processed_count(0);
std::atomic<size_t> lost_count(0);

void producer() {
    while (true) {
        SensorData data;
        // Fill the data structure with values from an external source.

        std::unique_lock<std::mutex> lock(mtx);
        input_queue.push_back(data);
        lock.unlock();

        std::this_thread::sleep_for(std::chrono::milliseconds(10)); // Simulate latency

        if (input_queue.size() > buffer.capacity()) {
            lost_count++;
            continue;
        }

        lock.lock();
        buffer.insert(buffer.end(), input_queue.begin(), input_queue.end());
        input_queue.clear();
        lock.unlock();
    }
}

void consumer() {
    while (true) {
        std::unique_lock<std::mutex> lock(mtx);

        if (buffer.empty()) {
            lock.unlock();
            std::this_thread::sleep_for(std::chrono::milliseconds(10));
            continue;
        }

        auto data = buffer.back();
        buffer.pop_back();
        lock.unlock();

        // Process the data here

        processed_count++;
    }
}

int main() {
    const int buffer_size = 10000;
    buffer.reserve(buffer_size);
    buffer.shrink_to_fit();

    std::thread producerThread(producer);
    std::vector<std::thread> consumerThreads;

    for (int i = 0; i < std::thread::hardware_concurrency() - 1; ++i) {
        consumerThreads.emplace_back(consumer);
    }

    producerThread.join();
    for (auto& thread : consumerThreads) {
        thread.join();
    }

    std::cout << "Processed records: " << processed_count << "\n";
    std::cout << "Lost records: " << lost_count << "\n";

    return 0;
}
```

This code creates a producer thread that reads data from an external source and pushes it into a queue. A consumer thread processes the data from the queue, and multiple consumer threads are used to improve performance. The buffer ensures that incoming data is not lost when the processing threads cannot keep up with the production rate. Error handling is implemented through exceptions for memory allocation failures, and the system can continue operating with reduced throughput if necessary.

You may need to adjust the code to fit your specific sensor data structure and external data source. Additionally, you should consider implementing more advanced error handling, thread synchronization, and performance optimization techniques as needed for your high-throughput sensor data processing system.']

