const crypto = require('crypto');
const stream = require('stream');
const axios = require('axios');

class CertificateStream extends stream.Transform {
  constructor(options) {
    super(options);
    this._data = '';
  }

  _transform(chunk, encoding, callback) {
    this._data += chunk;
    callback();
  }

  get certificate() {
    return this._data;
  }
}

async function generatePEMCertificate(request) {
  const provider = request.provider || '';
  const version = request.version || '';

  let keyPath, certPath;

  switch (provider) {
    case 'google':
      // Implement Google-specific key and certificate retrieval based on OAuth version
      break;
    case 'facebook':
      // Implement Facebook-specific key and certificate retrieval based on OAuth version
      break;
    default:
      throw new Error(`Unsupported provider: ${provider}`);
  }

  const keyStream = axios.create().get(keyPath, { responseType: 'stream' });
  const certStream = axios.create().get(certPath, { responseType: 'stream' });

  const keyBuffer = await new Promise((resolve) => {
    const key = new CertificateStream({ highWaterMark: 1024 });
    keyStream.on('data', (chunk) => key.write(chunk));
    keyStream.on('end', () => resolve(key.certificate));
  });

  const certBuffer = await new Promise((resolve) => {
    const cert = new CertificateStream({ highWaterMark: 1024 });
    certStream.on('data', (chunk) => cert.write(chunk));
    certStream.on('end', () => resolve(cert.certificate));
  });

  try {
    const pemKey = `-----BEGIN RSA PRIVATE KEY-----\n${keyBuffer.toString('base64')}\n-----END RSA PRIVATE KEY-----`;
    const pemCert = `-----BEGIN CERTIFICATE-----\n${certBuffer.toString('base64')}\n-----END CERTIFICATE-----`;

    return { pemKey, pemCert };
  } catch (error) {
    throw new Error(`Failed to generate PEM: ${error.message}`);
  }
}
```

