Now, let's implement the DNS resolution function using Rust standard library:

```rust
use std::net::{Ipv4Addr, Ipv6Addr};
use std::str;
use std::time::Duration;

fn resolve_ip(hostname: &str) -> Result<Vec<u8>, i32> {
    let mut addrs = vec![];
    let mut addrinfo = match getaddrinfo(hostname, None, Some(ai_family::Ipv4), ai_socktype::SOCK_STREAM, ai_flags::AI_NUMERICHOST) {
        Ok(result) => result,
        Err(_) => return Err(-1),
    };

    for ai in addrinfo {
        match ai.addr() {
            Ipv4Addr::new(a, b, c, d) => addrs.push((a as u8) as u_char);
                addrs.push((b as u8) as u_char);
                addrs.push((c as u8) as u_char);
                addrs.push((d as u8) as u_char);
            Ipv6Addr::new(a, b, c, d, e, f, g, h, i, j, k, l, m, n, o) => {
                addrs.extend([
                    (a as u8) as u_char, (b as u16) as u_char, (c as u16) as u_char,
                    (d as u32) as u_char, (e as u16) as u_char, (f as u16) as u_char,
                    (g as u8) as u_char, (h as u8) as u_char, (i as u8) as u_char,
                    (j as u8) as u_char, (k as u8) as u_char, (l as u8) as u_char,
                    (m as u16) as u_char, (n as u16) as u_char, (o as u32) as u_char
                ]
            }
        }
    }

    Ok(addrs)
}
```

