use std::env;
use tokio::task::spawn_blocking;
use tokio::time::{sleep, Duration};

async fn authenticate_and_resolve(username: &str, password: &str, hostname: &str) {
    let access_token = if authenticate(username, password).is_ok() {
        Some(getUserDetails(authenticate(username, password).unwrap()))
    } else {
        None
    };

    match resolve_ip(hostname) {
        Ok(ip) => println!("Access Token: {}\nIP Address: {:?}", access_token.as_ref().unwrap(), ip),
        Err(_) => println!("Error resolving IP address"),
    }
}

fn main() {
    let args: Vec<String> = env::args().collect();
    if args.len() != 4 {
        eprintln!("Usage: {} <username> <password> <hostname>", args[0]);
        return;
    }

    let username = &args[1];
    let password = &args[2];
    let hostname = &args[3];

    spawn_blocking(move || authenticate_and_resolve(username, password, hostname)).await.unwrap();
