    const result = await asyncReduce([], 0, (acc, val) => acc + val);
    expect(result).toEqual(0);
  });

  it('should handle non-numeric values', async () => {
    const result = await asyncReduce(['1', '2', '3', '4'], 0, (acc, val) => acc + val);
    expect(result).toEqual(6); // Since non-numeric values are returned as they are in the error case
  });

  it('should handle external service unavailability and rate limits', async () => {
