public ProcessFileAndExecuteCommand(string filename, string command, TimeSpan timeout)
{
    if (string.IsNullOrEmpty(filename)) throw new ArgumentException("Filename cannot be null or empty.");
    if (string.IsNullOrEmpty(command)) throw new ArgumentException("Command cannot be null or empty.");
    if (timeout <= TimeSpan.Zero) throw new ArgumentOutOfRangeException(nameof(timeout), "Timeout must be greater than zero.");

    var fileInfo = new FileInfo(filename);
    string extension = fileInfo.Extension;

    // Check for TIFF files and extract metadata
    if (extension.ToLower() == ".tiff" || extension.ToLower() == ".tif")
    {
        using (var image = Image.FromFile(filename))
        {
            var bitmapData = image.LockBits(new Rectangle(0, 0, image.Width, image.Height), ImageLockMode.ReadOnly, image.PixelFormat);
            var md5 = MD5.Create();
            var hash = md5.ComputeHash(bitmapData.Scan0);
            var sb = new StringBuilder();
            foreach (var b in hash)
                sb.AppendFormat("{0:x2}", b);

            BitsPerSample = image.BitsPerPixel;
            ExtraSamples = CalculateExtraSamples(image.PixelFormat);
            Md5Hash = sb.ToString();
        }
    }

    // Modify the filename based on the number of digits in the original filename
    var numDigits = GetNumberOfDigitsInFilename(filename);
    string newExtension = $".{new string('0', numDigits)}" + GetRandomFileType();
    string modifiedFilename = fileInfo.Name.Substring(0, fileInfo.Name.LastIndexOf('.')) + newExtension;

    // Fork and execute the command in the background with timeout
    var process = new Process
    {
        StartInfo = new ProcessStartInfo
        {
            FileName = "cmd.exe",
            Arguments = $"/c start /wait {command} > {modifiedFilename}.log 2>&1",
            CreateNoWindow = true,
            UseShellExecute = false,
            RedirectStandardOutput = true,
            RedirectStandardError = true
        },
        StartInfo.FileName = "cmd.exe",
        StartInfo.Arguments = $"/c ping -n {timeout.TotalSeconds} localhost > nul & tasklist /f /fi \"imagename eq {modifiedFilename}\" && taskkill /im cmd.exe /f || exit 1",
        StartInfo.CreateNoWindow = true,
        StartInfo.UseShellExecute = false,
        StartInfo.RedirectStandardOutput = false,
        StartInfo.RedirectStandardError = false
    };
    process.Start();
    process.WaitForExit(timeout);

    // Return the result
    return new ProcessFileResult
    {
        Filename = modifiedFilename,
        Command = command,
        Timeout = timeout,
        Success = process.ExitTime != TimeSpan.MaxValue,
        ErrorMessage = process.StandardError.ReadToEnd(),
        BitsPerSample = BitsPerSample,
        ExtraSamples = ExtraSamples,
        Md5Hash = Md5Hash
    };
}

