SSHContext *ssh_context_init(const char *private_key_path, const char *cache_root_dir) {
    SSHContext *ctx = malloc(sizeof(SSHContext));
    ctx->private_key_path = strdup(private_key_path);
    ctx->cache_root_dir = strdup(cache_root_dir);

    // Determine default server config directory
    char *default_config_dir;
    if (getenv("SSH_CONFIG")) {
        default_config_dir = strdup(getenv("SSH_CONFIG"));
    } else if (access(join_paths(cache_root_dir, "ssh", "config"), F_OK) != -1) {
        default_config_dir = join_paths(cache_root_dir, "ssh", "config");
    } else {
        default_config_dir = join_paths(getenv("HOME"), ".ssh", "config");
    }

    // Load JSON configuration and validate against schema
    char *config_path = join_paths(default_config_dir, "known_hosts2");
    json_error_t error;
    ctx->config = json_loadf(config_path, 0, &error);
    if (!ctx->config) {
        fprintf(stderr, "Failed to load configuration: %s\n", error.text);
        exit(EXIT_FAILURE);
    }

    // Initialize SSH session context and set trusted host key verification
    ctx->session = ssh2_new();
    ssh2_options_set(ctx->session, SSH2_OPTIONS_HOSTKEYS, "none");

    return ctx;
}

void ssh_context_cleanup(SSHContext *ctx) {
    if (ctx->config) json_decref(ctx->config);
    if (ctx->private_key_path) free(ctx->private_key_path);
    if (ctx->cache_root_dir) free(ctx->cache_root_dir);
    ssh2_session_disconnect(ctx->session, "Closing SSH session");
    ssh2_session_free(ctx->session);
}
