```

3. Implement functions for adding and removing nodes from the list:

```c
void add_node(node_t** head, record_t data) {
    node_t* new_node = malloc(sizeof(node_t));
    if (!new_node) return;

    new_node->data = data;
    new_node->next = *head;
    *head = new_node;
}

void remove_node(node_t** head, node_t* node_to_remove) {
    if (*head == node_to_remove) {
        *head = (*head)->next;
        free(node_to_remove);
        return;
    }

    node_t* current = *head;
    while (current->next != node_to_remove) {
        if (!current->next) break;
        current = current->next;
    }

    if (!current->next) return;

    current->next = current->next->next;
    free(node_to_remove);
}
```

