struct LogEntry {
    std::string timestamp;
    int user_id;
    std::string action_type;
};

std::vector<LogEntry> log_entries;
std::deque<LogEntry> buffer;
std::mutex mtx;
std::atomic<int> processed_lines{0};
constexpr int BUFFER_SIZE = 5000;
constexpr std::string LOG_FILE = "progress.log";

void processCSV(const std::string& file) {
    std::ifstream inputFile(file);
    if (!inputFile.is_open()) {
        std::cerr << "Error opening file: " << file << std::endl;
        return;
    }

    int line_count = 0;
    LogEntry entry;
    while (inputFile >> entry.timestamp >> entry.user_id >> entry.action_type) {
        if (!validate(entry)) continue;

        mtx.lock();
        buffer.push_back(std::move(entry));
        mtx.unlock();

        processed_lines++;
        if (processed_lines % BUFFER_SIZE == 0) {
            processBuffer();
        }
        line_count++;
    }

    inputFile.close();
    processBuffer();
}

void processBuffer() {
    mtx.lock();
    while (!buffer.empty()) {
        log_entries.push_back(std::move(buffer.front()));
        buffer.pop_front();
    }
    mtx.unlock();

    updateProgress();
}

bool validate(const LogEntry& entry) {
    // Custom validation logic for each field goes here
    return true;
}

void updateProgress() {
    auto start = std::chrono::system_clock::now();
    if (processed_lines % BUFFER_SIZE == 0) {
        auto elapsed_seconds = std::chrono::duration_cast<std::chrono::seconds>(start - lastUpdateTime);
        std::ofstream logFile(LOG_FILE, std::ios::app);
        if (logFile.is_open()) {
            logFile << "Processed " << processed_lines << " lines in " << elapsed_seconds.count() << " seconds" << std::endl;
            logFile.close();
        }
    }
    lastUpdateTime = std::chrono::system_clock::now();
}

std::chrono::system_clock::time_point lastUpdateTime = std::chrono::system_clock::now();

int main() {
    processCSV("activity_log.csv");
    return 0;
}
```

