const axios = require('axios');
const dns = require('dns');
const { fork } = require('child_process');

const SERVERS = ['server1.com', 'server2.com', 'server3.com']; // List of servers to monitor
const CONCURRENCY_LIMIT = 5; // Maximum number of concurrent requests
const TIMEOUT = 3000; // Timeout in milliseconds

function checkServerHealth(server) {
  return new Promise((resolve, reject) => {
    const request = axios.get(`http://${server}`);

    request.timeout(TIMEOUT).catch(() => {
      console.error(`Timeout for ${server}`);
      reject(new Error(`Timeout for ${server}`));
    });

    request.then(response => {
      if (response.status === 200) {
        console.log(`${server} is healthy`);
        resolve(true);
      } else {
        console.error(`${server} is not healthy (status code ${response.status})`);
        reject(new Error(`${server} is not healthy (status code ${response.status})`));
      }
    });
  });
}

async function monitorServers() {
  const worker = fork('worker.js');

  for (const server of SERVERS) {
    dns.lookup(server, async (err, address, family) => {
      if (err) {
        console.error(`DNS resolution error for ${server}:`, err);
        return;
      }

      worker.send({ command: 'check', server });
    });
  }

  worker.on('message', message => {
    if (message.status) {
      console.log(message.server, 'is healthy');
    } else {
      console.error(message.server, 'is not healthy:', message.error);
    }
  });
}

function worker(args) {
  const { command, server } = args;

  if (command === 'check') {
    checkServerHealth(server)
      .then(healthy => {
        process.send({ command: 'response', server, status: healthy });
      })
      .catch(error => {
        process.send({ command: 'response', server, error });
      });
  }
}

monitorServers();
```

In this example, the `worker.js` file contains the worker process that handles individual server health checks. The main script (not shown) would handle concurrency control and logging as per your requirements. This is a starting point and can be further optimized and extended to meet all of your specific needs."]

