    def to_dict(self) -> dict:
        return self._data.copy()

class ConfigFactoryRegistry:
    _registry = {}

    @classmethod
    def register(cls, config_type: Type[ConfigBase], factory: callable):
        cls._registry[config_type] = factory

    @classmethod
    def create(cls, config_type: Type[ConfigBase], data: dict) -> ConfigBase:
        if config_type not in cls._registry:
            raise ValueError(f"Unknown configuration type {config_type}")
        return cls._registry[config_type](data)

class NetworkConfigService:
    def __init__(self, url: str):
        self.url = url

    def get_config(self) -> dict:
        try:
            response = requests.get(self.url)
            if response.status_code == 200:
                return response.json()
        except Exception as e:
            logging.error(f"Error fetching configuration from {self.url}: {e}")
        return {}

class ConfigLoader:
    def __init__(self, service: NetworkConfigService):
        self._service = service
        self._lock = threading.Lock()
        self._config = None

    def load(self) -> ConfigBase:
        with self._lock:
            if self._config is None:
                self._config = ConfigFactoryRegistry.create(ConfigNetwork, self._service.get_config())
        return self._config

class ConfigNetwork(ConfigBase):
    pass

class ConfigFile:
    def __init__(self, filepath: str):
        with open(filepath) as f:
            self._data = json.load(f)

    @property
    def data(self) -> dict:
        return self._data

    def to_dict(self) -> dict:
        return self._data.copy()

class ConfigFileLoader:
    def load(self, filepath: str) -> ConfigBase:
        return ConfigFactoryRegistry.create(ConfigFile, filepath=filepath)

class ConfigManager:
    def __init__(self, config_loader: ConfigLoader or ConfigFileLoader):
        self._loader = config_loader
        self._config = None

    @property
    def config(self) -> ConfigBase:
        if self._config is None:
            self._config = self._loader.load()
        return self._config

class Encryptor:
