```cpp
#include <iostream>
#include <string>
#include <filesystem>
#include <fstream>
#include <sstream>
#include <vector>
#include <zlib/adler32.h>
#include <thread>
#include <mutex>
#include <queue>

std::mutex mtx;
std::condition_variable cv;
std::queue<std::string> fileQueue;
int maxThreads = 10;
std::vector<std::thread> threads;

void compress(const std::string& fileName) {
    // Implement compression logic here using zlib library
}

void processFile(const std::filesystem::path& path) {
    std::ifstream file(path, std::ios::binary);
    if (!file.is_open()) return;

    std::string fileName = path.filename().string();
    std::string suffix;
    uint32_t adler32Checksum = Adler32(nullptr, nullptr, 0);

    std::stringstream buffer((std::istreambuf_iterator<char>(file)), std::ostreambuf_iterator<char>());
    std::string line;
    while (getline(buffer, line)) {
        adler32Checksum = Adler32(adler32Checksum, line.c_str(), line.length());
    }

    if (file.eof()) {
        if (buffer.str().empty()) suffix = "_0lines";
        else suffix = std::to_string(buffer.str().size()) + "lines";
    }

    auto newName = fileName.substr(0, fileName.find('.')) + "_" + std::to_string(adler32Checksum) + suffix;
    std::rename(path.string().c_str(), (path / newName).string().c_str());
    fileQueue.push((path / newName).string());
}

void worker() {
    while (!fileQueue.empty()) {
        auto fileName = fileQueue.front();
        fileQueue.pop();
        compress(fileName);
        cv.notify_one();
    }
}

void processDirectory(const std::filesystem::path& path) {
    std::for_each(std::begin(std::filesystem::recursive_directory_iterator(path)),
                   std::end(std::filesystem::recursive_directory_iterator(path)),
                   [](const auto& entry) {
                       if (entry.is_regular_file()) processFile(entry.path());
                   });

    for (int i = 0; i < maxThreads && !fileQueue.empty(); ++i) {
        threads.emplace_back(worker);
    }

    std::unique_lock<std::mutex> lock(mtx);
    cv.wait(lock, [] { return fileQueue.empty() || threads.size() == maxThreads; });
}
```

This code snippet creates a function `processDirectory` that processes the specified directory recursively and renames files based on their content type and number of lines. It also spawns worker threads to compress each renamed file asynchronously, with a limit on the number of concurrent threads. The main thread waits for all worker threads to complete before returning.']

