    semaphore->count--;
    pthread_mutex_unlock(&semaphore->lock);
}

void release_semaphore(Semaphore* semaphore) {
    pthread_mutex_lock(&semaphore->lock);
    semaphore->count++;
    pthread_cond_signal(&semaphore->cond);
