[' Here's a C function that meets your requirements, using the `malloc`, `fscanf`, and `fprintf` functions for memory allocation, input/output, and the `pthread_mutex_t` for synchronization with an external logging library:

```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

typedef struct {
    pthread_mutex_t lock;
    size_t size;
    size_t capacity;
    int* data;
} IntArray;

IntArray* create_int_array(size_t initial_capacity) {
    IntArray* array = malloc(sizeof(IntArray));
    if (!array) return NULL;

    array->data = malloc(initial_capacity * sizeof(int));
    if (!array->data) {
        free(array);
        return NULL;
    }

    array->size = 0;
    array->capacity = initial_capacity;
    pthread_mutex_init(&array->lock, NULL);

    return array;
}

void destroy_int_array(IntArray* array) {
    free(array->data);
    pthread_mutex_destroy(&array->lock);
    free(array);
}

void append_valid_integer(IntArray* array, int value) {
    if (value <= 0) return;

    if (array->size == array->capacity) {
        array->capacity *= 2;
        array->data = realloc(array->data, array->capacity * sizeof(int));
    }

    array->data[array->size++] = value;
}

void log_stats(const char* label, IntArray* array) {
    pthread_mutex_lock(&array->lock);

    int sum = 0;
    for (size_t i = 0; i < array->size; ++i) {
        sum += array->data[i];
    }

    fprintf(stderr, "%s: %zu valid integers, sum: %d\n", label, array->size, sum);

    pthread_mutex_unlock(&array->lock);
}

int find_largest_integer(IntArray* array) {
    if (array->size == 0) return INT_MIN;

    int largest = array->data[0];
    for (size_t i = 1; i < array->size; ++i) {
        if (array->data[i] > largest) {
            largest = array->data[i];
        }
    }

    return largest;
}

void read_and_process(FILE* stream, IntArray* array) {
    int value;
    while (fscanf(stream, "%d", &value) == 1 && value > 0) {
        append_valid_integer(array, value);
    }
}

void handle_network_interruption(FILE* stream) {
    if (feof(stream)) {
        fprintf(stderr, "Network interruption detected.\n");
    } else if (ferror(stream)) {
        perror("Error reading from network stream.");
    }
}

void process_and_log(FILE* stream, IntArray* array) {
    read_and_process(stream, array);
    handle_network_interruption(stream);

    log_stats("Interim", array);
}

int main() {
    FILE* stream = fopen("network_stream.txt", "r");
    if (!stream) {
        perror("Error opening network stream.");
        return 1;
    }

    IntArray* array = create_int_array(16);
    if (!array) {
        fprintf(stderr, "Memory allocation failure.\n");
        fclose(stream);
        return 2;
    }

    process_and_log(stream, array);

    int largest = find_largest_integer(array);
    printf("Largest integer: %d\n", largest);

    destroy_int_array(array);
    fclose(stream);

    return 0;
