bool validate_input(unsigned long *size1, unsigned long *size2, unsigned int range) {
    if (*size1 == 0 || *size2 == 0 || *size1 > SIZE_MAX / sizeof(long) || *size2 > SIZE_MAX / sizeof(int)) {
        fprintf(stderr, "Error: Invalid size\n");
        return false;
    }
    if (*size1 < *size2) *size1 = *size2;

    return true;
}

void init_keys(int *keys, unsigned long size) {
    for (unsigned long i = 0; i < size; ++i) keys[i] = i;
}

Record* create_records(unsigned long size, unsigned int range) {
    Record *records = malloc(size * sizeof(Record));
    if (!records) {
        fprintf(stderr, "Error: Out of memory\n");
        return NULL;
    }

    srand(time(NULL));
    for (unsigned long i = 0; i < size; ++i) {
        records[i].value = rand() % range;
        records[i].offset = -1;
    }

    return records;
}

void assign_offsets(long *offsets, Record *records, unsigned long size) {
    for (unsigned long i = 0; i < size; ++i) {
        if (i < size && records[i].offset != -1) offsets[records[i].offset] = i;
    }
}

int main_function(unsigned long *size1, unsigned long *size2, unsigned int range) {
    if (!validate_input(size1, size2, range)) return 1;

    long *offsets = malloc(*size1 * sizeof(long));
    if (!offsets) {
        fprintf(stderr, "Error: Out of memory\n");
        return 1;
    }

    int *keys = malloc(*size2 * sizeof(int));
    if (!keys) {
        free(offsets);
        fprintf(stderr, "Error: Out of memory\n");
        return 1;
    }

    init_keys(keys, *size2);

    Record *records = create_records(*size1, range);
    if (!records) {
        free(offsets);
        free(keys);
        fprintf(stderr, "Error: Out of memory\n");
        return 1;
    }

    assign_offsets(offsets, records, *size1);

    // Use the allocated memory here...

    free(records);
    free(keys);
    free(offsets);

    return 0;
}
