```

2. Implement the function in a source file (`encryption_module.c`):

```c
#include "encryption_module.h"
#include <openssl/evp.h>
#include <openssl/err.h>

void init_encryption(EncryptionConfig* config, unsigned char** key, size_t* key_length) {
    EVP_CIPHER_CTX* ctx = EVP_CIPHER_CTX_new();

    const EVP_CIPHER* cipher = NULL;
    if (!EVP_get_cipherbyname(config->algorithm)) {
        fprintf(stderr, "Error: Unsupported encryption algorithm\n");
        exit(EXIT_FAILURE);
    }
    cipher = EVP_CIPHER_new();

    int mode_num;
    if (!strcmp(config->mode, "ECB")) {
        mode_num = EVP_ENCRYPTION_MODE_ECB;
    } else if (!strcmp(config->mode, "EDE")) {
        mode_num = EVP_ENCRYPTION_MODE_CBC_PKCS5_OAEP; // EDE uses CBC under the hood
    } else if (!strcmp(config->mode, "EDE3")) {
        mode_num = EVP_ENCRYPTION_MODE_CFB1_PADDING; // EDE3 uses CFB under the hood
    } else if (!strcmp(config->mode, "CFB")) {
        mode_num = EVP_ENCRYPTION_MODE_CFB1_PADDING;
    } else {
        fprintf(stderr, "Error: Unsupported encryption mode\n");
        exit(EXIT_FAILURE);
    }

    if (1 != EVP_EncryptInit_ex(ctx, cipher, NULL, config->key, config->iv)) {
        fprintf(stderr, "Error: Initialization failed\n");
        exit(EXIT_FAILURE);
    }

    *key = EVP_CIPHER_get_key(cipher);
    *key_length = EVP_CIPHER_key_length(*key);
}

void encrypt_block(unsigned char* plaintext, const unsigned char* key, size_t length, EVP_CIPHER_CTX* ctx) {
    unsigned char ciphertext[1024];
    int ciphertext_len = 0;

    if (1 != EVP_EncryptUpdate(ctx, ciphertext, &ciphertext_len, plaintext, length)) {
        fprintf(stderr, "Error: Encryption failed\n");
        exit(EXIT_FAILURE);
    }

    memcpy(plaintext, ciphertext, ciphertext_len);
}

void decrypt_block(unsigned char* ciphertext, const unsigned char* key, size_t length, EVP_CIPHER_CTX* ctx) {
    unsigned char plaintext[1024];
    int plaintext_len = 0;

    if (1 != EVP_DecryptUpdate(ctx, plaintext, &plaintext_len, ciphertext, length)) {
        fprintf(stderr, "Error: Decryption failed\n");
        exit(EXIT_FAILURE);
    }

    memcpy(ciphertext, plaintext, plaintext_len);
}

void cleanup_encryption(EVP_CIPHER_CTX* ctx) {
    EVP_CIPHER_CTX_free(ctx);
}
```

3. Add a main function to test the encryption module:

```c
int main(int argc, char** argv) {
    if (argc < 6) {
        fprintf(stderr, "Usage: %s [algorithm] [mode] [key_length] [iv_size] [plaintext]\n", argv[0]);
        return EXIT_FAILURE;
    }

    EncryptionConfig config = {
        .algorithm = argv[1],
        .mode = argv[2],
        .key_length = atoi(argv[3]),
        .iv_size = atoi(argv[4])
    };

    unsigned char* key;
    size_t key_length;
    init_encryption(&config, &key, &key_length);

    unsigned char plaintext[] = "Hello World!";
    unsigned char ciphertext[sizeof(plaintext)];
    encrypt_block(ciphertext, key, sizeof(plaintext), NULL);

    printf("Ciphertext: ");
    for (size_t i = 0; i < sizeof(ciphertext); ++i) {
        printf("%02x ", ciphertext[i]);
    }
    printf("\n");

    cleanup_encryption(NULL);
    free(key);

    return EXIT_SUCCESS;
}
```']

