[' Here is a C function that meets your requirements, using pthreads for thread-safety, and environment variables for dynamic configuration. The code assumes the use of `stdlib.h`, `unistd.h`, `pthread.h`, `stdint.h`, and `time.h`.

```c
#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <pthread.h>
#include <stdint.h>
#include <time.h>

typedef struct {
    int value;
    char key_char;
} record;

struct config {
    size_t max_records;
    size_t offset_step;
    size_t offset_limit;
    long seed;
    int min_value;
    int max_value;
    char* char_mapping;
};

static struct config g_config;
static pthread_mutex_t g_mutex = PTHREAD_MUTEX_INITIALIZER;
static record* g_records = NULL;
static size_t g_record_count = 0;

void init_config(const char* env_prefix) {
    g_config.max_records = getenv((char*)(env_prefix "MAX_RECORDS")) ? atol(getenv((char*)(env_prefix "MAX_RECORDS"))) : 1024;
    g_config.offset_step = getenv((char*)(env_prefix "OFFSET_STEP")) ? atol(getenv((char*)(env_prefix "OFFSET_STEP"))) : 1;
    g_config.offset_limit = getenv((char*)(env_prefix "OFFSET_LIMIT")) ? atol(getenv((char*)(env_prefix "OFFSET_LIMIT"))) : 1024 * 1024;
    g_config.seed = getenv((char*)(env_prefix "SEED")) ? atol(getenv((char*)(env_prefix "SEED"))) : time(NULL);
    g_config.min_value = getenv((char*)(env_prefix "MIN_VALUE")) ? atoi(getenv((char*)(env_prefix "MIN_VALUE"))) : 0;
    g_config.max_value = getenv((char*)(env_prefix "MAX_VALUE")) ? atoi(getenv((char*)(env_prefix "MAX_VALUE"))) : 10000;
    g_config.char_mapping = getenv((char*)(env_prefix "CHAR_MAPPING"));
}

long hash(size_t key, long seed) {
    long hash = 5381;
    for (size_t i = 0; i < key; ++i) {
        hash = ((hash << 5) + hash) + (key & 0xFF); /* hash * 33 + c */
    }
    hash += seed;
    return hash % g_config.offset_limit;
}

void* create_record(void* arg) {
    size_t index = (size_t)arg;
    long key = hash(index, g_config.seed);

    while (g_records && g_record_count >= g_config.max_records) {
        if (key == g_records[0].key) return NULL;
        key = hash(++index, g_config.seed);
    }

    record* record_ptr = (record*)malloc(sizeof(record));
    if (!record_ptr) return NULL;

    record_ptr->value = rand() % (g_config.max_value - g_config.min_value + 1) + g_config.min_value;
    record_ptr->key_char = g_config.char_mapping[key];
    if (!g_records) {
        g_records = record_ptr;
        g_record_count++;
    } else {
        record* last_record = &g_records[g_record_count - 1];
        while (last_record->key_char != record_ptr->key_char) {
            if (!++last_record) {
                free(record_ptr);
                return NULL;
            }
        }
        last_record = record_ptr;
        g_record_count++;
    }

    return last_record;
}

record* init_records() {
    pthread_t threads[g_config.offset_limit];
    for (size_t i = 0; i < g_config.offset_limit; ++i) {
        if (pthread_create(&threads[i], NULL, create_record, (void*)i)) {
            fprintf(stderr, "Failed to create thread\n");
            return NULL;
        }
    }

    for (size_t i = 0; i < g_config.offset_limit; ++i) {
        void* result;
        if (pthread_join(threads[i], &result)) {
            fprintf(stderr, "Failed to join thread\n");
            return NULL;
        }
        if (!result) {
            fprintf(stderr, "Thread creation failed\n");
            return NULL;
        }
    }

    return g_records;
}
```

This code initializes the configuration using environment variables and creates a thread for each record to be created. The `create_record()` function ensures that keys are unique by hashing the index and seed, and it uses a mapping to generate unique ASCII characters for each key. The memory is dynamically allocated, and the function returns a pointer to the first record in the array.

To use this code, call `init_config()` with the desired environment variable prefix before calling `init_records()`. Make sure to set the appropriate environment variables before running your program.']

