```cpp
#include <iostream>
#include <vector>
#include <string>
#include <boost/thread/mutex.hpp>
#include <boost/log/trivial.hpp>
#include <boost/container/small_vector.hpp>

struct Record {
    long offset;
    int key;
    std::string str;
    double measurement;
};

class MemoryPool {
public:
    MemoryPool(size_t initialSize, size_t blockSize) : blocks_(initialSize), blockSize_(blockSize), freeList_(), usedBlocks_(), mutex_() {}

    Record* allocate() {
        boost::lock_guard<boost::mutex> lock(mutex_);
        if (!freeList_.empty()) {
            auto it = freeList_.begin();
            freeList_.erase(it);
            usedBlocks_[it] = true;
            return reinterpret_cast<Record*>(it);
        }

        if (usedBlocks_.size() >= blocks_.size()) {
            BOOST_LOG_TRIVIAL(warning) << "Memory pool is full. Consider resizing.";
            return nullptr;
        }

        auto newBlock = &blocks_[usedBlocks_.size()];
        new (newBlock) std::vector<Record*>;
        newBlock += blockSize_;
        usedBlocks_[newBlock] = true;
        return reinterpret_cast<Record*>(newBlock);
    }

    void deallocate(Record* record) {
        boost::lock_guard<boost::mutex> lock(mutex_);
        auto newBlock = reinterpret_cast<Record*>(std::addressof(static_cast<std::vector<Record*>*>(record)[-1]));
        usedBlocks_[newBlock] = false;
        freeList_.push_back(newBlock);
    }

private:
    std::vector<std::vector<Record*>> blocks_;
    size_t blockSize_;
    std::vector<bool> usedBlocks_;
    std::vector<Record*> freeList_;
    mutable boost::mutex mutex_;
};
```

This code provides a basic memory pool for records, with functions to allocate and deallocate records. The `MemoryPool` class uses a linked list of blocks to manage free memory efficiently and minimizes fragmentation by allocating new blocks when necessary. It also includes a simple thread-safety mechanism using Boost's mutex.

