[' Here's a Rust function `generate_unique_filename_and_create_directory` that follows your specifications:

```rust
use std::env;
use std::fs::{self, File, create_dir_all};
use std::io::{BufWriter, Write};
use std::path::Path;
use std::time::SystemTime;
use rand::Rng;
use chrono::prelude::*;

fn generate_unique_filename(base: &str, ext: &str) -> String {
    let mut rng = rand::thread_rng();
    let timestamp = Local::now().format("%Y%m%d%H%M%S").to_string();
    format!("{}{}{}.{}", base, timestamp, rng.gen_range(0..10000), ext)
}

fn generate_unique_filename_and_create_directory(filename: &str, directory: &str, create_dir: bool) -> std::io::Result<String> {
    let dir = Path::new(directory);
    if create_dir && !dir.exists() {
        create_dir_all(dir)?;
        env::set_var("CURRENT_DIR", dir.to_str().unwrap());
    }

    let mut base = filename;
    let ext = match base.rsplit('.') {
        Some(parts) => parts.last().unwrap(),
        None => ".txt",
    };

    let unique_filename = generate_unique_filename(&base, &ext);
    Ok(match (ext, &unique_filename) {
        ("log", ref s) if s.ends_with(".log") => s.to_string(),
        ("csv", ref s) if s.ends_with(".csv") => s.to_string(),
        _ => format!("{}.txt", unique_filename),
    })
}
```

