tiff_info parse_tiff(const char *filename) {
    TIFF *tif = TIFOpen(filename, "r");
    if (!tif) {
        fprintf(stderr, "Error: Unable to open file %s\n", filename);
        exit(EXIT_FAILURE);
    }

    tiff_info info;
    info.bits_per_sample = TIFFGetField(tif, TIFFTAG_SAMPLESPERPIXEL);
    info.sample_per_pixel = TIFFGetField(tif, TIFFTAG_BITSPERSAMPLE);

