        fprintf(stderr, "Error: Unsupported bits per sample or sample per pixel\n");
        exit(EXIT_FAILURE);
    }

    int num_samples = TIFFNumberOfSamples(tif);
    info.extra_samples = num_samples - (info.sample_per_pixel > 1 ? info.sample_per_pixel : 1);

