    for (size_t i = 0; i < size; ++i) {
        int value;
        do {
            value = dis(gen);
            mtx.lock();
            if (std::find(usedValues.begin(), usedValues.end(), value) == usedValues.end()) {
                usedValues[value] = 1;
                mtx.unlock();
                break;
            }
            mtx.unlock();
        } while (true);

        records[i].value = value;
        records[i].offset = i * sizeof(Record);
        records[i].key = i % KEY_RANGE;
    }
}

size_t system_memory() { // Replace with actual memory calculation function
