```c
#define POOL_SIZE 1024
struct MemoryPool {
    void* buffer[POOL_SIZE];
    size_t allocated;
};

void init_memory_pool(struct MemoryPool* pool) {
    memset(pool->buffer, 0, sizeof(pool->buffer));
    pool->allocated = 0;
}

void* allocate_from_pool(struct MemoryPool* pool) {
    if (pool->allocated >= POOL_SIZE) return allocate_memory(1);
    void* ptr = pool->buffer[pool->allocated];
    pool->allocated++;
    return ptr;
}

void free_to_pool(struct MemoryPool* pool, void* ptr) {
    memset(ptr, 0, sizeof(record)); // Zero out the memory for safety
    pool->buffer[--pool->allocated] = ptr;
}
