class DataStructure {
public:
    DataStructure(size_t numRecords, bool compress) : pool(), numRecords_(numRecords), compress_(compress) {}

    void* allocate() {
        void* memory = pool.allocate();
        if (!memory) {
            log_error("Memory allocation failure");
            return nullptr;
        }
        return memory;
    }

    void deallocate(void* memory) {
        pool.deallocate(memory);
    }

    void serialize(const std::string& filename) const {
        boost::filesystem::ofstream file(filename, std::ios::binary | std::ios::out);
        if (file.is_open()) {
            boost::iostreams::compression::zlib compressor;
            if (compress_) {
                compressor.push(file);
            }

            for (const auto& record : records_) {
                NFAPI_CRC_INDICATION_PDU_T* pdu = static_cast<NFAPI_CRC_INDICATION_PDU_T*>(record.first);
                CRC_INDICATION_REL8_TAG* tag = static_cast<CRC_INDICATION_REL8_TAG*>(record.second);

                boost::asio::write(file, reinterpret_cast<char*>(pdu), sizeof(NFAPI_CRC_INDICATION_PDU_T));
                boost::asio::write(file, reinterpret_cast<char*>(tag), sizeof(CRC_INDICATION_REL8_TAG));
            }

            if (compress_) {
                compressor.pop();
            }
        } else {
            log_error("Failed to open file for writing");
        }
    }

    void deserialize(const std::string& filename) {
        boost::filesystem::ifstream file(filename, std::ios::binary | std::ios::in);
        if (file.is_open()) {
            boost::iostreams::compression::zlib compressor;
            if (compress_) {
                compressor.push(file);
            }

            for (auto& [offset, key] : records_) {
                deallocate(key);
            }
            records_.clear();

            while (!file.eof()) {
                NFAPI_CRC_INDICATION_PDU_T* pdu = static_cast<NFAPI_CRC_INDICATION_PDU_T*>(allocate());
                if (pdu) {
                    boost::asio::read(file, reinterpret_cast<char*>(pdu), sizeof(NFAPI_CRC_INDICATION_PDU_T));

                    CRC_INDICATION_REL8_TAG* tag = static_cast<CRC_INDICATION_REL8_TAG*>(allocate());
                    if (tag) {
                        boost::asio::read(file, reinterpret_cast<char*>(tag), sizeof(CRC_INDICATION_REL8_TAG));

                        tag->crcflag = !tag->crcflag; // Flip CRCFLAG for deserialization
                        records_[offset] = tag;
                    } else {
                        log_error("Memory allocation failure during deserialization");
                        deallocate(pdu);
                        break;
                    }
                } else {
                    log_error("Memory allocation failure during deserialization");
                    break;
                }
            }

            if (compress_) {
                compressor.pop();
            }
        } else {
            log_error("Failed to open file for reading");
        }
    }

private:
    boost::pool<void> pool;
    std::map<size_t, void*> records_;
    size_t numRecords_;
    bool compress_;
};
