        perror("mmap failed");
        exit(EXIT_FAILURE);
    }
    for (size_t i = 0; i < n; ++i) {
        records[i].offset = i;
        records[i].key = i;
        records[i].value = (float)(rand() % RAND_MAX / 100.0f * 2 - 1);
    }
    return records;
}

void free_records(record* records, size_t n) {
    munmap(records, sizeof(record) * n);
}
