#include <stdexcept>

void insertAfterOrAppend(std::forward_list<std::string>& list, const std::string& key, const std::string& value) {
    auto it = list.begin();
    auto prevIt = list.before_begin();

    while (it != list.end()) {
        if (*it == key) {
            prevIt = it;
            ++it;
            break;
        }
        ++prevIt;
        ++it;
    }

    if (it == list.end()) {
        list.insert_after(prevIt, value);
    } else {
        list.insert_after(it, value);
    }
}
