#include <pthread.h>
#include <time.h>

typedef struct Record {
    long offset;
    int key;
    float value;
} Record;

// Custom memory pool
struct MemBlock {
    void* data;
    size_t size;
    struct MemBlock* next;
};

struct MemPool {
    struct MemBlock head, tail;
    size_t total_size;
    size_t max_size;
};

void mempool_init(struct MemPool* pool, size_t max_size) {
    pool->head.next = &pool->tail;
    pool->tail.data = NULL;
    pool->total_size = 0;
    pool->max_size = max_size;
}

void* mempool_alloc(struct MemPool* pool, size_t size) {
    if (pool->total_size + size > pool->max_size) return NULL;

    struct MemBlock* current = &pool->head;
    while (current->next != &pool->tail && current->next->size > 0) current = current->next;

    if (current->next != &pool->tail) {
        void* result = current->next->data;
        current->next->size -= size;
        pool->total_size += size;
        return result;
    }

    struct MemBlock* new_block = malloc(sizeof(struct MemBlock) + size);
    if (!new_block) return NULL;

    new_block->size = size;
    current->next = new_block;
    pool->total_size += size;
    return new_block->data;
}

void mempool_free(struct MemPool* pool, void* ptr) {
    struct MemBlock* current = &pool->head;
    while (current->next != &pool->tail) {
        if (current->next->data == ptr) {
            current->next->size += sizeof(struct MemBlock);
            current->next->data = NULL;
            pool->total_size -= sizeof(struct MemBlock);
            break;
        }
        current = current->next;
    }
}

// Thread-safe locking mechanism using spin locks
pthread_spinlock_t lock;

void lock_init() {
    pthread_spin_init(&lock, 0);
}

void lock_acquire() {
    pthread_spin_lock(&lock);
}

void lock_release() {
    pthread_spin_unlock(&lock);
}

// Function to initialize an array of records
