    for (size_t i = 0; i < n; ++i) {
        records[i].offset = i;
        records[i].key = i;
        records[i].value = rand() / (RAND_MAX + 1.0f) * 2 - 1;
    }
}

// Function to validate memory usage within the 1MB limit
bool validate_memory(struct MemPool pool) {
    size_t overhead = sizeof(struct MemBlock) * 2 + sizeof(void*) * 3; // approximate overhead for system libraries and alignment
    return pool.total_size + overhead <= (1 << 20); // 1MB in bits
}

int main() {
    lock_init();

    struct MemPool mempool;
    mempool_init(&mempool, (1 << 20) - sizeof(struct MemPool));

    size_t n = 100000;
    size_t m = 100000;
    size_t p = 100000;

    Record* records = mempool_alloc(&mempool, sizeof(Record) * n);
    if (!records) {
        fprintf(stderr, "Memory allocation failed\n");
        return 1;
    }

    lock_acquire();
    init_records(records, n);
    lock_release();

    // Populate the memory usage and validate it
    // ...

