std::mutex mtx;

struct Transaction {
    std::string type;
    double amount;
};

using Transactions = std::vector<Transaction>;
using UserTransactions = std::map<std::string, Transactions>;

int processUserTransactionsAndHash(const std::string& resourceFile, const std::string& apiUrl, int timeout_ms, int maxRetries, const std::string& inputStr) {
    UserTransactions userTransactions;
    std::ifstream file(resourceFile);
    if (!file.is_open()) return 1; // File not found error code

    std::string line;
    while (std::getline(file, line)) {
        auto transaction = parseTransaction(line);
        if (!transaction) continue; // Invalid transaction error code

        std::lock_guard<std::mutex> lock(mtx);
        userTransactions[transaction->user].push_back(*transaction);
    }

    boost::asio::io_context ioc;
    boost::beast::http::io_service httpService(ioc);

    UserTransactions processedTransactions;
    std::vector<std::future<bool>> requests;

    for (const auto& [user, transactions] : userTransactions) {
        for (size_t i = 0; i < transactions.size(); ++i) {
            auto transaction = transactions[i];
            auto req = httpService.make_request<boost::beast::http::verb::post>(apiUrl, 10);
            req.set(boost::beast::http::field::host, "your-api-host");
            req.set(boost::beast::http::field::user_agent, BOOST_BEAST_VERSION_STRING);
            req.set(boost::beast::http::field::content_type, boost::beast::http::mime::json);

            auto body = boost::beast::http::string_body();
            body.assign(transaction.serialize().data(), transaction.serialize().size());
            req.set(boost::beast::http::field::content_length, std::to_string(body.size()));
            req.prepare(boost::asio::buffer(body));

            requests.push_back(ioc.submit([req, transaction]() {
                bool success = false;
                boost::beast::http::response<boost::beast::http::string_body> res;
                try {
                    httpService.run(req);
                    res = req.result();
                    if (res.result() != boost::beast::http::status::ok) return false;
                    success = true;
                } catch (const std::exception& e) {
                    std::cerr << "Error: " << e.what() << std::endl;
                }

                if (!success) {
                    if (--maxRetries > 0) {
                        std::this_thread::sleep_for(std::chrono::milliseconds(std::pow(2, maxRetries)));
                        return processUserTransactionsAndHash(resourceFile, apiUrl, timeout_ms, maxRetries - 1, inputStr);
                    } else {
                        std::cerr << "Max retries exceeded" << std::endl;
                    }
                }

                processedTransactions[transaction.user].push_back(transaction);
                return success;
            }));
        }
    }

    ioc.run();

    for (auto& future : requests) {
        if (!future.get()) return 2; // API request error code
    }

    Transactions aggregatedTransactions;
    for (const auto& [user, transactions] : processedTransactions) {
        double totalAmount = 0;
        std::map<std::string, int> transactionCounts;

        for (const auto& transaction : transactions) {
            totalAmount += transaction.amount;
            transactionCounts[transaction.type]++;
        }

        aggregatedTransactions.push_back({user, totalAmount, transactionCounts});
    }

    std::string md5Hash = boost::algorithm::md5_hex(inputStr);

    // Generate and return the summary report
    // ...

    return 0; // Success code
}
```

