class StringGenerator {
    private $charset = '!@#$%^&*()-_=+[]{}|;:"<>?/';
    private $algorithms = ['bcrypt', 'sha256', 'md5', 'custom'];

    public function generateRandomHashedString($length, $charset = null, $hashAlgorithm = 'bcrypt') {
        if (!in_array($hashAlgorithm, $this->algorithms)) {
            throw new Exception("Invalid hash algorithm: {$hashAlgorithm}");
        }

        $randomString = $this->generateRandomString($length, $charset);
        $hashedString = null;

        switch ($hashAlgorithm) {
            case 'bcrypt':
                $salt = base64_encode(random_bytes(32));
                $hashedString = password_hash($randomString . $salt, PASSWORD_BCRYPT);
                break;
            case 'sha256':
                $hashedString = hash('sha256', $randomString, true);
                break;
            case 'md5':
                $hashedString = md5($randomString);
                break;
            default: // custom algorithm
                $this->log("Custom hashing method not implemented yet.");
                break;
        }

        $this->log("Generated and hashed string: {$randomString} => {$hashedString}");

        return $hashedString;
    }

    private function generateRandomString($length, $charset = null) {
        if ($charset === null) {
            $charset = $this->charset;
        }

        $randomString = '';
        for ($i = 0; $i < $length; $i++) {
            $randomString .= $charset[rand(0, strlen($charset) - 1)];
        }

        return $randomString;
    }

