```javascript
async function readFileSync(file, encoding = 'utf8', mode = 'r') {
    try {
        const fs = require('fs');
        const filePath = path.join(__dirname, 'docs', file);
        let fileContent;

        switch (encoding) {
            case 'utf8':
                fileContent = await fs.promises.readFile(filePath, mode);
                break;
            case 'utf16':
                fileContent = await fs.promises.readFile(filePath, 'utf16le', mode);
                break;
            case 'iso88591':
                fileContent = await fs.promises.readFile(filePath, 'iso-8859-1', mode);
                break;
            default:
                console.error(`Unsupported encoding: ${encoding}`);
                return Promise.reject(new Error('Unsupported encoding'));
        }

