#include <cstring>

struct Record {
    int key;
    long offset;
    std::string data;
    std::atomic_int refCount{1};

    ~Record() {
        if (--refCount == 0) delete this;
    }
};

void initRecords(std::vector<Record>& records, int n) {
    records.resize(n);

    std::default_random_engine generator;
    std::uniform_int_distribution<int> distributionKey(1, 100);
    std::uniform_int_distribution<long> distributionOffset(0, 1000000000L);
    std::uniform_int_distribution<std::streamsize> distributionDataLength(10, 50);

    std::mutex mtx;

    for (auto& record : records) {
        record.key = distributionKey(generator);
        record.offset = distributionOffset(generator);
        record.data.resize(distributionDataLength(generator));
        std::generate_n(record.data.begin(), distributionDataLength(generator), []() -> char { return 'a' + rand() % 26; });

        // Ensure thread-safety when modifying the refCount
        std::lock_guard<std::mutex> lock(mtx);
        record.refCount++;
    }
}
```

This code creates a `Record` structure with fields for an integer key, long offset, and string data. It also includes a reference count to manage memory cleanup using a simple reference counting system. The `initRecords()` function initializes the records with random values and ensures thread-safety when modifying the refCount.

