        for (int i = 0; i < num_offsets - 1; ++i) {
            if ((char*)&records[i] + sizeof(record) * i != (char*)&records[i + 1]) {
                fprintf(stderr, "Memory overflow detected.\n");
                goto cleanup;
            }
        }
    }

cleanup:
    if (validate_memory && num_offsets > 0) {
        free(records);
