#include <stdio.h>
#include <stdlib.h>
#include <pthread/pthread.h>
#include <time.h>

typedef struct Record {
    int value;
    struct Record *next;
} Record;

Record* initialize_records(int num_offsets, int validate_memory, int max_value_threshold) {
    pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;
    long* offsets = NULL;
    int* keys = NULL;
    Record** records = NULL;

    if (!(offsets = malloc(num_offsets * sizeof(long)))) {
        log_failure("Failed to allocate memory for offsets");
        goto cleanup;
    }

    if (!(keys = malloc(num_offsets * sizeof(int)))) {
        log_failure("Failed to allocate memory for keys");
        free(offsets);
        goto cleanup;
    }

    records = calloc(num_offsets, sizeof(Record*));
    if (!records) {
        log_failure("Failed to allocate memory for records");
        free(keys);
        free(offsets);
        goto cleanup;
    }

    for (int i = 0; i < num_offsets; ++i) {
        offsets[i] = i * 5;
        keys[i] = i + 10;
        records[i] = NULL;
    }

    srand(time(NULL));

    for (int i = 0; i < num_offsets; ++i) {
        Record* current = malloc(sizeof(Record));
        if (!current) {
            log_failure("Failed to allocate memory for record");
            free_records(records, i);
            free(keys);
            free(offsets);
            goto cleanup;
        }

        current->value = generate_random(1, 100);
        if (validate_memory && current->value > max_value_threshold) {
            log_failure("Value exceeded the specified threshold");
            free(current);
            free_records(records, i);
            free(keys);
            free(offsets);
            goto cleanup;
        }

        pthread_mutex_lock(&mutex);
        current->next = records[i];
        records[i] = current;
        pthread_mutex_unlock(&mutex);
    }

cleanup:
    if (records) free(records);
    return records;
}

void free_records(Record** records, int index) {
    Record* current = records[index];
    while (current != NULL) {
        Record* temp = current;
        current = current->next;
        free(temp);
    }
}

void log_success(const char* message) {
    // Implement logging for successful allocations here.
}

void log_failure(const char* message) {
    // Implement logging for memory allocation failures here.
}
```

This implementation uses a linked list to store the records, which allows for efficient memory usage and cache locality when dealing with large datasets. The `pthread_mutex_t` is used to ensure thread safety during concurrent calls.']

