void generate_random(int* out, int min, int max) {
    *out = rand() % (max - min + 1) + min;
}

void* allocate(size_t size, size_t chunk_size, size_t* used, size_t* total, size_t max_memory_usage) {
    void* ptr = malloc(size);
    if (!ptr) return NULL;

    *used += size;
    if (*used > *total) {
        *total = *used;
        while (*total % chunk_size != 0) *total += chunk_size;
    }

    if (*total > max_memory_usage) {
        free(ptr);
        return NULL;
    }

    return ptr;
}

void deallocate(void* ptr, size_t* used, size_t* total) {
    free(ptr);
    *used -= sizeof(*ptr);
    if (*used > 0 && *used % (*total) == 0) *total = *used;
}

