        ds->offsets[i + 1] = ds->offsets[i] + 1;
    }
    ds->offsets[ds->capacity] = ds->size + 1;
}

void resize_data_struct(struct DataStruct* ds, size_t new_capacity) {
    if (new_capacity <= ds->capacity) return;

