#include <time.h>
#include <stdlib.h>
#include <ctype.h>

char* generate_unique_filename(const char* filename) {
    size_t len = strlen(filename);
    if (len > 256 || len == 0) return NULL;

    char ext[5] = {'.', 't', 'x', 't', '\0'};
    char* base = malloc(len + 19);
    strncpy(base, filename, len);

    // Replace special characters with underscores
    for (size_t i = 0; i < len; ++i) {
        if (!isalnum(base[i]) && base[i] != '.') base[i] = '_';
    }

    // Determine file extension
    char* ext_ptr = strrchr(base, '.');
    if (ext_ptr == NULL) {
        ext_ptr = &base[len];
        *ext_ptr++ = '.';
    } else {
        ext_ptr++;
    }

    // Generate timestamp and random number
    char timestamp[19];
    time_t now = time(NULL);
    strftime(timestamp, sizeof(timestamp), "%Y%m%d%H%M%S", localtime(&now));
    char rand_num[5];
    snprintf(rand_num, sizeof(rand_num), "%04d", (int)strtoll(timestamp, NULL, 16) % 10000);

    // Combine and check for overflow
    size_t new_len = len + strlen(timestamp) + strlen(rand_num) + strlen(ext) + 2;
    if (new_len > 256) {
        base[len - 1] = '\0';
        strcat(base, "...");
    }

    // Append timestamp, random number, and extension
    strncat(base, timestamp, strlen(timestamp));
    strncat(base, rand_num, strlen(rand_num));
    strncat(base, ext, strlen(ext));

    return base;
}
