**Python Class (PduManager.py)**

```python
import json
from collections import defaultdict

class PduManager:
    def __init__(self):
        self._pdus = defaultdict(lambda: {})
        self._factories = {}

    def register_factory(self, identifier, factory):
        self._factories[identifier] = factory

    def create_pdu(self, identifier, **kwargs):
        if identifier not in self._factories:
            raise ValueError(f"Unknown PDU factory with identifier {identifier}")

        return self._factories[identifier](**kwargs)

    def serialize(self, pdu):
        return json.dumps(pdu.__dict__)

    def deserialize(self, data):
        return eval(data)

    def save_pdus(self, filename):
        with open(filename, 'w') as f:
            for identifier, pdus in self._pdus.items():
                for pdu_id, pdu in pdus.items():
                    serialized_pdu = self.serialize(pdu)
                    f.write(f"{identifier}:{pdu_id}:{serialized_pdu}\n")

    def load_pdus(self, filename):
        with open(filename, 'r') as f:
            for line in f:
                identifier, pdu_id, serialized_pdu = line.split(":")
                pdu = self.deserialize(serialized_pdu)
                if identifier not in self._pdus:
                    self._pdus[identifier] = {}
                self._pdus[identifier][pdu_id] = pdu
```

