    if (records == NULL) {
        perror("calloc failed");
        free(keys);
        munmap(offsets, offset_size);
        return -1;
    }

    pthread_mutex_init(mutex, NULL);

    srand(time(NULL));
    for (size_t i = 0; i < record_size; ++i) {
        records[i].value = rand() % MAX_RANDOM_VALUE;
        records[i].timestamp = time(NULL);
    }

    return 0;
