import re
from passlib.hash import sha256_crypt

class PasswordDAO:
    def __init__(self, db):
        self.db = db

    def validate(self, password):
        # Complexity check, length check, uniqueness check
        if not re.match(r'^(?=.*[a-z])(?=.*[A-Z])(?=.*\d)(?=.*[@$!%*?&]).{8,}$', password):
            return False

        hashed_password = sha256_crypt.hash(password)
        if self.db.get(hashed_password) is not None:
            return False

        return True

    def update(self, user_id, password):
        if self.validate(password):
            hashed_password = sha256_crypt.hash(password)
            self.db[hashed_password] = user_id

