struct MemoryBlock {
    void* data;
    struct MemoryBlock* next;
};

static struct MemoryBlock* free_list = NULL;

void* my_malloc(size_t size) {
    if (free_list == NULL || free_list->next != NULL && free_list->next->size < size) {
        void* new_block = mmap(NULL, size + sizeof(struct MemoryBlock), PROT_READ | PROT_WRITE, MAP_PRIVATE | MAP_ANONYMOUS, -1, 0);
        if (new_block == MAP_FAILED) {
            // Handle allocation failure
        }
        struct MemoryBlock* new_node = (struct MemoryBlock*)((char*)new_block + sizeof(struct MemoryBlock));
        new_node->size = size;
        new_node->next = free_list;
        free_list = new_node;
    }
    return ((char*)free_list + sizeof(struct MemoryBlock));
}

void my_free(void* ptr) {
    struct MemoryBlock* node = (struct MemoryBlock*)((char*)ptr - sizeof(struct MemoryBlock));
    if (node->next != NULL) {
        node->next->next = free_list;
    }
    node->next = free_list;
    free_list = node;
}
