[' Here's a C++ code implementation that meets your requirements using the Standard Template Library (STL) for thread safety and dynamic memory allocation:

```cpp
#include <iostream>
#include <vector>
#include <memory>
#include <random>
#include <mutex>
#include <map>

struct Key {
    int id;
};

struct Offset {
    long value;
    std::shared_ptr<Key> key;
};

struct Record {
    int value;
    std::unique_ptr<Offset> offset;
    std::atomic<int> refCount{ 0 };
    std::mutex mtx;
};

std::vector<std::unique_ptr<Record>> createRecords(size_t size, long minOffset, long maxOffset) {
    std::vector<std::unique_ptr<Record>> records;
    std::default_random_engine generator;
    std::uniform_int_distribution<int> distribution(0, INT_MAX);

    for (size_t i = 0; i < size; ++i) {
        auto record = std::make_unique<Record>();
        record->value = distribution(generator);
        record->offset.reset(new Offset{});
        record->offset->value = minOffset + generator() % (maxOffset - minOffset + 1);
        record->refCount = 1;
        records.push_back(std::move(record));
    }

    return records;
}

void initializeRecords(std::vector<std::unique_ptr<Record>>& records, std::map<int, std::shared_ptr<Key>> keys) {
    std::for_each(records.begin(), records.end(), [&](auto& record) {
        auto it = keys.find(record->value);
        if (it != keys.end()) {
            record->offset->key = it->second;
        } else {
            std::cerr << "Error: Key not found for value: " << record->value << std::endl;
        }
    });
}

std::unique_ptr<Record> getRecord(int key, std::map<int, std::shared_ptr<Key>> keys, std::vector<std::unique_ptr<Record>> records) {
    auto it = keys.find(key);
    if (it != keys.end()) {
        std::lock_guard<std::mutex> lock(it->second->offset->offset->mtx);
        for (auto& record : records) {
            if (record->offset->key == it->second) {
                record->refCount++;
                return std::move(record);
            }
        }
    } else {
        std::cerr << "Error: Key not found" << std::endl;
    }

    return nullptr;
}

void releaseRecord(std::unique_ptr<Record> record) {
    if (record && --record->refCount == 0) {
        delete record.release();
    }
}
```

