[' Due to the complexity of the task, I will provide a high-level design and code snippets for key components. For a complete implementation, you would need to integrate these pieces and address edge cases.

1. Custom Allocator:

```c
#include <stdlib.h>
#include <stdio.h>

typedef struct Block {
    size_t size;
    struct Block* next;
} Block;

Block* allocator = NULL;
size_t total_allocated = 0;
const size_t MAX_MEMORY = 1024 * 1024; // 1MB

void init_allocator() {
    if (allocator) return;
    allocator = malloc(sizeof(Block));
    allocator->size = 0;
    allocator->next = NULL;
}

void* custom_malloc(size_t size) {
    if (total_allocated + size > MAX_MEMORY) {
        fprintf(stderr, "Error: Memory allocation exceeded the limit of 1MB\n");
        return NULL;
    }

    Block* current = allocator;
    while (current && current->size < size) {
        current = current->next;
    }

    if (!current) {
        current = malloc(sizeof(Block));
        if (!current) {
            fprintf(stderr, "Error: Failed to allocate memory\n");
            return NULL;
        }
        current->size = 0;
        current->next = allocator;
        allocator = current;
    }

    void* result = (void*)((char*)current + current->size);
    current->size += size;
    total_allocated += size;
    return result;
}
```

