[' Here's a C++ code example that meets your requirements using the `std::vector` for dynamic memory allocation, `<random>` for generating random numbers, and `boost::log` for logging. I've used Boost Log instead of an external library as it is widely adopted and well-documented.

```cpp
#include <iostream>
#include <vector>
#include <random>
#include <boost/log/trivial.hpp>
#include <boost/log/expressions.hpp>
#include <boost/log/utility/setup/file_manager.hpp>
#include <boost/log/utility/setup/common_attributes.hpp>
#include <boost/log/sources/severity_logger.hpp>
#include <boost/log/sources/record_ostream.hpp>

namespace logging = boost::log;
using namespace boost::log::trivial;
using namespace boost::log::expressions;
using namespace boost::log::sources;
using namespace boost::log::utility;
using namespace std;

struct Record {
    int value;
};

class MemoryManager {
public:
    MemoryManager(size_t offsetSize, size_t keySize, size_t recordSize, size_t initialCapacity)
        : _offsets(_initialCapacity * offsetSize), _keys(_initialCapacity * keySize), _records(_initialCapacity) {
        if (initializeRecords()) {
            BOOST_LOG_TRIVIAL(info) << "Memory Manager initialized with capacity: " << _initialCapacity;
        } else {
            BOOST_LOG_TRIVIAL(error) << "Failed to initialize Memory Manager";
        }
    }

    ~MemoryManager() {
        deallocate();
        BOOST_LOG_TRIVIAL(info) << "Memory Manager destroyed";
    }

    void resize(size_t newCapacity) {
        if (newCapacity > _currentCapacity) {
            reallocate(newCapacity);
        }
    }

private:
    bool initializeRecords() {
        for (auto& record : _records) {
            record.value = rand() % 100;
        }
        return true;
    }

    void deallocate() {
        _offsets.clear();
        _keys.clear();
        _records.clear();
    }

    void reallocate(size_t newCapacity) {
        vector<long> tempOffsets(_newCapacity * sizeof(long));
        vector<int> tempKeys(_newCapacity * sizeof(int));
        vector<Record> tempRecords(_newCapacity);

        if (newCapacity > _initialCapacity) {
            copy(_offsets.data(), _offsets.data() + _currentCapacity * sizeof(long), tempOffsets.data());
            copy(_keys.data(), _keys.data() + _currentCapacity * sizeof(int), tempKeys.data());
            copy(_records.begin(), _records.end(), tempRecords.begin());
        }

        deallocate();
        _offsets = move(tempOffsets);
        _keys = move(tempKeys);
        _records = move(tempRecords);
        _currentCapacity = newCapacity;
    }

    vector<long> _offsets;
    vector<int> _keys;
    vector<Record> _records;
    size_t _initialCapacity = 0;
    size_t _currentCapacity = 0;
};

int main() {
    logging::add_file_log(
        keywords::file_name = "memory_manager.log",
        keywords::rotation_size = 10 * 1024 * 1024,
        keywords::time_based_rotation = sinks::file::rotation_at_time_point(0, 0, 0),
        keywords::format = "[%TimeStamp%][%ThreadId%] %Message%");

    MemoryManager manager(sizeof(long), sizeof(int), sizeof(Record::value), 10);

    // Use the memory manager here...

    return 0;
}
```

This code creates a `MemoryManager` class that dynamically allocates and initializes three contiguous blocks of memory for offsets, keys, and records. It uses `std::vector` to handle dynamic memory requirements and reallocates memory if the initial allocation proves insufficient. The logging system is implemented using Boost Log, which is thread-safe and non-disruptive to the performance-critical sections of the code.']

