std::map<int, int> process_log(const std::string& file_path) {
    std::ifstream file(file_path);
    std::map<int, int> status_counts;
    std::regex http_status_regex{R"(HTTP/\d+\.\d+ \d{3})"};

    std::mutex mtx;
    int cooldown = 0;
    std::vector<std::string> attacks = {"Attack1", "Attack2"};
    std::random_device rd;
