            if (status_code >= 418 && status_code <= 599) continue;
            mtx.lock();
            status_counts[status_code / 100]++;
            mtx.unlock();
        }

        // Simulate cooldown and random attack selection
        if (cooldown > 0) {
            --cooldown;
        } else {
            mtx.lock();
            int attack_index = dis(gen);
            std::cout << "Thread: Performing attack: " << attacks[attack_index] << std::endl;
