      {settings.map((setting) => (
        <div key={setting.key}>
          <label htmlFor={setting.key}>{setting.label}</label>
          <input
            id={setting.key}
            name={setting.key}
            type="radio"
            value={setting.value}
            checked={localSettings[setting.key] === setting.value}
