void insertAfterTarget(std::forward_list<std::string>& list, const std::string& target, const std::string& insertion) {
    auto it = list.begin();
    if (it == list.end()) {
        list.push_back(insertion);
        return;
    }

    while (it != list.end() && *it != target) {
        ++it;
    }

    if (it == list.end()) {
        list.push_back(insertion);
        return;
    }

    list.insertAfter(it, insertion);
}
