    this.processData();
  }

  processData() {
    if (this.dataChunks.length === 0) return;

    const [chunk, ...remaining] = this.dataChunks;
    const priority = this.config.priorityFunction(chunk);

    this.memoryUsage += chunk.size;

    if (this.memoryUsage > this.env.memoryLimit) {
      console.warn(`Memory usage exceeded: ${this.memoryUsage} / ${this.env.memoryLimit}`);
    }

    this.dataChunks = remaining;
    this.totalProcessed++;

    if (priority === 'high') {
      this.processHighPriority(chunk);
    } else {
      setTimeout(() => this.processData(), 0);
    }
  }

  processHighPriority(chunk) {
    try {
      // Process high-priority data here
      console.log(`Processing high-priority chunk: ${JSON.stringify(chunk)}`);
      this.messageBus.send('high-priority-processed', chunk);
      this.memoryUsage -= chunk.size;
    } catch (error) {
      console.error(`Error processing high-priority chunk: ${error}`);
    } finally {
      this.resumeDataProcessing();
    }
  }

  resumeDataProcessing() {
    clearTimeout(this.pauseTimer);
    clearTimeout(this.resumeTimer);

    if (this.dataChunks.length > this.config.maxBufferSize) {
      const chunkToDrop = this.dataChunks.shift();
      console.warn(`Dropping chunk due to buffer overflow: ${JSON.stringify(chunkToDrop)}`);
    }

    if (this.dataChunks.length > 0) {
      this.pauseTimer = setTimeout(() => {
        this.messageBus.send('service-paused');
      }, this.intervalDuration);

      this.resumeTimer = setTimeout(() => {
        this.processData();
      }, Math.random() * 4000 + 1000);
    }
  }
}
```

This implementation uses a class to encapsulate the data processor functionality, making it easier to manage state and behavior. The `DataProcessor` constructor accepts the required parameters and initializes the necessary variables. The `processData()` method is responsible for managing the buffer, prioritizing high-priority chunks, monitoring memory usage, and handling errors gracefully.

The `processHighPriority()` method processes high-priority data, while the `resumeDataProcessing()` method manages pauses and resumes in the service. The class also includes methods to send messages to a message bus for status updates."]

