  let filePointer = fs.createReadStream(file, { encoding: 'utf8', highWaterMark: chunkSize });

  debounceInterval = setInterval(() => processChunk(filePointer), 500);

  async function processChunk(stream) {
    try {
      const chunk = await new Promise((resolve, reject) => {
        let data = '';
        stream.on('data', (chunk) => {
          data += chunk;
          if (data.includes('\n')) resolve(data.split('\n'));
        });
        stream.on('end', () => resolve(['']));
      });

