    visitedElements.add(element.id); // Store the visited element's id for optimized performance

    let matches = [];
    if (element.matches && element.matches(selector)) matches.push(element);

    for (let child of element.children) {
      matches = matches.concat(await traverseDOM(child, selector));
    }

    return matches;
  }

  async function updateDatabase(clinicId) {
    try {
      const elements = await traverseDOM(document.body, selector);
      const visitedElementsArray = Array.from(visitedElements);
      const unvisitedElements = _.difference(elements, visitedElementsArray);

      for (let element of unvisitedElements) {
        const ipAddress = getIPAddress(element); // Assuming you have a function to get the IP address here
        await db.updateClinicLog(clinicId, element.id, ipAddress, new Date());
      }
    } catch (error) {
      console.error(`Error updating database: ${error}`);
    }
  }

  updateDatabase(clinicId); // Update the database initially
}
