// Define constants and structures
#define CACHE_SIZE 1000
#define THEME_DIR "theme_cache"
#define MAX_OFFSET (CACHE_SIZE * sizeof(long))
#define KEY_SIZE 32
#define THEME_METADATA_SIZE 64
#define MIN_DISK_SPACE 1024 * 1024 // 1 MB
#define RANDOM_RANGE 100

typedef struct {
    long offset;
    int key[KEY_SIZE];
    int metadata;
} record;

// External storage service functions (not provided)
void update_theme(const char* key, const char* theme);
bool has_network();

// Helper functions (not provided)
void parse_png(const char* path, record* record);
bool check_disk_space();
void clean_cache();
bool is_valid_theme(const char* path);

pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;
long offsets[MAX_OFFSET] = {0};
record cache[CACHE_SIZE];
int num_records = 0;
char theme_dir[256] = THEME_DIR;

// Function to set a random value for each record's metadata field
void set_random_metadata(record* record) {
    record->metadata = rand() % RANDOM_RANGE;
}

// Function to manage theme caching
record* get_theme(const char* key) {
    pthread_mutex_lock(&mutex);

    for (int i = 0; i < num_records; ++i) {
        record* current = &cache[i];

        if (current->metadata == -1) continue; // Recycling slot

        bool match = true;
        for (int j = 0; j < KEY_SIZE && match; ++j) {
            if (current->key[j] != key[j]) match = false;
        }

        if (match) { // Cache hit
            return current;
        }
    }

    pthread_mutex_unlock(&mutex);

    // Cache miss, search for an empty slot or recycle a theme
    for (int i = 0; i < num_records; ++i) {
        if (cache[i].metadata == -1) {
            record* current = &cache[i];
            parse_png(sprintf(theme_dir "/%ld", offsets[i]), current);
            set_random_metadata(current);
            current->offset = offsets[i];
            for (int j = 0; j < KEY_SIZE; ++j) {
                current->key[j] = key[j];
            }
            return current;
        }
    }

    // All slots are full, clean up old themes and recycle a slot
    if (num_records >= CACHE_SIZE || !check_disk_space()) {
        clean_cache();
    }

    int new_index = num_records % CACHE_SIZE;
    record* new_record = &cache[new_index];
    parse_png(sprintf(theme_dir "/%ld", offsets[new_index]), new_record);
    set_random_metadata(new_record);
    new_record->offset = offsets[new_index];
    for (int j = 0; j < KEY_SIZE; ++j) {
        new_record->key[j] = key[j];
    }
    num_records++;

    return new_record;
}
```

