```python
import hashlib
import concurrent.futures
import os

class FileHasher:
    def __init__(self):
        self.lock = threading.Lock()
        self.hashes = {}

    def md5(self, file_path):
        if file_path not in self.hashes:
            with open(file_path, 'rb') as f:
                hasher = hashlib.md5()
                for chunk in iter(lambda: f.read(4096), b''):
                    hasher.update(chunk)
                self.hashes[file_path] = hasher.hexdigest()
        return self.hashes[file_path]

    def md5s(self, file_paths):
        with concurrent.futures.ThreadPoolExecutor() as executor:
            futures = {executor.submit(self.md5, file_path) for file_path in file_paths}
            return [future.result() for future in futures]
```

