[" Here's a basic outline for a JavaScript module that addresses the given requirements. I'll use `axios` for HTTP requests, `lodash` for utility functions, and `p-queue` for managing concurrent requests.

```javascript
const axios = require('axios');
const _ = require('lodash');
const Queue = require('p-queue');

class MetadataScraper {
  constructor(apis, priorityMap) {
    this.apis = apis;
    this.priorityMap = priorityMap || _.fromPairs(apis.map((api, index) => [index, Infinity]));
    this.queue = new Queue({ concurrency: 5 });
  }

  async scrape(selector, attribute, value, onMetadataReceived) {
    const elements = document.querySelectorAll(selector);

    const tasks = [];

    for (let element of elements) {
      if (element[attribute] === value) {
        const apiIndex = _.findKey(this.priorityMap, (priority) => priority < Infinity);
        const api = this.apis[apiIndex];
        const task = async () => {
          try {
            const metadata = await axios.get(`${api}/${element.id}`);
            onMetadataReceived(metadata.data, element);
          } catch (error) {
            console.error(`Error fetching metadata for ${element.id}:`, error);
            this.retry(apiIndex, element);
          }
        };
        tasks.push(task);
      }
    }

    if (tasks.length > 0) {
      await Promise.all(tasks);
    }
  }

  retry(apiIndex, element) {
    const newPriority = this.priorityMap[apiIndex] - 1;
    this.priorityMap[apiIndex] = newPriority < 0 ? Infinity : newPriority;
    this.queue.add(() => this.scrape(element.querySelectorAll(element.getAttribute('data-selector')), 'data-attribute', element.getAttribute('data-attribute'), (metadata, el) => {
      this.priorityMap[apiIndex] += 1;
      this.queue.cancelAll();
      this.scrape(el.querySelectorAll(element.getAttribute('data-selector')), 'data-attribute', element.getAttribute('data-attribute'), (metadata, el) => {
        onMetadataReceived(metadata, el);
      });
    }));
  }
}
```

This code defines a `MetadataScraper` class that takes an array of APIs and a priority map as constructor arguments. The `scrape()` method traverses the DOM tree, identifies elements with the specified attribute value, and adds tasks to the queue for each API in order of priority.

The `retry()` method handles errors by decreasing the priority of the affected API and retrying the request on the same element using a new instance of `scrape()`. This ensures that resources are released promptly after processing an element, and that the function can handle concurrent requests without overwhelming the server.

The module is designed to be easy to integrate into existing applications with clear documentation and examples. You can configure the priority of different APIs and the processing order of elements by providing a custom priority map when creating a new instance of `MetadataScraper`."]

