#include <chrono>
#include <random>
#include <vector>

class WeatherService {
public:
    virtual std::string getWeatherCondition() = 0;
};

class DummyWeatherService : public WeatherService {
public:
    std::string getWeatherCondition() override {
        static const std::vector<std::string> conditions = {"Sunny", "Rainy", "Snowy"};
        return conditions[rand() % 3];
    }
};

class Cache {
public:
    void put(const std::string& key, const std::string& value) {
        data[key] = value;
        lastUpdate = std::chrono::system_clock::now();
    }

    std::string get(const std::string& key) {
        if (data.count(key)) {
            auto age = std::chrono::system_clock::now() - lastUpdate;
            if (age > std::chrono::minutes(5)) {
                data.erase(key);
            }
            return data[key];
        }
        return "";
    }

private:
    std::unordered_map<std::string, std::string> data;
    std::chrono::system_clock::time_point lastUpdate;
};

void selectWeatherCondition(Cache& cache, WeatherService* service) {
    auto condition = service->getWeatherCondition();
    if (!cache.get(condition).empty()) {
        std::cout << "Using cached weather condition: " << condition << ", probability: 1\n";
    } else {
        cache.put(condition, "");
        std::cout << "Fetching new weather condition: " << condition << ", probability: unknown\n";
    }
}

int main() {
    WeatherService* service = new DummyWeatherService();
    Cache cache;

    for (size_t i = 0; i < 10; ++i) {
        selectWeatherCondition(cache, service);
        std::this_thread::sleep_for(std::chrono::minutes(5 / 2)); // Simulate a 5-minute delay
    }

    delete service;
    return 0;
}
```

