    private readonly IConfigurationRoot _configuration;
    private readonly ILogger<ApplicationManager> _logger;

    public ApplicationManager(IWebHostBuilder hostingBuilder, IConfigurationRoot configuration, ILogger<ApplicationManager> logger)
    {
        _hostingBuilder = hostingBuilder;
        _configuration = configuration;
        _logger = logger;
    }

    public void AddApplication(string applicationDirectory)
    {
        if (!Directory.Exists(applicationDirectory))
        {
            _logger.LogError($"The specified directory '{applicationDirectory}' does not exist.");
            return;
        }

        var webConfigPath = Path.Combine(applicationDirectory, "web.config");
        if (!File.Exists(webConfigPath))
        {
            _logger.LogError($"The application directory '{applicationDirectory}' is missing a required 'web.config' file.");
            return;
        }

        var webHost = _hostingBuilder
            .UseContentRoot(applicationDirectory)
            .UseConfiguration(_configuration.GetConfiguration(applicationDirectory))
            .Build();

        _webHosts.TryAdd(applicationDirectory, webHost);
        webHost.Start();
    }

    public void RemoveApplication(string applicationDirectory)
    {
        WebHost webHost;
        if (_webHosts.TryRemove(applicationDirectory, out webHost))
        {
            webHost.StopAsync().Wait();
        }
    }

