using System;
using System.Collections.Generic;
using System.IO;
using System.Security.Cryptography;
using System.Text;

public class EncryptionMethod
{
    public string Name { get; set; }
    public Func<byte[], byte[]> Decryptor { get; set; }
}

public class KeySource
{
    public string Name { get; set; }
    public Func<int, byte[]> GetKey { get; set; }
}

private static Dictionary<string, EncryptionMethod> _encryptionMethods = new Dictionary<string, EncryptionMethod>
{
    { "TripleDES", new EncryptionMethod { Name = "TripleDES", Decryptor = TripleDes.Create().Decrypt } },
    { "AES", new EncryptionMethod { Name = "AES", Decryptor = Aes.Create().Decrypt } },
    { "RSA", new EncryptionMethod { Name = "RSA", Decryptor = Rsa.Create().Decrypt } },
};

private static Dictionary<string, KeySource> _keySources = new Dictionary<string, KeySource>
{
    { "Service1", new KeySource { Name = "Service1", GetKey = Service1.GetKey } },
    { "Service2", new KeySource { Name = "Service2", GetKey = Service2.GetKey } },
    { "Database", new KeySource { Name = "Database", GetKey = Database.GetKey } },
};

public void HandleEncryptedMessages(IEnumerable<string> messages)
{
    foreach (var message in messages)
    {
        var header = message.Substring(0, 128); // Assuming a fixed-length header format
        var encryptedData = message.Substring(128);

        var encryptionMethod = _encryptionMethods[header.Split(':')[0]];
        var keySource = _keySources[header.Split(':')[1]];
        var keyLength = int.Parse(header.Split(':')[2]);
        var key = keySource.GetKey(keyLength);

        var hmac = new HMACSHA256(key);
        var hash = hmac.ComputeHash(Encoding.UTF8.GetBytes(encryptedData));
        var headerHash = Encoding.UTF8.GetBytes(header.Split(':')[3]); // Assuming a fixed-length hash in the header

        if (hash.SequenceEqual(headerHash))
        {
            var decryptedData = encryptionMethod.Decryptor(encryptedData, key, CryptoStreamMode.CipherText);
            // Process the decrypted data here
        }
        else
        {
            Console.WriteLine($"Invalid HMAC for message: {message}");
        }
    }
}
```

