[' Here's a simplified Rust program that meets your requirements using the Tokio library for asynchronous operations. Note that this code does not include specific error handling for all possible cases, but it provides a starting point for further development.

```rust
use std::env;
use std::ffi::{CString, CStr};
use std::fmt::Write;
use std::mem::MaybeUninit;
use std::os::unix::io::AsRawFd;
use std::ptr::null_mut;
use std::sync::Arc;
use tokio::fs::File;
use tokio::io::{AsyncReadExt, AsyncWriteExt};
use tokio::task::spawn_blocking;
use tokio::time::sleep;

const BUFFER_SIZE: usize = 4096;

#[repr(C)]
#[derive(Debug)]
struct Record {
    key: i32,
    offset: *mut libc::c_long,
    value: i32,
}

fn initialize_data(min: i32, max: i32, keys_fd: i32, offsets_fd: i32) -> Vec<Record> {
    let mut keys = vec![];
    let mut offsets = vec![];
    let mut records = vec![];

    let mut keys_buf = Vec::with_capacity(BUFFER_SIZE);
    let mut offsets_buf = Vec::with_capacity(BUFFER_SIZE);

    let mut keys_reader = File::from_fd(keys_fd).expect("Failed to create File from fd");
    let mut offsets_reader = File::from_fd(offsets_fd).expect("Failed to create File from fd");

    loop {
        keys_buf.clear();
        offsets_buf.clear();

        keys_reader.read_exact(&mut keys_buf).await.expect("Failed to read keys");
        offsets_reader.read_exact(&mut offsets_buf).await.expect("Failed to read offsets");

        if keys_buf.is_empty() || offsets_buf.is_empty() {
            break;
        }

        let num_records = std::cmp::min(keys_buf.len(), offsets_buf.len());

        for i in 0..num_records {
            let key = CStr::from_ptr(keys_buf.get_unchecked(i)).to_str_lossy().into_owned();
            let offset: libc::c_long = offsets_buf.get_unchecked(i);

            records.push(Record {
                key,
                offset: offset as *,
                value: rand::thread_rng().gen_range(min..=max),
            });
        }
    }

    keys.shrink_to_fit();
    offsets.shrink_to_fit();

    records
}

#[tokio::main]
async fn main() {
    let args: Vec<String> = env::args().collect();

    if args.len() < 4 {
        println!("Usage: {} function min max keys_file offsets_file", args[0]);
        return;
    }

    let function = CString::new(args[1].as_str()).unwrap();
    let min = args[2].parse::<i32>().unwrap();
    let max = args[3].parse::<i32>().unwrap();
    let keys_file = AsRawFd::from(open(args[4].as_str(), O_RDONLY, 0).unwrap());
    let offsets_file = AsRawFd::from(open(args[5].as_str(), O_RDONLY, 0).unwrap());

    match function.as_ptr() {
        b"initialize_data" => {
            let records = initialize_data(min, max, keys_file, offsets_file);
            // Process or return the records here
        }
        _ => println!("Unknown function: {}", function),
    }
}
```

