#include <stdlib.h>
#include <stdio.h>

typedef struct {
    void* data;
    size_t size;
    struct node* next;
} Node;

Node* mem_alloc(size_t size) {
    Node* node = (Node*)malloc(sizeof(Node));
    if (!node) {
        fprintf(stderr, "Memory allocation failed\n");
        return NULL;
    }
    node->data = malloc(size);
    if (!node->data) {
        free(node);
        fprintf(stderr, "Memory allocation for data failed\n");
        return NULL;
    }
    node->size = size;
    node->next = NULL;
    return node;
}

void mem_free(Node* node) {
    if (node) {
        free(node->data);
        free(node);
    }
}
```

2. Hash Table:

```c
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <time.h>

typedef struct {
    int data;
    time_t timestamp;
    int status;
    int ref_count;
} UserData;

struct hash_table {
    Node** buckets;
    size_t capacity;
    size_t size;
    pthread_mutex_t lock;
};

HashTable* create_hash_table(size_t capacity) {
    HashTable* table = (HashTable*)mem_alloc(sizeof(HashTable));
    if (!table) {
        fprintf(stderr, "Memory allocation for hash table failed\n");
        return NULL;
    }
    table->capacity = capacity;
    table->size = 0;
    table->buckets = (Node**)calloc(capacity, sizeof(Node*));
    if (!table->buckets) {
        free(table);
        fprintf(stderr, "Memory allocation for buckets failed\n");
        return NULL;
    }
    pthread_mutex_init(&table->lock, NULL);
    return table;
}

void destroy_hash_table(HashTable* table) {
    for (size_t i = 0; i < table->capacity; ++i) {
        Node* node = table->buckets[i];
        while (node) {
            Node* next = node->next;
            mem_free(node);
            node = next;
        }
    }
    free(table->buckets);
    pthread_mutex_destroy(&table->lock);
    mem_free(table);
}
```

