```c
typedef struct MemoryBlock {
    size_t size;
    struct MemoryBlock* next;
} MemoryBlock;

MemoryBlock* memoryPool = NULL;

void initMemoryPool() {
    // Initialize the memory pool with a few initial blocks of different sizes.
}

void* allocate(size_t size) {
    MemoryBlock* current = memoryPool;
    while (current != NULL) {
        if (current->size >= size) {
            void* result = (void*)current + sizeof(MemoryBlock);
            current->size -= size + sizeof(MemoryBlock);
            return result;
        }
        current = current->next;
    }

    // Allocate a new block from system memory if none is available in the pool.
    MemoryBlock* newBlock = malloc(sizeof(MemoryBlock) + size);
    if (newBlock == NULL) {
        // Handle allocation failure here.
    }
    newBlock->size = size;
    newBlock->next = memoryPool;
    memoryPool = newBlock;

    return (void*)newBlock + sizeof(MemoryBlock);
}

void deallocate(void* ptr, size_t size) {
    // Deallocate the memory back to the pool.
    // You'll need to keep track of the original MemoryBlock pointer to do this.
}
