```cpp
#include <iostream>
#include <vector>
#include <thread>
#include <mutex>
#include <cstdlib>
#include <algorithm>
#include <memory>

struct Record {
    int value;
    int* key;
    static std::vector<std::unique_ptr<Record>> cache;

    Record(int key, int value) : key(key), value(value) {}
};

std::vector<std::unique_ptr<Record>> Record::cache;

void initializeDataStructure(size_t offsetSize, size_t keySize, size_t recordSize, int threshold, int minValue, int maxValue) {
    std::vector<long> offsets(offsetSize);
    std::vector<int> keys(keySize);
    std::vector<std::unique_ptr<Record>> records(recordSize);

    for (size_t i = 0; i < recordSize; ++i) {
        int randomValue = minValue + rand() % (maxValue - minValue + 1);
        records[i] = std::make_unique<Record>(keys[i], randomValue);
        offsets[i] = i;
    }

    // Maintain the sum of all record values within the threshold
    int totalSum = 0;
    for (const auto& record : records) {
        totalSum += record->value;
    }

    if (totalSum > threshold) {
        std::cerr << "Error: The sum of all record values exceeds the specified threshold." << std::endl;
        exit(1);
    }

    // Cache frequently accessed records
    for (size_t i = 0; i < recordSize; ++i) {
        Record* recordPtr = records[i].get();
        if (std::find(Record::cache.begin(), Record::cache.end(), recordPtr) == Record::cache.end()) {
            Record::cache.push_back(std::move(records[i]));
        }
    }
}

// Thread-safe access to records using a mutex
std::mutex recordsMutex;

void readRecord(size_t index) {
    std::unique_lock<std::mutex> lock(recordsMutex);
    if (index < Record::cache.size()) {
        auto record = Record::cache[index];
        std::cout << "Record value: " << record->value << ", Key: " << *record->key << std::endl;
    } else {
        auto it = std::find_if(Record::cache.begin(), Record::cache.end(), [index](const auto& record) { return index < record->key; });
        if (it != Record::cache.end()) {
            auto record = *it;
            std::cout << "Record value: " << record->value << ", Key: " << *record->key << std::endl;
        } else {
            std::cerr << "Error: Requested record not found in the cache." << std::endl;
        }
    }
}

void writeRecord(size_t index, int newValue) {
    std::unique_lock<std::mutex> lock(recordsMutex);
    if (index < Record::cache.size()) {
        auto record = Record::cache[index];
        record->value = newValue;
        std::cout << "Record value updated." << std::endl;
    } else {
        auto it = std::find_if(Record::cache.begin(), Record::cache.end(), [index](const auto& record) { return index < record->key; });
        if (it != Record::cache.end()) {
            auto record = *it;
            record->value = newValue;
            std::cout << "Record value updated." << std::endl;
        } else {
            std::cerr << "Error: Requested record not found in the cache." << std::endl;
        }
    }
}
```

This code creates a `Record` structure that includes a pointer to its corresponding key. The `initializeDataStructure` function initializes the data structure, ensuring that the sum of all record values is within the given threshold. It also caches frequently accessed records for faster access.

The `readRecord` and `writeRecord` functions provide thread-safe access to the records using a mutex. They first check if the requested record is in the cache before performing the operation. If it's not found, they search the cache for the nearest record with a lower key.']

