    time_t timestamp;
    int refCount;
    bool inUse;
    mutex mtx;
};

struct DataRecord {
    std::vector<std::variant<int, std::string>> data;
    mutex mtx;
};

Offset offsets;
std::map<int, Key*> keys;

void init() {
    srand(time(nullptr));
}

Key* create_key(int id) {
    auto it = keys.find(id);
    if (it != keys.end()) return it->second;

    Key* key = new Key{id, time(nullptr), 0, false};
    keys[id] = key;
    offsets.keys.push_back(key);
    return key;
}

DataRecord* create_data_record() {
    DataRecord* dataRecord = new DataRecord();
    // Add random data elements within specified limits
    for (int i = 0; i < rand() % 100 + 50; ++i) {
        dataRecord->data.push_back(rand() % 2 ? std::to_string(rand()) : std::string(rand() % 20, 'a'));
    }
    return dataRecord;
}

void append_to_data_record(DataRecord* dataRecord, const std::variant<int, std::string>& value) {
    dataRecord->mtx.lock();
    dataRecord->data.push_back(value);
    dataRecord->mtx.unlock();
}

void remove_from_data_record(DataRecord* dataRecord, size_t index) {
    dataRecord->mtx.lock();
    dataRecord->data.erase(dataRecord->data.begin() + index);
    dataRecord->mtx.unlock();
}

void increment_key_refcount(Key* key) {
    key->refCount++;
}

void decrement_key_refcount(Key* key) {
    if (--key->refCount == 0) {
        delete key;
        keys.erase(key->id);
        auto it = std::find(offsets.keys.begin(), offsets.keys.end(), key);
        offsets.keys.erase(it);
    }
}

void safe_release_unused_keys() {
    for (auto& key : keys) {
        if (key.second->refCount == 0) {
            delete key.second;
            keys.erase(key);
        }
    }
}
