[' Here is a simplified C++ implementation of a LRU Cache using a doubly-linked list for efficient insertion, deletion, and lookup operations. The code uses `std::unique_ptr` to manage memory dynamically and `std::mutex` for thread safety.

```cpp
#include <iostream>
#include <list>
#include <unordered_map>
#include <memory>
#include <mutex>
#include <cstdlib>
#include <cstring>

struct Record {
    int key;
    long offset;
    signed char value;

    Record* prev;
    Record* next;
};

class LRUCache {
public:
    explicit LRUCache(size_t maxMemory) : _maxMemory(maxMemory), _memoryUsed(0) {}

    ~LRUCache() {
        for (auto& pair : _cache) {
            delete pair.second;
        }
    }

    Record* getOrCreate(int key, long offset, signed char value) {
        auto it = _cache.find(key);
        if (it != _cache.end()) {
            moveToFront(*it->second);
            it->second->value = value;
            it->second->offset = offset;
            return it->second;
        }

        auto newRecord = std::make_unique<Record>();
        newRecord->key = key;
        newRecord->offset = offset;
        newRecord->value = value;
        newRecord->prev = nullptr;
        newRecord->next = nullptr;

        if (_memoryUsed + sizeof(Record) > _maxMemory) {
            evictLeastRecentlyUsed();
        }

        _cache[key] = std::move(newRecord);
        addToFront(*_cache[key]);
        _memoryUsed += sizeof(Record);

        return _cache[key].get();
    }

private:
    void moveToFront(Record& record) {
        if (record.prev != nullptr) {
            record.prev->next = record.next;
        } else {
            _head = record.next;
        }

        if (record.next != nullptr) {
            record.next->prev = record.prev;
        } else {
            _tail = &record;
        }

        record.prev = nullptr;
        record.next = _head;
        _head = &record;
    }

    void addToFront(Record& record) {
        if (_head == nullptr) {
            _head = &record;
            _tail = _head;
        } else {
            record.next = _head;
            _head->prev = &record;
            _head = &record;
        }
    }

    void evictLeastRecentlyUsed() {
        if (_tail == nullptr) return;

        auto it = --_cache.end();
        delete it->second;
        _cache.erase(it);
        _memoryUsed -= sizeof(Record);
    }

    size_t _maxMemory;
    size_t _memoryUsed;
    std::list<Record> _records;
    std::unordered_map<int, std::unique_ptr<Record>> _cache;
    Record* _head = nullptr;
    Record* _tail = nullptr;
};
```

This implementation uses a doubly-linked list to manage the records and an unordered map for fast lookups. The `getOrCreate` function handles both getting existing records and creating new ones when necessary, moving the least recently used record out of the cache if the memory limit is exceeded.

To integrate this into your existing system, you can create a global instance of the LRUCache class and provide functions for accessing it from multiple threads. Ensure that these functions use `std::unique_lock` to acquire a lock on the mutex before modifying the cache data.']

