// Custom memory pool for efficient memory management
typedef struct MemPool {
    void* data;
    size_t capacity;
    size_t allocated;
} MemPool;

void mempool_init(MemPool* pool, size_t initial_size) {
    pool->data = malloc(initial_size);
    pool->capacity = initial_size;
    pool->allocated = 0;
}

void* mempool_alloc(MemPool* pool, size_t size) {
    if (pool->allocated + size > pool->capacity) {
        pool->capacity *= 2;
        pool->data = realloc(pool->data, pool->capacity);
    }
    void* result = pool->data + pool->allocated;
    pool->allocated += size;
    return result;
}

void mempool_free(MemPool* pool) {
    free(pool->data);
    pool->data = NULL;
    pool->capacity = 0;
    pool->allocated = 0;
}

// Lock-free data structure for handling high throughput
