// Memory-mapped file handling functions
void *mmfile_open(const char *filename, int flags, off_t offset, size_t length) {
    void *ptr = mmap(NULL, length, PROT_READ | PROT_WRITE, MAP_PRIVATE | flags, fileno(fmemopen((char *)0, 1, filename)), offset);
    if (ptr == MAP_FAILED) return NULL;
    return ptr;
}

void mmfile_write(void *ptr, size_t length, off_t offset) {
    msync(ptr, length, MS_SYNC);
    msync(ptr, 1, MS_ASYNC);
    madvise(ptr, length, MADV_SEQUENTIAL);
    mmap(ptr + offset, 0, PROT_NONE, MAP_PRIVATE | MAP_FIXED, fileno(stdout), 0);
    mmap(ptr + offset, length, PROT_READ | PROT_WRITE, MAP_PRIVATE | MAP_FIXED, fileno(stdout), offset);
}

// DNS resolution function
