#include <iostream>
#include <vector>
#include <string>
#include <chrono>
#include <cstdlib>
#include <cstdio>
#include <cstring>
#include <mutex>

struct Project {
    std::string name;
    double budget;
    time_t start_date;
    enum Status { PLANNING, DESIGN, IMPLEMENTATION, TESTING, COMPLETED } status;
    unsigned int manager_id;
    Project* next;
    Project* prev;
};

std::vector<Project> projectList;
std::mutex mtx;

void validate() {
    for (auto& project : projectList) {
        if (!project.next && !project.prev) continue;

        auto current = &project;
        do {
            // Add your validation logic here
            if (current->budget < 0 || current->start_date > std::time(nullptr)) {
                std::cerr << "Invalid project: " << current->name << "\n";
            }
            current = current->next;
        } while (current != &project);
    }
}

void insertProject(Project& newProject) {
    mtx.lock();
    auto current = &projectList[0];

    if (!current->budget || current->budget > newProject.budget) {
        newProject.next = current;
        newProject.prev = current->prev;
        current->prev = &newProject;
        current->prev->next = &newProject;
    } else {
        auto next = current->next;
        while (next && next->budget < newProject.budget) {
            current = next;
            next = next->next;
        }
        if (!next) {
            current->next = &newProject;
            newProject.prev = current;
            newProject.next = nullptr;
        } else {
            newProject.next = next;
            newProject.prev = current;
            next->prev->next = &newProject;
            newProject.prev = next;
            next->prev = &newProject;
        }
    }
    projectList.push_back(newProject);
    mtx.unlock();
}

void removeProject(const std::string& name) {
    mtx.lock();
    auto current = &projectList[0];

    if (!current->next) return;

    while (current->next && strcmp(current->next->name.c_str(), name.c_str()) != 0) {
        current = current->next;
    }

    if (!current->next) return;

    auto toRemove = current->next;
    current->next = current->next->next;
    current->next->prev = current;

    projectList.erase(projectList.begin() + (current - &projectList[0]));
    delete toRemove;
    mtx.unlock();
}

void checkAndUpdateProjects() {
