typedef struct {
    xmlDocPtr doc;
    xmlNode* root;
} xml_buffer;

xml_buffer* load_xml(const char* filename) {
    xml_buffer* buffer = (xml_buffer*)calloc(1, sizeof(xml_buffer));
    if (!buffer) return NULL;

    xmlParseOperatorsPtr old_ops = xmlGetCurrentOperators();
    xmlInitParser();
    xmlSetUserData(buffer);

    xmlDoc* doc = xmlReadFile(filename, NULL, 0);
    if (doc == NULL) {
        fprintf(stderr, "Failed to parse XML file: %s\n", xmlErrorString(xmlGetLastError()));
        free(buffer);
        return NULL;
    }

    buffer->doc = doc;
    buffer->root = xmlDocGetRootElement(doc);
    xmlSetCurrentOperators(old_ops);

    return buffer;
}

// Implement a function to extract elements by name from the XML document
xmlNode* find_element(xmlNode* node, const char* name) {
    for (xmlNode* cur = node->children; cur != NULL; cur = cur->next) {
        if (cur->type == XML_ELEMENT_NODE && xmlStrcmp(cur->name, (const xmlChar*)name) == 0) {
            return cur;
        }
    }

    return NULL;
}
