        record.offset = 0; // You can initialize offset as needed
    }
    return records;
}

std::vector<Record> deserializeByteArray(const char* byteArray, size_t length) {
    std::istringstream iss(byteArray, std::ios::binary);
    boost::archive::binary_iarchive ia(iss);
    std::vector<Record> records;
    ia >> BOOST_SERIALIZATION_NVP(records);
    return records;
}

