#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <locale.h>
#include <stdio_ext.h> // For RAND_MAX

typedef struct {
    long offset;
    int key;
    char description[100];
} profile;

int manageResourceBundleAndUpdateUserProfile(const char *filename, int *numItems) {
    FILE *file = fopen(filename, "r");
    if (!file) {
        perror("Error opening file");
        return -1;
    }

    setlocale(LC_ALL, ""); // For gettext functions
    bindtextdomain("myapp", "./locale");
    textdomain("myapp");

    char line[256];
    int lines = 0;
    while (fgets(line, sizeof(line), file)) {
        ++lines;
    }
    rewind(file);

    size_t longArraySize = 10000;
    size_t intKeyArraySize = 5000;
    size_t profileArraySize = longArraySize / 2;

    long *longArray = malloc(longArraySize * sizeof(long));
    if (!longArray) {
        perror("Error allocating memory for long array");
        fclose(file);
        return -1;
    }

    int *intKeyArray = malloc(intKeyArraySize * sizeof(int));
    if (!intKeyArray) {
        perror("Error allocating memory for int key array");
        free(longArray);
        fclose(file);
        return -1;
    }

    profile *profileArray = malloc(profileArraySize * sizeof(profile));
    if (!profileArray) {
        perror("Error allocating memory for profile array");
        free(longArray);
        free(intKeyArray);
        fclose(file);
        return -1;
    }

    int currentProfile = 0;
    while (lines > 0 && currentProfile < profileArraySize) {
        char *token = strtok(line, "\n");
        if (!token) break;

        long offset = atol(token);
        longArray[currentProfile] = offset;

        token = strtok(NULL, " ");
        if (!token) break;

        int key = atoi(token);
        intKeyArray[currentProfile] = key;

        snprintf(profileArray[currentProfile].description, sizeof(profileArray[currentProfile].description), _("Generated description"));
        profileArray[currentProfile].key = key;
        profileArray[currentProfile].offset = offset;

        --lines;
        ++currentProfile;
    }

    *numItems = lines;
    fclose(file);

    return 0;
}
