class MemoryPool {
public:
    virtual ~MemoryPool() {}
    virtual void* allocate(size_t size) = 0;
    virtual void deallocate(void* ptr, size_t size) = 0;
};

class FloatMemoryPool : public MemoryPool {
private:
    boost::circular_buffer<float> buffer_;
public:
    FloatMemoryPool(size_t capacity) : buffer_(capacity) {}
    void* allocate(size_t size) override {
        if (buffer_.empty()) return nullptr;
        auto it = buffer_.begin();
        auto result = it;
        std::advance(it, size);
        buffer_.erase(it, buffer_.end());
        return &*result;
    }
    void deallocate(void* ptr, size_t size) override {
        boost::circular_buffer<float>::value_type* data = static_cast<boost::circular_buffer<float>::value_type*>(ptr);
        buffer_.push_back(*data);
    }
};

class IntMemoryPool : public MemoryPool {
private:
    boost::circular_buffer<int> buffer_;
public:
    IntMemoryPool(size_t capacity) : buffer_(capacity) {}
    void* allocate(size_t size) override {
        if (buffer_.empty()) return nullptr;
        auto it = buffer_.begin();
        auto result = it;
        std::advance(it, size);
        buffer_.erase(it, buffer_.end());
        return &*result;
    }
    void deallocate(void* ptr, size_t size) override {
        boost::circular_buffer<int>::value_type* data = static_cast<boost::circular_buffer<int>::value_type*>(ptr);
        buffer_.push_back(*data);
    }
