#include <iostream>
#include <string>
#include <vector>

struct Node {
    int data;
    Node* left;
    Node* right;
};

class BinaryTree {
public:
    void create(int size) {
        root = new Node[size];
        for (int i = 0; i < size; ++i) {
            root[i].left = nullptr;
            root[i].right = nullptr;
        }
        buildTree(root, 0, size - 1);
    }

    void buildTree(Node* node, int start, int end) {
        if (start > end) return;

        int mid = (start + end) / 2;
        node[mid].data = mid;

        buildTree(node, start, mid - 1);
        buildTree(node, mid + 1, end);
    }

    void traverseInOrder(Node* node) {
        if (node == nullptr) return;

        traverseInOrder(node->left);
        std::cout << node->data << " ";
        traverseInOrder(node->right);
    }

    void traversePreOrder(Node* node) {
        if (node == nullptr) return;

        std::cout << node->data << " ";
        traversePreOrder(node->left);
        traversePreOrder(node->right);
    }

    void traversePostOrder(Node* node) {
        if (node == nullptr) return;

        traversePostOrder(node->left);
        traversePostOrder(node->right);
        std::cout << node->data << " ";
    }

private:
    Node* root;
};

std::vector<std::string> filenames;
void addFilename(const std::string& filename) {
    bool unique = true;
    for (const auto& existing : filenames) {
        if (filename == existing) {
            unique = false;
            break;
        }
    }
    if (unique) filenames.push_back(filename);
}
