};

class SimpleMemoryPool : public MemoryPool {
private:
    std::vector<std::unique_ptr<Record>> pool;
    std::mutex mtx;

public:
    SimpleMemoryPool(size_t initialSize) {
        for (size_t i = 0; i < initialSize; ++i) {
            pool.emplace_back(new Record{});
        }
    }

    Record* allocate() override {
        std::lock_guard<std::mutex> lock(mtx);
        if (!pool.empty()) {
            auto result = pool.back().release();
            pool.pop_back();
            return result;
        }
        return nullptr;
    }

    void deallocate(Record* record) override {
        std::lock_guard<std::mutex> lock(mtx);
        if (record) {
            pool.emplace_back(new Record{*record});
        }
    }
};

