}

Node* create_node(const Record* record) {
    Node* node = malloc(sizeof(Node));
    if (!node) {
        fprintf(stderr, "Failed to allocate memory for node\n");
        exit(EXIT_FAILURE);
    }
    memcpy(&node->data, record, sizeof(Record));
    node->next = NULL;
    return node;
}

unsigned int hash(const char* key, unsigned int size) {
    unsigned long hash = 5381;
    for (int i = 0; key[i]; ++i)
        hash = ((hash << 5) + hash) + key[i]; /* hash * 33 + c */
    return hash % size;
}

void insert(HashTable* table, const Record* record) {
    pthread_mutex_lock(&table->lock);
    Node** node_ptr = &table->table[hash(record->str, table->size)];
    while (*node_ptr)
        node_ptr = &(*node_ptr)->next;
    *node_ptr = create_node(record);
    pthread_mutex_unlock(&table->lock);
}

Record* find(HashTable* table, const char* key) {
    pthread_mutex_lock(&table->lock);
    Node** node_ptr = &table->table[hash(key, table->size)];
    for (; *node_ptr; node_ptr = &(*node_ptr)->next) {
        if (strcmp((*node_ptr)->data.str, key) == 0) {
            pthread_mutex_unlock(&table->lock);
            return &(*node_ptr)->data;
        }
    }
    pthread_mutex_unlock(&table->lock);
    return NULL;
}

void delete(HashTable* table, const char* key) {
    pthread_mutex_lock(&table->lock);
    Node** prev_ptr = &table->table[hash(key, table->size)];
    Node** node_ptr = prev_ptr;
    for (; *node_ptr && strcmp((*node_ptr)->data.str, key) != 0; node_ptr = &(*node_ptr)->next);
    if (*node_ptr) {
        *prev_ptr = (*node_ptr)->next;
        free(*node_ptr);
    }
    pthread_mutex_unlock(&table->lock);
}
```

