#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <time.h>

typedef struct {
    time_t timestamp;
    unsigned int id;
    bool status;
} sensor_data;

struct memory_block {
    void* data;
    size_t size;
    struct memory_block* next;
};

struct memory_pool {
    struct memory_block* head;
    struct memory_block* tail;
    size_t capacity;
    pthread_mutex_t lock;
};

struct measurement {
    float value;
    sensor_data* data;
};

void init_memory_pool(struct memory_pool* pool, size_t capacity) {
    pool->head = NULL;
    pool->tail = NULL;
    pool->capacity = capacity;
    pthread_mutex_init(&pool->lock, NULL);
}

void* allocate(struct memory_pool* pool, size_t size) {
    pthread_mutex_lock(&pool->lock);
    struct memory_block* block = pool->head;
    if (block != NULL && block->size >= size) {
        pool->head = block->next;
        if (pool->head == NULL) pool->tail = NULL;
        block->size -= size;
        block->data += size;
        pthread_mutex_unlock(&pool->lock);
        return block->data;
    }
    pthread_mutex_unlock(&pool->lock);
    return malloc(size);
}

void free_memory(struct memory_pool* pool, void* ptr, size_t size) {
    if (pool->capacity > 0) {
        pthread_mutex_lock(&pool->lock);
        struct memory_block* block = (struct memory_block*)malloc(sizeof(struct memory_block));
        block->data = ptr;
        block->size = size;
        block->next = NULL;
        if (pool->tail != NULL) pool->tail->next = block;
        else pool->head = block;
        pool->tail = block;
        pool->capacity--;
        pthread_mutex_unlock(&pool->lock);
    } else {
        free(ptr);
    }
}

void* create_measurement(struct memory_pool* measurements, struct memory_pool* sensor_data, time_t seed) {
    void* measurement = allocate(measurements, sizeof(struct measurement));
    if (measurement == NULL) return NULL;
    sensor_data->data = allocate(sensor_data, sizeof(sensor_data));
    if (sensor_data->data == NULL) {
        free_memory(measurements, measurement, sizeof(struct measurement));
        return NULL;
    }
    ((struct measurement*)measurement)->value = rand() % 100;
    ((struct sensor_data*)sensor_data->data)->timestamp = time(NULL) + seed;
    ((struct sensor_data*)sensor_data->data)->id = rand();
    ((struct sensor_data*)sensor_data->data)->status = rand() % 2 == 0;
    return measurement;
}

void destroy_measurement(struct memory_pool* measurements, struct measurement* measurement) {
    free_memory(measurements, measurement, sizeof(struct measurement));
    free_memory(measurements->sensor_data, measurement->data, sizeof(sensor_data));
}
