void init_memory_pool(struct memory_pool* pool, size_t initial_size) {
    pool->data = malloc(initial_size);
    if (!pool->data) {
        fprintf(stderr, "Failed to allocate memory\n");
        exit(EXIT_FAILURE);
    }
    pool->capacity = initial_size;
    pool->allocated = 0;
}

void* custom_malloc(struct memory_pool* pool, size_t size) {
    if (pool->allocated + size > pool->capacity) {
        fprintf(stderr, "Memory allocation exceeded capacity\n");
        return NULL;
    }
    void* result = pool->data + pool->allocated;
    pool->allocated += size;
    return result;
}

void custom_free(struct memory_pool* pool, void* ptr) {
    if (!ptr || !pool->data) return;
    pool->allocated -= (size_t)(ptr - pool->data);
}

