1. **Lexer and Parser**: Create lexer and parser modules to interpret directives from the configuration file. You can use `combine` crate for combining multiple parsing combinators.

```rust
use combine::parser::{char, keyword, many_till, opt, parse};

pub fn lex(input: &str) -> impl Iterator<Item = Token> {
    let mut tokens = Vec::new();
    let mut current_line = String::new();
    let mut line_number = 1;

    let mut parser = many_till(
        chain(opt(space), keyword("operation")).then(space).then(operation),
        chain(opt(space), eof()).then(move || Token::Eof),
    );

    for token in parser.parse(input).into_iter() {
        current_line.clear();
        current_line.push_str(&token.value);
        tokens.push(Token { line: line_number, value: token.value });
        line_number += 1;
    }

    tokens.into_iter()
}
```

2. **Operation Parser**: Define a parser for specific operations and their associated parameters.

```rust
pub struct Token {
    pub line: usize,
    pub value: String,
}

fn operation(input: &str) -> impl FnOnce() -> Result<Operation, ParseError<String>> {
    move || parse(chain(opt(space), keyword("add")).then(space).then(number), input)
        .map_err(|e| e.into())
        .and_then(|(_, add)| {
            Ok(Operation::Add {
                a: add as u64,
                b: 0,
                result: Box::new(move || {}),
            })
        })
}
