[' I'm providing you with a basic structure for the C function, using a custom memory pool for efficient memory management and a simple data integrity check. For thread safety, I'll use pthreads and mutexes. However, please note that this is a simplified version and may require further optimization and error handling for production use.

```c
#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <sys/mman.h>

typedef struct WeatherRecord {
    long offset;
    int key;
    double temperature_fahrenheit;
    int humidity;
    float temperature_celsius;
} WeatherRecord;

typedef struct MemoryBlock {
    size_t size;
    struct MemoryBlock* next;
    void* data;
    pthread_mutex_t lock;
} MemoryBlock;

MemoryBlock* memory_pool = NULL;
pthread_mutex_t pool_lock = PTHREAD_MUTEX_INITIALIZER;

void* mem_alloc(size_t size) {
    pthread_mutex_lock(&pool_lock);

    MemoryBlock* current = memory_pool;
    while (current != NULL && current->size < size) {
        current = current->next;
    }

    if (current == NULL || current->size >= size) {
        void* new_data = mmap(NULL, size, PROT_READ | PROT_WRITE, MAP_PRIVATE | MAP_ANONYMOUS, -1, 0);
        if (new_data == MAP_FAILED) {
            perror("mmap failed");
            pthread_mutex_unlock(&pool_lock);
            return NULL;
        }

        MemoryBlock* new_block = (MemoryBlock*) malloc(sizeof(MemoryBlock));
        if (new_block == NULL) {
            munmap(new_data, size);
            perror("malloc failed");
            pthread_mutex_unlock(&pool_lock);
            return NULL;
        }

        new_block->size = size;
        new_block->next = memory_pool;
        new_block->data = new_data;
        new_block->lock = PTHREAD_MUTEX_INITIALIZER;
        memory_pool = new_block;
    }

    void* data = current->data;
    size_t remaining_size = current->size - size;
    if (remaining_size > 0) {
        current->size = remaining_size;
        current->next = (MemoryBlock*) ((char*)current->next + size);
    } else {
        MemoryBlock* next_block = current->next;
        current->size = 0;
        current->next = NULL;
        free(next_block);
    }

    pthread_mutex_unlock(&pool_lock);
    return data;
}

void mem_free(void* ptr) {
    pthread_mutex_lock(&pool_size_lock);

    MemoryBlock* current = memory_pool;
    while (current != NULL && current->next != NULL) {
        if (current->data == ptr) {
            void* next_data = current->next->data;
            size_t size = current->size + ((MemoryBlock*)next_data)->size;
            free(current);
            current = (MemoryBlock*)next_data;
            current->size = size;
            current->next = memory_pool;
            memory_pool = current;
            break;
        }
        current = current->next;
    }

    pthread_mutex_unlock(&pool_lock);
}

WeatherRecord* create_weather_record(void* data) {
    WeatherRecord* record = (WeatherRecord*)data;
    pthread_mutex_init(&record->lock, NULL);
    return record;
}

void verify_integrity(const WeatherRecord* record) {
    // Implement your data integrity check here
}

// Implement a thread-safe function to access and modify the weather records
```

