3. Custom memory pool:

```c
struct memory_pool {
    size_t capacity;
    void* buffer;
    size_t free_index;
};

void init_memory_pool(struct memory_pool* pool, size_t capacity) {
    pool->capacity = capacity;
    pool->buffer = custom_malloc(capacity * sizeof(Vector));
    if (!pool->buffer) {
        fprintf(stderr, "Memory allocation failed\n");
    }
    pool->free_index = 0;
}

Vector* alloc_from_pool(struct memory_pool* pool) {
    if (pool->free_index < pool->capacity) {
        return (Vector*)((char*)pool->buffer + pool->free_index * sizeof(Vector));
    }
    return NULL;
}

void free_to_pool(struct memory_pool* pool, Vector* vector) {
    if (pool->free_index < pool->capacity) {
        memmove((char*)pool->buffer + pool->free_index * sizeof(Vector), vector, sizeof(Vector));
        pool->free_index++;
    }
}
```

4. Dynamic array function:

```c
struct dynamic_array* create_dynamic_array(size_t capacity) {
    struct dynamic_array* da = (struct dynamic_array*)custom_malloc(sizeof(struct dynamic_array));
    if (!da) {
        fprintf(stderr, "Memory allocation failed\n");
        return NULL;
    }

    pthread_mutex_init(&da->lock, NULL);
    da->capacity = capacity;
    da->size = 0;
    da->data = (Vector*)alloc_from_pool((struct memory_pool){.capacity = capacity});

    return da;
}

void destroy_dynamic_array(struct dynamic_array* da) {
    if (da->data) {
        free_to_pool((struct memory_pool){.buffer = da->data}, NULL);
    }
    pthread_mutex_destroy(&da->lock);
    custom_free(da);
}

void resize_if_needed(struct dynamic_array* da) {
    if (da->size == da->capacity) {
        da->capacity *= 2;
        da->data = (Vector*)realloc(da->data, sizeof(Vector) * da->capacity);
        if (!da->data) {
            fprintf(stderr, "Memory allocation failed\n");
            da->capacity = 1024; // Predefined threshold
        }
    }
}
```

