} Record;

Record* create_record_array(int size) {
    Record *records = malloc(sizeof(Record) * size);
    if (!records) {
        fprintf(stderr, "Memory allocation failure\n");
        exit(EXIT_FAILURE);
    }

    for (int i = 0; i < size; ++i) {
        records[i].key = -1 + rand() % (2 * KEY_ARRAY_SIZE);
        records[i].value = -10000 + rand() % (2 * KEY_ARRAY_SIZE);
        records[i].offset = -1;
    }

    return records;
}

void resize_record_array(Record **records, int *size, int new_size) {
    Record *new_records = realloc(*records, sizeof(Record) * new_size);
    if (!new_records) {
