// Function to handle extra samples
void handleExtraSamples(TIFF* tif, std::vector<uint16_t>& extraSamples) {
    // Iterate through TIFF tags until you find TIFFTAG_SAMPLEFORMAT
    while (true) {
        uint32_t tag = TIFFGetField(tif, TIFFDIR_ORIENTATION);
        if (!tag) break;

        if (tag == TIFFTAG_SAMPLEFORMAT) {
            extraSamples.push_back(TIFFGetField(tif, tag));
        } else {
            // Skip other tags and continue iterating
        }
    }
}

// Function to handle compression types
uint32_t getCompressionType(TIFF* tif) {
    uint32_t compression = TIFFGetField(tif, TIFFTAG_COMPRESSION);
    switch (compression) {
        case COMPRESSION_NONE:
            return COMPRESSION_NONE;
        case COMPRESSION_CCITTFAX3:
        case COMPRESSION_CCITTFAX4:
            return COMPRESSION_CCITT;
        case COMPRESSION_LZW:
            return COMPRESSION_LZW;
        case COMPRESSION_JPEG:
            return COMPRESSION_JPEG;
        default:
            // Handle unsupported compression types here
    }
}
```

5. Use memory-mapped I/O to minimize direct memory usage and reduce swapping:

```cpp
#include <sys/mman.h>

// Function to map the TIFF file into memory
void* mapFile(const char* filename, size_t& length) {
    int fd = open(filename, O_RDONLY);
    if (fd == -1) {
        std::cerr << "Error opening file: " << filename << std::endl;
        return nullptr;
    }

    struct stat st;
    fstat(fd, &st);
    void* mapped = mmap(nullptr, st.st_size, PROT_READ, MAP_PRIVATE, fd, 0);
    close(fd);
    length = st.st_size;
    return mapped;
}
