#include <cstring>

struct Record {
    int id;
    std::string str;
};

class MemoryManager {
public:
    MemoryManager() : offsets_(new std::vector<long>()), keys_(new std::vector<int>()), records_(new std::vector<Record>()) {}

    ~MemoryManager() {
        delete offsets_;
        delete keys_;
        delete records_;
    }

    void resizeOffsets(size_t size) {
        mutex_.lock();
        if (offsets_->size() < size) {
            offsets_->resize(size, 0);
        }
        mutex_.unlock();
    }

    void setKey(size_t index, int key) {
        mutex_.lock();
        if (index >= keys_->max_size()) {
            std::cerr << "Error: Key index exceeds the maximum allowed size." << std::endl;
            mutex_.unlock();
            return;
        }
        keys_->at(index) = key;
        mutex_.unlock();
    }

    void allocateRecord(size_t index, int min, int max, const char* str) {
        mutex_.lock();
        if (index >= records_->size()) {
            records_->resize(index + 1);
        }
        Record& record = records_->at(index);
        record.id = rand() % (max - min + 1) + min;
        record.str.assign(str, 0, std::min(strlen(str), static_cast<unsigned>(MAX_LENGTH)));
        mutex_.unlock();
    }

    void deallocateRecord(size_t index) {
        mutex_.lock();
        if (index >= records_->size()) {
            std::cerr << "Error: Index exceeds the size of the Records vector." << std::endl;
            mutex_.unlock();
            return;
        }
        records_->at(index).str.clear();
        mutex_.unlock();
    }

    void logAllocation(const char* type, size_t size) {
        // Implement logging here using an external system
        std::cout << "Allocated " << type << " of size " << size << std::endl;
    }

    void logDeallocation(const char* type, size_t size) {
        // Implement logging here using an external system
        std::cout << "Deallocated " << type << " of size " << size << std::endl;
    }

    void sharedMemoryInit() {
        key_ = ftok("shm", 'M');
        shmid_ = shmget(key_, sizeof(void*), 0666 | IPC_CREAT);
        data_ = static_cast<char*>(shmat(shmid_, nullptr, 0));
    }

    void sharedMemoryCleanup() {
        shmdt(data_);
        shmctl(shmid_, IPC_RMID, nullptr);
    }

private:
    std::vector<long>* offsets_;
    std::vector<int>* keys_;
    std::vector<Record>* records_;
    mutex mutex_;
    int key_;
    int shmid_;
    char* data_;
};
```

