#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <sys/wait.h>
#include <time.h>

typedef struct {
    long offset;
    int key;
    char description[100];
} profile;

int load_resource(const char *filename, profile ***profiles, size_t *num_profiles) {
    FILE *file = fopen(filename, "r");
    if (!file) {
        perror("Error opening file");
        return 0;
    }

    long offsets[10000] = {0};
    int keys[5000] = {0};
    profile *profiles_array = NULL;
    size_t max_profiles = 0;
    size_t current_profiles = 0;

    while (1) {
        profile new_profile;
        if (fscanf(file, "%ld %d %s", &new_profile.offset, &new_profile.key, new_profile.description) != 3)
            break;

        if (current_profiles >= max_profiles) {
            max_profiles *= 2;
            profiles_array = realloc(profiles_array, sizeof(profile *) * max_profiles);
            if (!profiles_array) {
                perror("Error allocating memory");
                goto cleanup;
            }
        }

        profiles_array[current_profiles] = malloc(sizeof(profile));
        if (!profiles_array[current_profiles]) {
            perror("Error allocating memory");
            goto cleanup;
        }

        profiles_array[current_profiles++]->offset = new_profile.offset;
        profiles_array[current_profiles - 1]->key = new_profile.key;
        strcpy(profiles_array[current_profiles - 1]->description, new_profile.description);
    }

    *num_profiles = current_profiles;
    *profiles = profiles_array;

    return 1;

cleanup:
    for (size_t i = 0; i < current_profiles; ++i) {
        free(profiles_array[i]);
    }
    free(profiles_array);
    fclose(file);
    return 0;
}

int execute_command_in_background(const char *command) {
    pid_t child = fork();

    if (child == -1) {
        perror("Error forking");
        return 0;
    } else if (child > 0) {
        // Parent process
        return 1;
    } else {
        // Child process
        if (execlp(command, command, NULL) == -1) {
            perror("Error executing command");
            _exit(EXIT_FAILURE);
        }
    }
}
