        (*nodes + i) = create_node(min_val + rand() % (max_val - min_val + 1));
    }
}

void init_hash_table(Node** nodes, size_t n, UT_hash_table* hash_table) {
    for (size_t i = 0; i < n; ++i) {
        Node* current_node = (*nodes + i);
        UT_HASH_ADD_PTR(hash_table, value, current_node);
    }
}

void init_indices(int* indices, size_t k, long min_val, long max_val) {
    for (size_t i = 0; i < k; ++i) {
        indices[i] = min_val + rand() % (max_val - min_val + 1);
    }
