void rotate_logs() {
    time_t now = time(NULL);
    struct tm *tm = localtime(&now);
    char timestamp[19];
    strftime(timestamp, sizeof(timestamp), "%Y%m%d", tm);

    DIR *dir = opendir("logs");
    if (!dir) return;

    struct dirent *entry;
    while ((entry = readdir(dir)) != NULL) {
        char filename[256];
        strcpy(filename, entry->d_name);
        if (strncmp(filename, "log_", 4) == 0 && strchr(filename, timestamp[0]) && strchr(filename, timestamp[1]) && strchr(filename, timestamp[2])) {
            char log_path[256];
            snprintf(log_path, sizeof(log_path), "logs/%s", filename);
            int log_fd = open(log_path, O_RDONLY);
            if (log_fd == -1) continue;

            struct stat st;
            fstat(log_fd, &st);
            off_t size = st.st_size;
            char *buffer = malloc(size + 1);
            read(log_fd, buffer, size);
            buffer[size] = '\0';

            int new_log_fd = open("logs/log_" + timestamp + "_backup.log", O_WRONLY | O_CREAT | O_APPEND, S_IRUSR | S_IWUSR | S_IRGRP | S_IROTH);
            if (new_log_fd == -1) {
                free(buffer);
                continue;
            }

            dprintf(new_log_fd, "%s", buffer);
            close(new_log_fd);

            char backup_path[256];
            snprintf(backup_path, sizeof(backup_path), "logs/%s.bak", filename);
            rename(log_path, backup_path);
            free(buffer);
        }
    }
    closedir(dir);
}
```

Call `rotate_logs()` periodically to rotate logs and keep only the last seven logs per day.']

