pid_t fork_exec(const char* command, char** output) {
    pid_t pid = fork();
    if (pid == -1) return -1; // Fork failed

    if (pid > 0) { // Parent process
        int status;
        waitpid(pid, &status, 0);
        close(pid);
        *output = calloc(sizeof(char), strlen(stdout));
        read(pid, *output, strlen(stdout));
