    virtual void deallocate(Record* record) = 0;
};

class LoggingCustomMemoryPool : public CustomMemoryPool {
private:
    std::atomic<int> allocation_failures{0};

public:
    LoggingCustomMemoryPool() {
        // Initialize logging mechanism here
    }

    Record* allocate() override {
        void* memory = mmap(NULL, sizeof(Record), PROT_READ | PROT_WRITE, MAP_PRIVATE | MAP_ANONYMOUS, -1, 0);
        if (memory == MAP_FAILED) {
            ++allocation_failures;
            // Log allocation failure here
            return nullptr;
        }
        return new (static_cast<Record*>(memory)) Record();
    }

    void deallocate(Record* record) override {
        munmap(static_cast<void*>(record), sizeof(Record));
    }
};

