            fprintf(stderr, "Failed to allocate memory for file path.\n");
            exit(EXIT_FAILURE);
        }

        new_node->next = *head;
        *head = new_node;
    }

    closedir(dp);
}

void manage_memory(Node **head) {
    Node *current = *head;
    while (current != NULL) {
        Node *temp = current;
        current = current->next;
        free(temp->path);
        free(temp);
    }
    *head = NULL;
}

