DGPFGraph* create_graph(int num_vertices, int num_edges, size_t vertex_size, size_t edge_size) {
    DGPFGraph* graph = dgpf_create();

    // Allocate memory pools for vertices and edges
    void* vertex_pool = create_memory_pool(vertex_size * num_vertices);
    void* edge_pool = create_memory_pool(edge_size * num_edges);

    // Initialize offset arrays for both vertex and edge structures
    int* vertex_offsets = malloc((num_vertices + 1) * sizeof(int));
    int* edge_offsets = malloc((num_edges + 1) * sizeof(int));

    // Set initial offsets to zero
    vertex_offsets[0] = 0;
    edge_offsets[0] = 0;

    pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;

    // Function to add a vertex or an edge, ensuring thread-safety
    void add_vertex_or_edge(struct event* event) {
        pthread_mutex_lock(&lock);

        switch (event->type) {
            case ADD_VERTEX:
                memcpy((void*)(vertex_pool + vertex_offsets[num_vertices]), &event->v, vertex_size);
                vertex_offsets[num_vertices + 1] = vertex_offsets[num_vertices];
                num_vertices++;
                break;
            case ADD_EDGE:
                int src = event->e.src;
                int dest = event->e.dest;

                if (vertex_offsets[src] >= vertex_offsets[dest]) {
                    log_warning("Vertex with id %d has a larger offset than vertex with id %d", src, dest);
                }

                memcpy((void*)(edge_pool + edge_offsets[num_edges]), &event->e, edge_size);
                edge_offsets[num_edges + 1] = edge_offsets[num_edges];
                num_edges++;
                break;
        }

        pthread_mutex_unlock(&lock);
    }

    // Add configurable number of vertices and edges to the graph
    for (int i = 0; i < num_vertices; ++i) {
        struct vertex v = { .id = i, .data = i * i, .timestamp = time(NULL) };
        struct event e = { .type = ADD_VERTEX, .v = v };
        add_vertex_or_edge(&e);
    }

    for (int i = 0; i < num_edges; ++i) {
        int src = rand() % num_vertices;
        int dest = rand() % num_vertices;
        struct edge e = { .src = src, .dest = dest, .weight = src + dest, .timestamp = time(NULL) };
        struct event e = { .type = ADD_EDGE, .e = e };
        add_vertex_or_edge(&e);
    }

    // Implement serialization and deserialization functions, logging, resource checks, and other necessary features

    return graph;
}
