#include <cstring>

struct NFAPI_CRC_INDICATION_PDU_T {
    uint32_t RX_UE_INFORMATION_TAG;
    uint16_t RNTI;
    bool CRCFLAG;
};

struct record {
    long offset;
    int key;
    std::unique_ptr<char[]> label;
    std::vector<NFAPI_CRC_INDICATION_PDU_T> indications;
    std::mutex mtx;
};

std::map<int, std::unique_ptr<record>> records;
std::mutex records_mtx;

void allocateRecord(int key, const char* label) {
    std::lock_guard<std::mutex> lock(records_mtx);
    auto it = records.find(key);
    if (it != records.end()) return;

    auto new_record = std::make_unique<record>();
    new_record->key = key;
    new_record->label.reset(new char[strlen(label) + 1]);
    strcpy(new_record->label.get(), label);
    records[key] = std::move(new_record);
}

void addIndication(int key, const NFAPI_CRC_INDICATION_PDU_T& indication) {
    std::lock_guard<std::mutex> lock(records_mutext);
    auto it = records.find(key);
    if (it == records.end()) return;

    it->second->indications.push_back(indication);
}

record* getRecord(int key) {
    std::lock_guard<std::mutex> lock(records_mtx);
    auto it = records.find(key);
    if (it == records.end()) return nullptr;
    return it->second.get();
}
```

