void generate_filename(char* original_filename, char* new_filename, size_t max_records) {
    // Extract prefix and count vowels
    char prefix[4];
    int vowel_count = 0;
    for (int i = 0; i < 3 && original_filename[i] != '\0'; ++i) {
        if (isalpha(original_filename[i]) && islower(original_filename[i])) {
            prefix[i] = tolower(original_filename[i]);
        } else if (i < 3) {
            break;
        }
        if (strchr("aeiou", prefix[i])) {
            ++vowel_count;
        }
    }

    // Generate extension
    char extension[9] = ".ABCDEFG";
    for (int i = 3 + vowel_count; i < 8; ++i) {
        extension[i] = 'A' + rand() % 26;
    }

    // Handle special characters and concatenate
    size_t filename_length = strlen(original_filename);
    char* combined_filename = malloc(filename_length + 8 + 1);
    strcpy(combined_filename, original_filename);
    for (int i = filename_length - 1; i >= 0 && i < filename_length - 7; --i) {
        if (!isalnum(original_filename[i]) && original_filename[i] != '.') {
            combined_filename[i + 8] = original_filename[i];
            combined_filename[filename_length + 8] = '\0';
            break;
        }
    }
    strcat(combined_filename, extension);

    // Copy new filename to the provided buffer
    strncpy(new_filename, combined_filename, 100);
    new_filename[99] = '\0';
