std::bitset<31> generate_key(int replacement) {
    std::bitset<31> key;
    for (int i = 1001; i < 2001; ++i) {
        if (isPrime(i) && countOnes(key = bitset<31>(std::to_string(i))) % 2 == 1) {
            key[30] = replacement; // Set the last bit to the replacement value
            return key;
        }
    }
    throw std::runtime_error("No suitable prime key found within given range.");
}

bool isPrime(int num) {
    if (num <= 1) return false;
    if (num == 2) return true;
    if (num % 2 == 0) return false;

    for (int i = 3; i * i <= num; i += 2) {
        if (num % i == 0) return false;
    }

    return true;
}

int countOnes(const std::bitset<31>& bs) {
    int count = 0;
    for (char c : bs.to_string()) {
        if (c == '1') ++count;
    }
    return count;
}

void log_error(const std::runtime_error& err, const std::chrono::system_clock::time_point& start) {
