    std::cerr << "Error: " << err.what() << ", Time taken: " << elapsed << " seconds." << std::endl;
}

pid_t fork_and_execute(const std::function<void()>& func) {
    pid_t child = fork();
    if (child < 0) {
        throw std::runtime_error("Fork failed.");
    } else if (child == 0) {
        func();
        exit(0);
    }
    return child;
}

