        for (const auto& i : input) {
            if (i <= 0 || (i % 2 == 0 && i != 2)) throw std::runtime_error("Invalid input integer.");

            pid_t child = fork_and_execute([&]() {
                try {
                    auto key = generate_key(replacement);
                    // Execute additional tasks with the generated key, if needed
                    // ...
                } catch (const std::runtime_error& err) {
                    log_error(err, start);
