```cpp
#include <iostream>
#include <vector>
#include <string>
#include <cstdlib>
#include <ctime>
#include <mutex>
#include <thread>

struct Record {
    long offset;
    int key;
    time_t timestamp;
    char status;
    std::string str;
};

void initRecord(Record& record) {
    record.offset = 0;
    record.key = rand() % 100 + 1; // Random integer within range 1-100
    record.timestamp = time(nullptr);
    record.status = 'A';
}

void generateString(Record& record) {
    std::string tempStr;
    for (int i = 0; i < rand() % 20 + 5; ++i) {
        tempStr += 'a' + rand() % 26;
    }
    record.str.swap(tempStr);
}

std::vector<Record> createRecords(int size, int maxSize) {
    std::vector<Record> records;
    std::mutex mtx;

    const int threadCount = std::min(maxSize / 100, 10); // Adjust thread count based on size

    std::vector<std::thread> threads;
    for (int i = 0; i < threadCount; ++i) {
        threads.emplace_back([&]() mutable {
            for (int j = i * size / threadCount; j < (i + 1) * size / threadCount; ++j) {
                Record record;
                initRecord(record);
                generateString(record);
                std::unique_lock<std::mutex> lock(mtx);
                records.emplace_back(record);
                lock.unlock();
            }
        });
    }

    for (auto& thread : threads) {
        thread.join();
    }

    return records;
}

void pauseResume(std::vector<Record>& records, bool pause) {
    std::unique_lock<std::mutex> lock(mtx);
    if (pause) {
        // Implement pause functionality here
    } else {
        // Implement resume functionality here
    }
}
