```javascript
const { PassThrough, Transform } = require('stream');
const fs = require('fs');

class DataCollector extends Transform {
  constructor({ maxBufferSize }) {
    super();
    this._maxBufferSize = maxBufferSize;
    this._buffer = [];
    this._isPaused = false;
    this._pageSize = 100; // Default page size
    this._currentPage = 1;
  }

  _transform(chunk, encoding, callback) {
    if (this._isPaused) return callback();

    this._buffer.push(chunk);

    if (Buffer.byteLength(this._buffer) > this._maxBufferSize) {
      this.flushToDisk().then(() => callback());
    } else {
      callback();
    }
  }

  collect(data) {
    this._buffer.push(data);
  }

  pause() {
    this._isPaused = true;
  }

  resume() {
    this._isPaused = false;
  }

  reset() {
    this._buffer = [];
    this._currentPage = 1;
  }

  async flushToDisk(maxFileSize) {
    if (!maxFileSize) maxFileSize = this._maxBufferSize;

    const file = await fs.promises.open('data.bin', 'w');
    await file.write(Buffer.concat(this._buffer));
    await file.close();
    this._buffer = [];
  }

  async getDataPage(pageSize) {
    if (!pageSize) pageSize = this._pageSize;
    this._pageSize = pageSize;

    const startIndex = (this._currentPage - 1) * pageSize;
    const endIndex = Math.min(startIndex + pageSize, this._buffer.length);

    const dataPage = this._buffer.slice(startIndex, endIndex);
    this._currentPage++;

    return Buffer.concat(dataPage);
  }
}

const collector = new DataCollector({ maxBufferSize: 10 * 1024 * 1024 }); // Set max buffer size to 10MB

// Integrate the collector into your system's data processing pipeline
collector.pipe(new PassThrough());
