```csharp
using System;
using System.Collections.Generic;
using System.Data;
using System.IO;
using System.Linq;
using System.Security.Cryptography;
using System.Text;
using System.Threading.Tasks;
using UnityEngine;

public class DynamicFileProcessor
{
    private readonly MD5 _md5;
    private readonly byte[] _buffer;
    private readonly List<byte[]> _memoryPool;
    private readonly int _maxMemoryUsage;
    private readonly Random _random;
    private readonly string _connectionString;

    public DynamicFileProcessor(int min, int max, int bufferSize = 4096, int maxMemoryUsageMB = 100, string connectionString = null)
    {
        _md5 = MD5.Create();
        _buffer = new byte[bufferSize];
        _memoryPool = new List<byte[]>();
        _maxMemoryUsage = maxMemoryUsageMB * 1024 * 1024;
        _random = new Random(unchecked((int)UnityEngine.Random.Range(min, max)));
        _connectionString = connectionString;
    }

    public int NextInt(int min, int max)
    {
        return _random.Next(min, max);
    }

    public async Task<string> CalculateMD5HashAsync(string filePath)
    {
        using (var fileStream = File.OpenRead(filePath))
        {
            var hash = _md5;
            var buffer = _memoryPool.FirstOrDefault();
            if (buffer == null || buffer.Length < _buffer.Length)
                buffer = new byte[_buffer.Length];

            _memoryPool.Remove(buffer);

            int read;
            while ((read = await fileStream.ReadAsync(_buffer, 0, _buffer.Length)) > 0)
            {
                Array.Copy(_buffer, 0, buffer, 0, read);
                hash.TransformBlock(buffer, 0, read, buffer, 0);
                _memoryPool.Add(buffer);
            }

            hash.TransformFinalBlock(Array.Empty<byte>(), 0, 0);

            var result = BitConverter.ToString(hash.Hash).Replace("-", string.Empty).ToLower();
            return result;
        }
    }

