                foreach (var parameter in parameters)
                    command.Parameters.AddWithValue($"@{command.Parameters.Count}", parameter);

                using (var reader = await command.ExecuteReaderAsync())
                {
                    // Process the result set here
                }
            }
        }
    }

    public override string ToString() => $"Random Range: [{_random.Next(int.MinValue), _random.Next(int.MaxValue)}]";
}
```

