class DataStore {
public:
    virtual Key* getKey(size_t id) = 0;
    virtual void releaseKey(Key* key) = 0;
};

struct Record {
    int value;
    std::unique_ptr<LongKey> offset;
    std::atomic<int> refCount{ 1 };

    ~Record() {
        if (--refCount == 0) {
            delete offset.release();
        }
    }
};

class RecordArray {
public:
    explicit RecordArray(size_t capacity) : records_(capacity), nextId_(0) {}

    Record* allocateRecord() {
        if (nextId_ >= records_.size()) {
            resize(records_.size() * 2);
        }
        auto& record = records_[nextId_++];
        new (&record) Record();
        return &records_[nextId_ - 1];
    }

    void resize(size_t newCapacity) {
        std::vector<Record> newRecords(newCapacity);
        std::copy_n(records_.begin(), nextId_, newRecords.begin());
        records_.swap(newRecords);
    }

    size_t getAllocatedCount() const { return nextId_; }
    size_t getTotalCapacity() const { return records_.size(); }

    Record* batchAllocate(size_t count) {
        if (nextId_ + count > records_.size()) {
            resize(records_.size() * 2);
        }
        auto start = &records_[nextId_];
        nextId_ += count;
        return start;
    }

    void initializeRecords(Record* records, size_t count, DataStore& dataStore, int minValue, int maxValue) {
        std::mutex mtx;
        std::default_random_engine generator;
        std::uniform_int_distribution<int> distribution(minValue, maxValue);

        auto initRecord = [&](Record* record, size_t id) {
            record->value = distribution(generator);
            if (id < records_.size()) {
                record->offset.reset(dataStore.getKey(id));
            }
        };

        std::vector<std::thread> threads;
        for (size_t i = 0; i < count; ++i) {
            threads.emplace_back([this, &records, initRecord, dataStore, i]() mutable {
                initRecord(&records[i], i);
            });
        }

        for (auto& thread : threads) {
            thread.join();
        }
    }

    void validateRecords(const Record* records, size_t count) const {
        // Implement validation logic here
    }
};
