using System;
using System.Collections.Generic;
using System.Data;
using System.Linq;
using System.Threading;
using System.Threading.Tasks;

public class DynamicDataManager
{
    private double _minValue;
    private double _maxValue;
    private readonly List<Action> _rangeChangeListeners;
    private readonly IDistributedDatabaseCluster _databaseCluster;
    private readonly ILoggingService _loggingService;
    private readonly ILoadBalancer _loadBalancer;
    private readonly Random _randomGenerator;

    public DynamicDataManager(IDistributedDatabaseCluster databaseCluster, ILoggingService loggingService, ILoadBalancer loadBalancer)
    {
        _databaseCluster = databaseCluster;
        _loggingService = loggingService;
        _loadBalancer = loadBalancer;
        _randomGenerator = new Random();
        _rangeChangeListeners = new List<Action>();
        _minValue = double.MinValue;
        _maxValue = double.MaxValue;
    }

    public void SetRange(double newMin, double newMax)
    {
        if (newMin >= _minValue || newMax <= _maxValue)
            throw new ArgumentException("New range must not intersect with the old one.");

        lock (_rangeChangeListeners)
        {
            _minValue = Math.Min(newMin, _minValue);
            _maxValue = Math.Max(newMax, _maxValue);
            foreach (var listener in _rangeChangeListeners)
                listener();
        }
    }

    public void AddRangeChangeListener(Action listener) => _rangeChangeListeners.Add(listener);

    public void RemoveRangeChangeListener(Action listener) => _rangeChangeListeners.Remove(listener);

    public byte[] SendByteArrayToServer(byte[] data) => _databaseCluster.SendByteArrayToServer(_loadBalancer.GetConnection(), data);

    public IDataReader GetQueryResults(string query) => _databaseCluster.ExecuteQuery(_loadBalancer.GetConnection(), query);

    public double GetRandomFloat() => _randomGenerator.NextDouble() * (_maxValue - _minValue) + _minValue;

    public int GetRandomInt() => (int)(_randomGenerator.NextDouble() * (_maxValue - _minValue)) + (int)_minValue;

    public override string ToString() => $"Current Range: [{_minValue}, {_maxValue})";
}
```

