  servicePaused = true;
  messageBus.send('Service paused');
}

function resumeService() {
  const delay = Math.floor(Math.random() * 4000) + 1000;
  setTimeout(() => {
    if (!servicePaused) return;
    startService();
    messageBus.send(`Resumed after ${delay}ms, ${buffer.length} data chunks remaining`);
