    public async Task ProcessBatchAsync(List<byte[]> ciphertexts, List<byte[]> tags, byte[] key, byte[] iv)
    {
        using (var memoryStream = new MemoryStream())
        {
            _aesGcm.Init(false, key, iv);

            var tasks = ciphertexts.Zip(tags, (c, t) => Task.Run(() => DecryptAndLog(memoryStream, c, t))).ToList();

            await Task.WhenAll(tasks);
        }
    }

    private void DecryptAndLog(MemoryStream stream, byte[] ciphertext, byte[] tag)
    {
        try
        {
            _aesGcm.Decrypt(ciphertext, tag, stream);
            stream.Position = 0;
            // Perform any necessary processing on the decrypted message here.

            _logger.LogInformation("Successfully decrypted message.");
        }
        catch (CryptographicException ex)
        {
            _logger.LogError(ex, "Failed to decrypt message: {Message}", Encoding.UTF8.GetString(ciphertext));
        }
        catch (Exception ex)
        {
            _logger.LogError(ex, "An error occurred while processing the message.");
        }
    }
}
```

This code defines an `AesGcmProcessor` class that processes a batch of encrypted messages using AES-GCM. The `ProcessBatchAsync` method accepts a list of ciphertexts, associated authentication tags, and shared encryption key as input parameters. It initializes the AES-GCM object, creates tasks for each ciphertext-tag pair, and decrypts them concurrently using the `DecryptAndLog` method.

The `DecryptAndLog` method handles both successful decryptions and errors by logging messages to an external logging service. It catches exceptions related to cryptographic operations and general errors separately for better error handling.']

[' Here's a C implementation of a dynamically growing collection (or "dynamic array") of entries containing a floating-point number and a file path string, using a custom allocator for better control over memory distribution:

```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <stdbool.h>
#include <regex.h>

typedef struct Entry {
    double number;
    char path[256];
    struct Entry *next;
} Entry;

typedef struct Collection {
    unsigned int capacity;
    unsigned int size;
    Entry **entries;
    Entry *head;
    Entry *tail;
    size_t memory_usage;
    size_t allocation_granularity;
    void* custom_allocator;
} Collection;

Collection* collection_create(size_t initial_capacity, size_t allocation_granularity, void* custom_allocator) {
    Collection *collection = malloc(sizeof(Collection));
    if (!collection) return NULL;

    collection->capacity = initial_capacity;
    collection->size = 0;
    collection->entries = calloc(initial_capacity, sizeof(Entry*));
    if (!collection->entries) {
        free(collection);
        return NULL;
    }

    collection->head = NULL;
    collection->tail = NULL;
    collection->memory_usage = 0;
    collection->allocation_granularity = allocation_granularity;
    collection->custom_allocator = custom_allocator;

    return collection;
}

Entry* create_entry(double number, const char *path) {
    Entry *entry = malloc(sizeof(Entry));
    if (!entry) return NULL;

    entry->number = number;
    strcpy(entry->path, path);
    entry->next = NULL;

    return entry;
}

bool is_valid_file_path(const char *path) {
    regex_t regex;
    regcomp(&regex, "/^[a-zA-Z]:\\/?[\\w/-.]+$/", REG_EXTENDED);
    int result = regexec(&regex, path, 0, NULL, 0);
    regfree(&regex);

    return result == 0;
}

void collection_insert(Collection *collection, Entry *entry) {
    if (!is_valid_file_path(entry->path)) return;

    if (collection->size == collection->capacity) {
        collection->capacity += collection->allocation_granularity;
        collection->entries = realloc(collection->entries, sizeof(Entry*) * collection->capacity);
    }

    if (!collection->head) {
        collection->head = entry;
        collection->tail = entry;
    } else {
        collection->tail->next = entry;
        collection->tail = entry;
    }

    collection->size++;
    collection->memory_usage += sizeof(Entry);
}

void collection_delete(Collection *collection, Entry *entry) {
    if (collection->head == entry) {
        collection->head = entry->next;
    } else if (collection->tail == entry) {
        collection->tail = collection->tail->next;
    }

    free(entry);
    collection->size--;
    collection->memory_usage -= sizeof(Entry);
}

void collection_free(Collection *collection) {
    Entry *current = collection->head;
    while (current != NULL) {
        Entry *next = current->next;
        free(current);
        current = next;
    }

    free(collection->entries);
    free(collection);
}
```

This implementation provides functions for creating a collection, inserting and deleting entries, validating file paths, and freeing the memory upon completion. The custom allocator can be passed during collection creation to optimize memory usage. The collection uses a singly linked list structure for efficient insertion and deletion of entries while handling memory fragmentation.']

