```cpp
#include <iostream>
#include <fstream>
#include <vector>
#include <map>
#include <stdexcept>
#include <new>

enum class Color { RED, GREEN, BLUE };

struct Coordinate {
    float x;
    float y;
};

void* allocate(size_t size, size_t elementCount) {
    void* memory = std::malloc(size * elementCount);
    if (!memory) {
        throw std::runtime_error("Memory allocation failed.");
    }
    return memory;
}

template<typename T>
T* createArray(size_t elementCount) {
    void* memory = allocate(sizeof(T) * elementCount, 1);
    return static_cast<T*>(memory);
}

std::vector<Coordinate> createStructs(size_t elementCount, float minX, float maxX, float minY, float maxY) {
    std::vector<Coordinate> coordinates;
    coordinates.reserve(elementCount);

    for (size_t i = 0; i < elementCount; ++i) {
        Coordinate coord{};
        coord.x = minX + static_cast<float>(std::rand()) / RAND_MAX * (maxX - minX);
        coord.y = minY + static_cast<float>(std::rand()) / RAND_MAX * (maxY - minY);
        coordinates.push_back(coord);
    }

    return coordinates;
}

void deallocate(void* memory, size_t elementCount) {
    std::free(memory);
}

std::map<Color, std::vector<Coordinate>> manageMemory(size_t arraySize, size_t structCount, float minX, float maxX, float minY, float maxY) {
    auto doubleArray = createArray<double>(arraySize);
    auto colorStructs = createStructs(structCount, minX, maxX, minY, maxY);

    std::map<Color, std::vector<Coordinate>> result;
    result[Color::RED] = std::move(colorStructs);

    deallocate(doubleArray, 1);
    return result;
}
```

