void load_records(int max_size, int record_size, const char* filename) {
    std::ifstream file(filename);
    if (!file.is_open()) throw std::runtime_error("Unable to open records file.");

    size_t line_len = 0;
    char* line = nullptr;
    ssize_t read;

    while ((read = getline(&line, &line_len, file)) != -1) {
        if (records.size() + record_size >= max_size) {
            std::cerr << "Warning: Maximum size of records array exceeded. Limiting to " << records.size() << " records.\n";
            break;
        }

        Record* new_record = new Record{record_id++, nullptr, nullptr, {}, 0, 0};
        records_mutex.lock();
        new_record->next = records.empty() ? nullptr : records.back();
        records.push_back(new_record);
        records_mutex.unlock();

        std::istringstream iss(line);
        std::string token;
        int i = 0;
        for (iss >> token; iss && i < record_size - 1; iss >> token) {
            new_record->field[i++] = token[0];
            new_record->field[i] = '\0';
        }

        std::istringstream timestamp_iss(token);
        time_t temp_time;
        if (std::istream::peek(timestamp_iss, 10) == 'T') { // Check for ISO format timestamp
            timestamp_iss >> std::get_time_t(&temp_time);
        } else {
            throw std::runtime_error("Invalid timestamp format.");
        }
        new_record->timestamp = temp_time;
    }

    free(line);
}

void save_records() {
    records_mutex.lock();
    for (auto record : records) {
        std::ofstream file("records.txt", std::ios_base::app);
        file << record->field;
        if (!record->next) break; // Break loop on last record
        file << '\n';
    }
    records_mutex.unlock();
}

void update_status(int key, int status) {
    records_mutex.lock();
    for (auto record : records) {
        if (record->key == key) {
            record->status = status;
            break;
        }
        if (!record->next) break; // Break loop on last record
    }
    records_mutex.unlock();
}
```

