1. Data structure (Custom Hash Map with LRU Cache):

```cpp
#include <unordered_map>
#include <list>
#include <chrono>

template<typename K, typename V>
class LRUCache {
public:
    LRUCache(size_t capacity) : _capacity(capacity), _accessTime(_timeNow()), _cache() {}

    void access(const K& key) {
        auto it = _cache.find(key);
        if (it != _cache.end()) {
            _cache.erase(it);
            _cache.emplace(_timeNow(), std::move(it));
        }
        else {
            if (_cache.size() >= _capacity) _cache.begin()->second.second = _timeNow();
            _cache.emplace(_timeNow(), std::make_pair(key, V()));
        }
    }

private:
    auto _timeNow() const { return std::chrono::high_resolution_clock::now(); }
    size_t _capacity;
    std::unordered_map<decltype(_timeNow)(), std::pair<K, V>> _cache;
};
```

