3. Thread Pool:

```cpp
#include <vector>
#include <queue>
#include <atomic>
#include <thread>
#include <mutex>

class ThreadPool {
public:
    explicit ThreadPool(size_t numThreads) : _numThreads(numThreads), _stopped(false) {}

    void enqueue(std::function<void()> task) {
        std::unique_lock<std::mutex> lock(_queueMutex);
        _tasks.emplace([task, lock]() mutable { task(); lock.unlock(); });
        _condVar.notify_one();
    }

    void join() {
        {
            std::unique_lock<std::mutex> lock(_stopMutex);
            _stopped = true;
        }
        _condVar.notify_all();
        _threads.join_all();
    }

private:
    void threadFunc() {
        for (;;) {
            std::function<void()> task;
            {
                std::unique_lock<std::mutex> lock(_queueMutex);
                _condVar.wait(lock, [this] { return !_tasks.empty() || _stopped; });
                if (!_tasks.empty()) {
                    task = std::move(_tasks.front());
                    _tasks.pop_front();
                }
            }
            if (task) task();
        }
    }

    size_t _numThreads;
    std::vector<std::thread> _threads;
    std::queue<std::function<void()>> _tasks;
    std::mutex _queueMutex;
    std::condition_variable _condVar;
    std::mutex _stopMutex;
    std::atomic_bool _stopped;
};
```

