    auto nineSecondsAgo = now - std::chrono::seconds(9);

    for (auto& action : actions) {
        if (actionHistory[playerId].empty() ||
            action.second.cooldown > nineSecondsAgo) {

            double totalProbability = 0;
            for (auto& [_, probability] : probabilities) {
                totalProbability += probability;
            }

            std::uniform_real_distribution<double> distribution(0, totalProbability);
            double randomProbability = distribution(rng);

