import java.util.concurrent.locks.Lock;
import java.util.concurrent.locks.ReentrantLock;

class Record {
    int value;
}

class Point {
    int x, y;
}

class Polygon {
    Lock lock = new ReentrantLock();
    String name;
    List<Point> points = new ArrayList<>();
    Record record;

    public void addPoint(Point point) {
        lock.lock();
        try {
            points.add(point);
        } finally {
            lock.unlock();
        }
    }
}

class PointAllocator {
    private Random random = new Random();

    public Point allocatePoint() {
        Point point = new Point();
        point.x = random.nextInt(100);
        point.y = random.nextInt(100);
        return point;
    }
}

class MemoryManager {
    private static final int MAX_POLYGONS = 1000;
    private static List<Polygon> polygons = new ArrayList<>();
    private static PointAllocator pointAllocator = new PointAllocator();
    private static Lock polygonListLock = new ReentrantLock();

    public Polygon allocatePolygon() {
        if (polygons.size() >= MAX_POLYGONS) {
            pruneUnusedPolygons();
        }

        Polygon polygon = new Polygon();
        polygon.name = "Polygon" + polygons.size();
        polygons.add(polygon);
        return polygon;
    }

    private void pruneUnusedPolygons() {
        polygonListLock.lock();
        try {
            Iterator<Polygon> iterator = polygons.iterator();
            while (iterator.hasNext()) {
                Polygon polygon = iterator.next();
                if (polygon.points.isEmpty()) {
                    iterator.remove();
                }
            }
        } finally {
            polygonListLock.unlock();
        }
    }

    // Memory usage logging and other functionalities can be added here
}

public class Main {
