        MemoryManager memoryManager = new MemoryManager();
        Polygon polygon = memoryManager.allocatePolygon();

        for (int i = 0; i < 10; i++) {
            Point point = pointAllocator.allocatePoint();
            polygon.addPoint(point);
        }

        Record record = new Record();
        record.value = random.nextInt(100);
        polygon.record = record;

        // Command execution and memory usage logging can be added here
    }
}
```

