void* allocate(size_t size, size_t alignment) {
    void* result = mmap(NULL, size + ALIGNMENT, PROT_READ | PROT_WRITE, MAP_PRIVATE | MAP_ANONYMOUS, -1, 0);
    if (result == MAP_FAILED) {
        failed_allocations++;
        return nullptr;
    }
    size_t aligned_size = ((size + ALIGNMENT - 1) / ALIGNMENT) * ALIGNMENT;
    return realloc(result, aligned_size);
}

void init() {
    long* offsets_ptr = static_cast<long*>(allocate(MAX_RECORDS * sizeof(long), ALIGNMENT));
    if (!offsets_ptr) {
        std::cerr << "Failed to allocate memory for offsets" << std::endl;
        return;
