    int value;
} Record;

typedef struct {
    unsigned RNTI;
    unsigned CRC_INDICATION_REL8_TAG;
    bool CRCFLAG;
} NFAPI_CRC_INDICATION_PDU_T;

struct Node {
    union {
        Record record;
        NFAPI_CRC_INDICATION_PDU_T pdu;
    } data;
    struct Node* next;
};

size_t max_elements = 10000000;
size_t records_count = 0, pdus_count = 0;
size_t memory_used = 0;

void* allocate(size_t size) {
    void* ptr = malloc(size);
    if (!ptr) {
        fprintf(stderr, "Out of memory\n");
        return NULL;
    }
    memory_used += size;
    return ptr;
}

void free_all() {
    struct Node* current = NULL;
    struct Node* next = NULL;

    while (records) {
        current = records;
        records = records->next;
        free(current);
    }

    while (pdus) {
        current = pdus;
        pdus = pdus->next;
        free(current);
    }
}

bool add_record(int value) {
    if (records_count >= max_elements) return false;

    struct Node* new_node = (struct Node*)allocate(sizeof(struct Node));
    if (!new_node) return false;

    new_node->data.value = value;
    new_node->next = records;
    records = new_node;
    records_count++;
    return true;
}

bool add_pdu(unsigned RNTI, unsigned CRC_INDICATION_REL8_TAG, bool CRCFLAG) {
    if (pdus_count >= max_elements) return false;

    struct Node* new_node = (struct Node*)allocate(sizeof(struct Node));
    if (!new_node) return false;

    new_node->data.pdu.RNTI = RNTI;
    new_node->data.pdu.CRC_INDICATION_REL8_TAG = CRC_INDICATION_REL8_TAG;
    new_node->data.pdu.CRCFLAG = CRCFLAG;
    new_node->next = pdus;
    pdus = new_node;
    pdus_count++;
    return true;
}

void log_memory() {
    printf("Memory usage: %zu bytes\n", memory_used);
    if (memory_used >= max_elements * 0.9) {
        fprintf(stderr, "Warning: Memory usage is close to the maximum capacity.\n");
    }
}

struct Node* records = NULL;
struct Node* pdus = NULL;
