    int *keys = create_key_array(KEY_COUNT);
    Record *records = create_record_array(RECORD_COUNT);

    check_integrity(records, offsets, keys);

    mempool_free(offsets, sizeof(long) * OFFSET_COUNT);
    mempool_free(keys, sizeof(int) * KEY_COUNT);
    mempool_free(records, sizeof(Record) * RECORD_COUNT);

    return 0;
}
