[" Here's an implementation using the C++11 standard library with boost for concurrency and smart pointers for memory management. This example demonstrates a basic hash table structure, but it may need further optimization based on specific use cases and requirements.

```cpp
#include <iostream>
#include <vector>
#include <unordered_map>
#include <mutex>
#include <boost/circular_buffer.hpp>
#include <boost/smart_ptr/shared_ptr.hpp>

struct Record {
    int key;
    long offset;
    time_t timestamp;
};

class HashTable {
public:
    HashTable(size_t size) : table_(std::make_unique<std::unordered_map<int, shared_ptr<Record>>>(size),
                               mutex_) {}

    shared_ptr<Record> insert(const Record& record) {
        std::lock_guard<std::mutex> lock(mutex_);
        auto it = table_->emplace(record.key, make_shared<Record>(record));
        if (!it.second) {
            it.first->second->timestamp = record.timestamp;
        }
        return it.first->second;
    }

    shared_ptr<Record> find(int key) const {
        std::lock_guard<std::mutex> lock(mutex_);
        auto it = table_->find(key);
        if (it != table_->end()) {
            return it->second;
        }
        return nullptr;
    }

private:
    std::unique_ptr<std::unordered_map<int, shared_ptr<Record>>> table_;
    mutable std::mutex mutex_;
};

class GarbageCollector {
public:
    void collect(HashTable& hashTable) {
        std::lock_guard<std::mutex> lock(hashTable.mutex_);
        for (auto& it : *hashTable.table_) {
            if (it.second->timestamp < currentTime() - MAX_AGE) {
                table_.push_back(it.second);
                hashTable.table_->erase(it.first);
            }
        }
    }

private:
    boost::circular_buffer<shared_ptr<Record>> table_;
    static time_t currentTime() { return std::time(nullptr); }
};
```

In this example, `HashTable` is the main data structure that manages records. It uses a concurrent hash map to store records and a mutex lock for synchronization during insertion and lookup operations. The `GarbageCollector` class handles periodic garbage collection of unused records based on a specified maximum age.

You can integrate this code into your larger application by creating multiple instances of the `HashTable` and `GarbageCollector` classes to manage concurrent operations efficiently. Additionally, you may want to consider using more advanced data structures or locking mechanisms for better performance in specific scenarios."]

