typedef struct Record {
    int value;
} Record;

pthread_mutex_t mutex;
int max_records = -1; // Initialize to an invalid value

void init_random() {
    if (pthread_mutex_init(&mutex, NULL) != 0) {
        perror("Mutex initialization failed");
        exit(EXIT_FAILURE);
    }
}

int random(int limit) {
    pthread_mutex_lock(&mutex);
    srand(time(NULL));
    int result = rand() % limit;
    pthread_mutex_unlock(&mutex);
    return result;
}

void check_and_init_max_records(int max) {
    if (max <= 0) {
        fprintf(stderr, "Invalid maximum size: %d\n", max);
        exit(EXIT_FAILURE);
    }

    if (max > max_records) {
        Record* temp = realloc(max_records, sizeof(Record) * max);
        if (!temp) {
            perror("Reallocation failed");
            exit(EXIT_FAILURE);
        }
        max_records = temp;
    }
}

int* allocate_longs(int size) {
