```c
#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <time.h>

typedef struct {
    int key;
    long offset;
    time_t timestamp;
    int status;
} Record;

struct hash_node {
    Record record;
    struct hash_node *next;
};

struct hash_table {
    unsigned int size;
    struct hash_node **nodes;
    pthread_mutex_t lock;
};

unsigned long custom_hash(int key, unsigned int table_size) {
    return (key % table_size);
}

void init_hash_table(struct hash_table *ht, unsigned int size) {
    ht->size = size;
    ht->nodes = calloc(size, sizeof(Record*));
    if (!ht->nodes) {
        perror("Calloc failed");
        exit(EXIT_FAILURE);
    }
    for (unsigned int i = 0; i < size; ++i) {
        ht->nodes[i] = NULL;
    }
    pthread_mutex_init(&ht->lock, NULL);
}

void resize_hash_table(struct hash_table *ht, unsigned int new_size) {
    struct hash_node **old_nodes = ht->nodes;
    ht->nodes = calloc(new_size, sizeof(Record*));
    if (!ht->nodes) {
        perror("Calloc failed");
        exit(EXIT_FAILURE);
    }
    for (unsigned int i = 0; i < new_size; ++i) {
        ht->nodes[i] = NULL;
    }

    unsigned int old_size = ht->size;
    for (unsigned int i = 0; i < old_size; ++i) {
        struct hash_node *current = old_nodes[i];
        while (current != NULL) {
            struct hash_node *next = current->next;
            unsigned long hash = custom_hash(current->record.key, new_size);
            current->next = ht->nodes[hash];
            ht->nodes[hash] = current;
            current = next;
        }
    }

    free(old_nodes);
    ht->size = new_size;
}

// Implement functions for adding, removing, and finding records in the hash table.
// Use pthread_mutex_lock() and pthread_mutex_unlock() to protect against race conditions during concurrent operations.
```

