    char id[16];
    char timestamp[18];
} Key;

typedef struct DataRecord {
    void* data;
    int size;
    int capacity;
} DataRecord;

Offset offset_create(int initial_capacity) {
    Offset offset = {NULL, 0, initial_capacity};
    offset.keys = malloc(offset.capacity * sizeof(Key*));
    return offset;
}

void offset_resize(Offset* offset, int new_capacity) {
    if (new_capacity <= offset->capacity) return;
    offset->capacity = new_capacity;
    offset->keys = realloc(offset->keys, offset->capacity * sizeof(Key*));
}

void offset_push(Offset* offset, Key* key) {
    if (offset->size == offset->capacity) offset_resize(offset, offset->capacity * 2);
    offset->keys[offset->size++] = key;
}

DataRecord data_record_create(int initial_capacity) {
    DataRecord record = {NULL, 0, initial_capacity};
    record.data = malloc(record.capacity);
    return record;
}

void data_record_resize(DataRecord* record, int new_capacity) {
    if (new_capacity <= record->capacity) return;
    record->capacity = new_capacity;
    record->data = realloc(record->data, record->capacity);
}

void data_record_append(DataRecord* record, void* element) {
    if (record->size == record->capacity) data_record_resize(record, record->capacity * 2);
    memcpy(record->data + record->size, element, sizeof(*element));
    record->size++;
}

