    else if (strchr(original_filename, 'b')) strcpy(filetype, ".csv");
    else strcpy(filetype, ".log");

    size_t len = strlen(original_filename) + strlen(timestamp) + strlen(filetype) + 5; // for "_", random, and extension
    char* new_filename = malloc(len + 1);
    snprintf(new_filename, len + 1, "%s_%s%04d%s", original_filename, timestamp, random, filetype);
    return new_filename;
}

