```c
#include <stdio.h>
#include <stdlib.h>
#include <stdbool.h>
#include <time.h>

typedef struct Record {
    int key;
    int value;
    struct Record *next;
} Record;

Record* create_record(int key, int value) {
    Record *new_record = (Record *)malloc(sizeof(Record));
    if (!new_record) {
        perror("Memory allocation failure");
        exit(EXIT_FAILURE);
    }

    new_record->key = key;
    new_record->value = value;
    new_record->next = NULL;

    return new_record;
}

Record* find_record(Record *head, int key) {
    Record *current = head;
    while (current != NULL) {
        if (current->key == key) {
            return current;
        }
        current = current->next;
    }
    return NULL;
}

void insert_record(Record **head, int key, int value) {
    Record *new_record = create_record(key, value);
    if (!*head) {
        *head = new_record;
        return;
    }

    Record *current = *head;
    while (current->next != NULL) {
        current = current->next;
    }
    current->next = new_record;
}

void delete_record(Record **head, int key) {
    if (!*head) {
        return;
    }

    Record *current = *head;
    if (current->key == key) {
        *head = current->next;
        free(current);
        return;
    }

    while (current->next != NULL && current->next->key != key) {
        current = current->next;
    }

    if (current->next == NULL) {
        return;
    }

    Record *to_delete = current->next;
    current->next = current->next->next;
    free(to_delete);
}

void randomize_values(Record *head, int min_value, int max_value) {
    srand(time(NULL));
    Record *current = head;
    while (current != NULL) {
        current->value = rand() % (max_value - min_value + 1) + min_value;
        current = current->next;
    }
}

void clean_up(Record **head) {
    Record *current = *head;
    while (*head != NULL) {
        current = *head;
        *head = (*head)->next;
        free(current);
    }
}
```

