#include <iostream>
#include <vector>
#include <random>
#include <algorithm>
#include <boost/archive/binary_oarchive.hpp>
#include <boost/archive/binary_iarchive.hpp>
#include <boost/serialization/vector.hpp>
#include <boost/serialization/array.hpp>
#include <boost/serialization/long.hpp>
#include <boost/serialization/uint32_t.hpp>
#include <boost/serialization/utility.hpp>
#include <sqlite3.h>
#include <sstream>
#include <fstream>
#include <cstdio>
#include <cstring>

struct Record {
    int value;
    Record() {}
    Record(int v) : value(v) {}

    friend class boost::serialization::access;

    template<class Archive>
    void serialize(Archive & ar, const unsigned int version) {
        ar & value;
    }
};

void init_data(std::vector<long>& offsets, std::vector<int>& keys, std::vector<Record>& records, int num_records, int min_value, int max_value) {
    std::random_device rd;
    std::mt19937 gen(rd());
    std::uniform_int_distribution<> dis(min_value, max_value);

    offsets.resize(num_records + 1);
    keys.resize(num_records);
    records.resize(num_records);

    for (size_t i = 0; i < num_records; ++i) {
        keys[i] = i;
        records[i].value = dis(gen);
        offsets[i + 1] = offsets[i] + sizeof(Record);
    }
}

void sort_data(std::vector<long>& offsets, std::vector<int>& keys, std::vector<Record>& records) {
    std::sort(keys.begin(), keys.end(), [&](const int a, const int b) { return records[a].value < records[b].value; });
}

void save_to_file(const char* filename, const std::vector<long>& offsets, const std::vector<int>& keys, const std::vector<Record>& records, bool csv = false) {
    std::ofstream file(filename, std::ios::binary);
    if (csv) {
        file << "Key,Value\n";
    }

    for (size_t i = 0; i < keys.size(); ++i) {
        boost::archive::binary_oarchive oa(file);
        oa & BOOST_SERIALIZATION_NVP(records[keys[i]]);
        if (!csv) {
            file.write(reinterpret_cast<const char*>(offsets[i]), offsets[i + 1] - offsets[i]);
        }
    }
}

void load_from_file(const char* filename, std::vector<long>& offsets, std::vector<int>& keys, std::vector<Record>& records, bool csv = false) {
    std::ifstream file(filename, std::ios::binary);

    if (csv) {
        std::string line;
        getline(file, line);
    }

    while (!file.eof()) {
        boost::archive::binary_iarchive ia(file);
        Record record;
        ia & BOOST_SERIALIZATION_NVP(record);
        if (!csv) {
            size_t pos = file.tellg();
            offsets.push_back(pos);
            records.push_back(record);
        }
    }
}

void save_to_db(sqlite3* db, const std::vector<Record>& records) {
    sqlite3_stmt* stmt;
    char sql[256];

    sqlite3_prepare_v2(db, "CREATE TABLE IF NOT EXISTS records (id INTEGER PRIMARY KEY AUTOINCREMENT, value INTEGER)", -1, &stmt, NULL);
    sqlite3_step(stmt);
    sqlite3_finalize(stmt);

    snprintf(sql, sizeof(sql), "BEGIN TRANSACTION;");
    sqlite3_prepare_v2(db, sql, -1, &stmt, NULL);
    sqlite3_step(stmt);

    for (const auto& record : records) {
        snprintf(sql, sizeof(sql), "INSERT INTO records (value) VALUES (%d)", record.value);
        sqlite3_prepare_v2(db, sql, -1, &stmt, NULL);
        sqlite3_step(stmt);
    }

    snprintf(sql, sizeof(sql), "COMMIT;");
    sqlite3_prepare_v2(db, sql, -1, &stmt, NULL);
    sqlite3_step(stmt);
    sqlite3_finalize(stmt);
}

void load_from_db(sqlite3* db, std::vector<Record>& records) {
    sqlite3_stmt* stmt;
    char sql[256];
    Record record;

    snprintf(sql, sizeof(sql), "SELECT value FROM records ORDER BY id;");
    sqlite3_prepare_v2(db, sql, -1, &stmt, NULL);

    while (sqlite3_step(stmt) == SQLITE_ROW) {
        record.value = static_cast<int>(sqlite3_column_int(stmt, 0));
        records.push_back(record);
    }

    sqlite3_finalize(stmt);
}
```

This code provides a flexible interface for managing data structures, sorting them efficiently, and saving the sorted records to either binary or CSV files or a SQLite database. The function handles potential memory allocation failures gracefully and adheres to a logging mechanism for tracking operations.']

