#include <stdio.h>
#include <stdlib.h>
#include <stdbool.h>
#include <time.h>

typedef struct Record {
    int key;
    int value;
    struct Record* next;
} Record;

typedef struct DataAccessLayer {
    unsigned int capacity;
    unsigned int size;
    Record** records;
    unsigned int seed;
    bool allow_duplicates;
    FILE* log_file;
} DataAccessLayer;

DataAccessLayer* create_data_access_layer(unsigned int capacity, unsigned int seed, bool allow_duplicates) {
    DataAccessLayer* dal = (DataAccessLayer*)malloc(sizeof(DataAccessLayer));
    if (!dal) {
        fprintf(stderr, "Memory allocation for DataAccessLayer failed.\n");
        return NULL;
    }

    dal->capacity = capacity;
    dal->size = 0;
    dal->records = (Record**)malloc(capacity * sizeof(Record*));
    if (!dal->records) {
        fprintf(stderr, "Memory allocation for records array failed.\n");
        free(dal);
        return NULL;
    }

    srand(seed);
    dal->seed = seed;
    dal->allow_duplicates = allow_duplicates;
    dal->log_file = stdout; // Initialize log file to standard output

    for (unsigned int i = 0; i < capacity; ++i) {
        dal->records[i] = NULL;
    }

    return dal;
}

void destroy_data_access_layer(DataAccessLayer* dal) {
    Record* current = NULL;
    for (unsigned int i = 0; i < dal->capacity; ++i) {
        Record* next = dal->records[i];
        while (current != next) {
            current = next;
            next = next->next;
            free(current);
        }
    }
    free(dal->records);
    free(dal);
}

Record* find_record(DataAccessLayer* dal, unsigned int key) {
    Record* current = dal->records[key % dal->capacity];
    while (current != NULL && current->key != key) {
        current = current->next;
    }
    return current;
}

Record* create_record(int value) {
    Record* record = (Record*)malloc(sizeof(Record));
    if (!record) {
        fprintf(stderr, "Memory allocation for Record failed.\n");
        return NULL;
    }

    record->key = rand() % UINT32_MAX;
    record->value = value;
    record->next = NULL;

    return record;
}

int insert_record(DataAccessLayer* dal, int key, int value) {
    Record* existing = find_record(dal, key);
    if (existing && !dal->allow_duplicates) {
        fprintf(stderr, "Trying to insert duplicate record with key %u.\n", key);
        return -1;
    }

    Record* new_record = create_record(value);
    if (!new_record) {
        return -2;
    }

    if (existing) {
        new_record->next = existing->next;
        existing->next = new_record;
    } else {
        unsigned int index = key % dal->capacity;
        new_record->next = dal->records[index];
        dal->records[index] = new_record;
        ++dal->size;
    }

    if (dal->log_file != stdout) {
        fprintf(dal->log_file, "Inserted record with key %u and value %d.\n", key, value);
    }

    return 0;
}

int delete_record(DataAccessLayer* dal, unsigned int key) {
    Record* current = find_record(dal, key);
    if (!current) {
        fprintf(stderr, "Trying to delete non-existent record with key %u.\n", key);
        return -1;
    }

    Record* next = current->next;
    free(current);
    --dal->size;

    if (next == NULL) {
        unsigned int index = key % dal->capacity;
        dal->records[index] = NULL;
    } else {
        unsigned int index = (key + 1) % dal->capacity;
        Record* previous = find_record(dal, index - 1);
        if (!previous) {
            fprintf(stderr, "Trying to delete record with key %u and no next record found.\n", key);
            return -2;
        }
        previous->next = next;
    }

    if (dal->log_file != stdout) {
        fprintf(dal->log_file, "Deleted record with key %u.\n", key);
    }

    return 0;
}

int retrieve_record(DataAccessLayer* dal, unsigned int key, int* value) {
    Record* current = find_record(dal, key);
    if (!current) {
        fprintf(stderr, "Trying to retrieve non-existent record with key %u.\n", key);
        return -1;
    }

    *value = current->value;

    if (dal->log_file != stdout) {
        fprintf(dal->log_file, "Retrieved record with key %u and value %d.\n", key, *value);
    }

    return 0;
}
