    Record* record = (Record*)malloc(sizeof(Record));
    if (!record) return NULL;
    record->key = key;
    record->value = value;
    record->next = NULL;
    return record;
}

void insert_record(Record** head, int key, int value) {
    Record* new_record = create_record(key, value);
    if (!new_record) {
        fprintf(stderr, "Memory allocation failure\n");
        exit(EXIT_FAILURE);
    }

    Record* current = *head;
    if (!current) {
        *head = new_record;
        return;
    }

    while (current->next && current->next->key < key) current = current->next;

    new_record->next = current->next;
    current->next = new_record;
}

Record* find_record(Record* head, int key) {
    Record* current = head;
    while (current) {
        if (current->key == key) return current;
        current = current->next;
    }
    return NULL;
}

void delete_record(Record** head, int key) {
    Record* to_delete = find_record(*head, key);
    if (!to_delete) {
        fprintf(stderr, "No such record\n");
        return;
    }

    if (to_delete == *head) *head = to_delete->next;
    else {
        Record* current = *head;
        while (current->next != to_delete) current = current->next;
        current->next = to_delete->next;
    }
    free(to_delete);
}

void init_records(Record** head, int num_records, int min_value, int max_value) {
