    struct Session *next;
} Session;

typedef struct SessionManager {
    Session *head;
    Session *tail;
    int max_memory;
    int current_memory;
    pthread_mutex_t lock;
} SessionManager;

SessionManager* session_manager_init(int max_memory) {
    SessionManager* manager = malloc(sizeof(SessionManager));
    if (!manager) return NULL;

    manager->head = NULL;
    manager->tail = NULL;
    manager->max_memory = max_memory;
    manager->current_memory = 0;
    pthread_mutex_init(&manager->lock, NULL);

    return manager;
}

Session* session_list_alloc(SessionManager* manager) {
    if (manager->current_memory + sizeof(Session) > manager->max_memory) {
        fprintf(stderr, "Error: Memory allocation failed. Current memory usage exceeds the maximum allowed.\n");
        return NULL;
    }

    Session* session = malloc(sizeof(Session));
    if (!session) {
        fprintf(stderr, "Error: Memory allocation failed.\n");
        return NULL;
    }

    pthread_mutex_lock(&manager->lock);

    if (manager->tail) {
        manager->tail->next = session;
        manager->tail = session;
    } else {
        manager->head = session;
        manager->tail = session;
    }

    manager->current_memory += sizeof(Session);

    pthread_mutex_unlock(&manager->lock);

    return session;
}

