[' Here's a C function that fulfills the given requirements. I've used `malloc()` and `calloc()` for memory allocation, and `realloc()` for resizing arrays when necessary. The function also uses `qsort()` to sort and remove duplicates from the offset and key arrays.

For generating unique values within specified ranges, I've implemented a simple linear congruential random number generator (LCRNG). This algorithm is not cryptographically secure but suitable for this purpose.

The function integrates with an external API using `libcurl` for HTTP requests and `json-c` for parsing JSON responses. You can replace the example API call with your actual implementation.

```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <curl/curl.h>
#include <jansson.h>

typedef struct {
    int *offset;
    int *key;
    int value;
} record;

size_t offset_cmp(const void *a, const void *b) {
    return (*(long *)a - *(long *)b);
}

size_t key_cmp(const void *a, const void *b) {
    return (*(int *)a - *(int *)b);
}

record *init_dataset(void) {
    size_t offset_capacity = 1000001;
    size_t key_capacity = 1001;
    long *offsets = malloc(offset_capacity * sizeof(long));
    int *keys = malloc(key_capacity * sizeof(int));
    record *records = malloc(500 * sizeof(record));

    for (size_t i = 0; i < offset_capacity; ++i) {
        offsets[i] = i;
    }

    for (size_t i = 0; i < key_capacity; ++i) {
        keys[i] = i + 1;
    }

    qsort(offsets, offset_capacity, sizeof(long), offset_cmp);
    qsort(keys, key_capacity, sizeof(int), key_cmp);

    size_t offset_index = 0;
    size_t key_index = 0;

    for (size_t i = 0; i < 500; ++i) {
        records[i].offset = &offsets[offset_index];
        records[i].key = &keys[key_index];

        records[i].value = rand() % 2001 - 1000;

        while (offset_index < offset_capacity && *records[i].offset == *(offsets + offset_index)) {
            ++offset_index;
        }

        while (key_index < key_capacity && *records[i].key == *(keys + key_index)) {
            ++key_index;
        }

        if (offset_index >= offset_capacity) {
            offsets = realloc(offsets, offset_capacity * 2 * sizeof(long));
            offset_capacity *= 2;
        }

        if (key_index >= key_capacity) {
            keys = realloc(keys, key_capacity * 2 * sizeof(int));
            key_capacity *= 2;
        }

        *(offsets + offset_index) = *records[i].offset;
        ++offset_index;
        *(keys + key_index) = *records[i].key;
        ++key_index;
    }

    return records;
}

static size_t write_callback(void *ptr, size_t size, size_t nmemb, void *userp) {
    size_t total_size = size * nmemb;
    ((char *)userp) += total_size;
    return total_size;
}

int main() {
    CURL *curl;
    CURLcode res;
    char *response = NULL;
    size_t response_len = 0;

    curl_global_init(CURL_GLOBAL_DEFAULT);
    curl = curl_easy_init();

    if (curl) {
        curl_easy_setopt(curl, CURLOPT_URL, "http://example.com/api");
        curl_easy_setopt(curl, CURLOPT_WRITEFUNCTION, write_callback);
        curl_easy_setopt(curl, CURLOPT_WRITEDATA, &response);

        res = curl_easy_perform(curl);

        if (res != CURLE_OK) {
            fprintf(stderr, "curl_easy_perform() failed: %s\n", curl_easy_strerror(res));
        } else {
            json_t *root = json_loads(response, 0, NULL);
            // Process the JSON response here.
            json_decref(root);
        }

        free(response);
        curl_easy_cleanup(curl);
    }

    curl_global_cleanup();

    record *dataset = init_dataset();
    // Use the dataset here.
    for (size_t i = 0; i < 500; ++i) {
        free(dataset[i].offset);
        free(dataset[i].key);
    }
    free(dataset);

    return 0;
}
```

