[' Here is a simplified version of the requested C function using pthreads for multi-threading, malloc and calloc for memory management, and a custom memory pool for minimizing fragmentation. The struct vector is defined with x and y coordinates as floats. The function dynamically resizes arrays, handles memory leaks, and supports large datasets with a maximum size limit.

```c
#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <time.h>

typedef struct {
    float x, y;
} vector;

struct memory_block {
    size_t size;
    void *data;
    struct memory_block *next;
};

static struct memory_block *memory_pool = NULL;
static pthread_mutex_t memory_lock = PTHREAD_MUTEX_INITIALIZER;

void* mem_alloc(size_t size) {
    pthread_mutex_lock(&memory_lock);
    struct memory_block *current = memory_pool;
    while (current != NULL && current->size < size) {
        current = current->next;
    }

    if (current == NULL || current->size >= size) {
        current = malloc(sizeof(struct memory_block));
        if (!current) {
            pthread_mutex_unlock(&memory_lock);
            return NULL;
        }
        current->size = size;
        current->data = calloc(size, 1);
        if (!current->data) {
            free(current);
            pthread_mutex_unlock(&memory_lock);
            return NULL;
        }
        current->next = memory_pool;
        memory_pool = current;
    }

    void *result = current->data;
    current->data += size;
    pthread_mutex_unlock(&memory_lock);
    return result;
}

void mem_free(void *ptr, size_t size) {
    pthread_mutex_lock(&memory_lock);
    struct memory_block *current = memory_pool;
    struct memory_block *previous = NULL;

    while (current != NULL && current->data > ptr) {
        previous = current;
        current = current->next;
    }

    if (current == NULL || current->size < size) {
        fprintf(stderr, "Trying to free more memory than allocated\n");
        pthread_mutex_unlock(&memory_lock);
        return;
    }

    if (previous == NULL) {
        memory_pool = current->next;
    } else {
        previous->next = current->next;
    }

    free(current->data);
    free(current);
    pthread_mutex_unlock(&memory_lock);
}

void init_vectors(double *doubles, vector **vectors, size_t size, size_t max_size) {
    if (size > max_size) {
        fprintf(stderr, "Requested size exceeds maximum allowed size\n");
        return;
    }

    for (size_t i = 0; i < size; ++i) {
        void *d_ptr = mem_alloc(sizeof(double));
        if (!d_ptr) {
            fprintf(stderr, "Failed to allocate memory for doubles\n");
            return;
        }
        doubles[i] = (double*) d_ptr;

        void *v_ptr = mem_alloc(sizeof(vector));
        if (!v_ptr) {
            fprintf(stderr, "Failed to allocate memory for vectors\n");
            mem_free(doubles[i], sizeof(double));
            return;
        }
        vectors[i] = (vector*) v_ptr;

        (*vectors[i]).x = rand() / RAND_MAX * 10.0;
        (*vectors[i]).y = rand() / RAND_MAX * 10.0;
    }
}

void destroy_vectors(vector **vectors, size_t size) {
    for (size_t i = 0; i < size; ++i) {
        mem_free(vectors[i], sizeof(vector));
    }
}
```

