```c
#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <time.h>

typedef struct node {
    int data;
    struct node* next;
} Node;

void init_random_list(size_t* array_sizes, size_t max_elements, size_t min_val, size_t max_val) {
    double* darray = calloc(array_sizes[0], sizeof(double));
    if (!darray) {
        fprintf(stderr, "Error: Out of memory for double array.\n");
        return;
    }

    Node** list = calloc(array_sizes[1], sizeof(Node*));
    if (!list) {
        free(darray);
        fprintf(stderr, "Error: Out of memory for node pointers array.\n");
        return;
    }

    char** strings = calloc(array_sizes[2], sizeof(char*));
    if (!strings) {
        free(darray);
        free(list);
        fprintf(stderr, "Error: Out of memory for string array.\n");
        return;
    }

    srand(time(NULL));

    for (size_t i = 0; i < max_elements; ++i) {
        if (!list[i]) {
            list[i] = malloc(sizeof(Node));
            if (!list[i]) {
                fprintf(stderr, "Error: Out of memory for node %zu.\n", i);
                break;
            }
            list[i]->data = rand() % (max_val - min_val + 1) + min_val;
            list[i]->next = NULL;
        } else {
            Node* current = list[i];
            while (current->next) {
                current = current->next;
            }
            current->next = malloc(sizeof(Node));
            if (!current->next) {
                fprintf(stderr, "Error: Out of memory for node %zu.\n", i);
                break;
            }
            current->next->data = rand() % (max_val - min_val + 1) + min_val;
            current->next->next = NULL;
        }
    }

    // Generate strings here using the same random number generator or any other method you prefer.
}
```

This function initializes a linked list of `Node` structures, each containing an integer and a pointer to another `Node`. It also allocates memory for three arrays: one for double precision floating-point numbers, one for `struct node` pointers, and another for `char` strings. The function handles potential edge cases such as null pointers and out-of-memory conditions.

