void remove_record(int index) {
    if (index >= max_records || index < 0) {
        fprintf(stderr, "Error: Invalid index for removal\n");
        return;
    }

    Record *temp = realloc(record_array, (max_records - 1) * sizeof(Record));
    if (!temp) {
        fprintf(stderr, "Error: Could not allocate memory for updated record array\n");
        return;
    }

