int main() {
    DIR *dir = opendir("path/to/directory");
    if (!dir) return 1;

    struct dirent *entry;
    ImageData images[BATCH_SIZE];
    int processed = 0, total = 0;

    while ((entry = readdir(dir)) != NULL) {
        if (is_symbolic_link(get_file_stat(entry->d_name))) continue;

        strcpy(images[processed].path, entry->d_name);
        images[processed] = load_image(images[processed].path);
        total++;
        if (total == BATCH_SIZE) {
            for (int i = 0; i < processed; ++i) {
                pthread_t thread;
                pthread_create(&thread, NULL, process_image, &images[i]);
            }
            processed = 0;
        }
    }

    // Process remaining images if any
    for (int i = 0; i <= processed; ++i) {
        pthread_t thread;
        pthread_create(&thread, NULL, process_image, &images[i]);
    }

    // Wait for all threads to finish
    for (int i = 0; i <= total; ++i) {
        pthread_join(i, NULL);
    }

    closedir(dir);
    return 0;
}
