class JpegToPdf {
public:
    void convert(const std::string& input, const std::string& output, const std::string& jarPath) {
        Poppler::Document document;
        try {
            document.load_from_file(input);
            document.save_to_file(output, "pdf");
        } catch (const Poppler::Exception& e) {
            std::cerr << "Error converting JPEG to PDF: " << e.what() << std::endl;
            throw;
        }

        try {
            JavaVM* jvm = NULL;
            JNIEnv* env = NULL;
            JNI_CreateJavaVM(&jvm, (void**)&env, NULL);

            jobject outputStreamObj = env->NewObject(ObjectOutputStream::classID, "<init>", "(Ljava/io/OutputStream;)V");
            jobject fileOutputStreamObj = env->OpenFileInputStream(env->NewStringUTF(output.c_str()), "r");
            jobject objectOutputStream = env->CallObjectMethod(outputStreamObj, ObjectOutputStream::methodID_init, fileOutputStreamObj);

            jclass classToLoad = NULL;
            if (jarPath.empty()) {
                classToLoad = env->FindClass("your.package.YourClass");
            } else {
                jobject jarFile = env->NewGlobalRef(env->NewObject(JarFile::classID, "<init>", "(Ljava/io/File;)V", env->NewStringUTF(jarPath.c_str())));
                jmethodID getClassMethod = env->GetStaticMethodID(JarFile::classID, "getJarEntry", "(Ljava/lang/String;)Ljava/util/jar/JarEntry;");
                jobject jarEntryObj = env->CallStaticObjectMethod(jarFile, getClassMethod, env->NewStringUTF("your/package/YourClass.class"));
                jmethodID newInstanceMethod = env->GetMethodID(Class::classID, "<init>", "()V");
                classToLoad = (jclass)env->CallObjectMethod(env->CallObjectMethod(jarEntryObj, Class::methodID_newInstance), newInstanceMethod);
            }

            jobject serializedData = env->CallStaticObjectMethod(ObjectOutputStream::classID, ObjectOutputStream::methodID_writeObject, objectOutputStream, classToLoad);

            if (env->ExceptionCheck()) {
                std::cerr << "Error serializing data: Exception occurred" << std::endl;
