public class DirectoryService
{
    private readonly ILogger<DirectoryService> _logger;
    private readonly IConfiguration _configuration;
    private readonly IntegerProcessor _integerProcessor;
    private readonly ConcurrentDictionary<string, (int sum, int max)> _processedNumbers = new ConcurrentDictionary<string, (int sum, int max)>();

    public DirectoryService(ILogger<DirectoryService> logger, IConfiguration configuration, IntegerProcessor integerProcessor)
    {
        _logger = logger;
        _configuration = configuration;
        _integerProcessor = integerProcessor;
    }

    public bool AddWebsiteToDirectory(string directoryPath, string siteName, List<int> numbers)
    {
        if (!Directory.Exists(directoryPath))
        {
            _logger.LogError($"Directory '{directoryPath}' does not exist.");
            return false;
        }

        var webConfigPath = Path.Combine(directoryPath, "web.config");
        if (!File.Exists(webConfigPath))
        {
            _logger.LogError($"Web config file '{webConfigPath}' is missing.");
            return false;
        }

        lock (_processedNumbers)
        {
            if (_processedNumbers.ContainsKey(siteName))
                throw new ArgumentException("Site already exists in the directory");

            var (sum, max) = _integerProcessor.Process(numbers);
            _processedNumbers[siteName] = (sum, max);
        }

