                    FileName = _configuration["ProcessRunner:Executable"],
                    Arguments = $"add-website {directoryPath} {siteName} {sum} {max}",
                    UseShellExecute = false,
                    RedirectStandardOutput = true,
                    CreateNoWindow = true
                }
            };

            process.Start();
            process.WaitForExit(TimeSpan.FromMinutes(5)); // Set a timeout of 5 minutes

            if (process.ExitCode != 0)
            {
                _logger.LogError($"Failed to add website '{siteName}' to directory '{directoryPath}'. Exit code: {process.ExitCode}");
                return false;
            }
        }
        catch (Exception ex)
        {
            _logger.LogError($"An error occurred while adding website '{siteName}' to directory '{directoryPath}': {ex.Message}");
            return false;
        }

        _logger.LogInformation($"Successfully added website '{siteName}' to directory '{directoryPath}'.");
        return true;
