// Health check function with concurrency limits and retry logic
function healthCheck(hostname) {
  return new Promise((resolve, reject) => {
    const command = `ping -c 1 ${hostname}`; // Replace with appropriate command for your OS if needed
    const exec = bluebird.promisify(child_process.exec);

    exec(command)
      .then(result => {
        // Check exit status (0 means success) and response data (contains IP address)
        if (result.status === 0 && result.stdout.match(/[0-9]{1,3}\.[0-9]{1,3}\.[0-9]{1,3}\.[0-9]{1,3}/)) {
          resolve(result.stdout.split(' ')[3]); // Return IP address as u_char array
        } else {
          reject(new Error(`Health check failed: ${result.stderr}`));
        }
      })
      .catch(error => {
        console.error(`Error during health check: ${error}`);
        reject(error);
      });
  });
}

// Health check route with authorization, rate limiting, and concurrency control
