  const authorized = req.user.hasPermission('HEALTH_CHECK'); // Assuming user object is available in the request

  if (!authorized) {
    return res.status(403).send('Forbidden');
  }

  const hostname = req.query.hostname;
  if (!hostname) {
    return res.status(400).send('Missing required parameter: hostname');
  }

  // Store the current health check in Redis for retry logic and performance monitoring
  redisClient.set(`health-check-${req.user.id}-${hostname}`, Date.now(), (err) => {
    if (err) {
      console.error(`Error storing health check data: ${err}`);
      return res.status(500).send('Internal Server Error');
    }

    // Limit concurrent health checks per user and execute the health check function
    healthCheck(hostname)
      .then(ip => {
        // Handle successful health check response
        res.json({ success: true, ip });
      })
      .catch(error => {
        // Handle failed health check or timeouts
        if (error.message.includes('ECONNREFUSED')) {
          // Service outage - return error to the user and retry later
          res.json({ success: false, message: 'Service unavailable' });
        } else {
          // Other errors - return error to the user without retries
          res.status(500).json({ success: false, message: error.message });
        }
      });
  });
});

