```cpp
#include <iostream>
#include <vector>
#include <boost/random.hpp>
#include <boost/thread/tss_mutex.hpp>
#include <memory>

constexpr size_t MAX_RECORDS = 10000;

struct Record {
    int id;
    long offset;
    std::shared_ptr<Record> next;
};

class RecordManager {
public:
    RecordManager(int min, int max, unsigned seed) : rng_(seed), min_(min), max_(max), records_(MAX_RECORDS) {}

    std::unique_ptr<Record> add() {
        boost::mutex::scoped_lock lock(records_mutex_);
        if (current_ == records_.size()) {
            // Handle memory pressure here, e.g., by evicting older records or limiting the rate of new additions
            std::cerr << "Memory pressure! Consider adding a strategy to handle this." << std::endl;
            return nullptr;
        }

        auto record = std::make_unique<Record>();
        record->id = rng_(rng_) % (max_ - min_) + min_;
        record->offset = current_;
        record->next.reset(records_[current_].next.get());
        records_[current_] = std::move(record);
        ++current_;
        return record;
    }

    void remove(int id) {
        boost::mutex::scoped_lock lock(records_mutex_);
        auto current = &records_[0];
        for (size_t i = 0; i < current_; ++i, current = current->next.get()) {
            if (current->id == id) {
                current->next = std::move(current->next);
                --current_;
                break;
            }
        }
    }

    void keys(std::vector<int>& keys) const {
        boost::mutex::scoped_lock lock(records_mutex_);
        auto current = &records_[0];
        for (size_t i = 0; i < current_; ++i, current = current->next.get()) {
            keys.push_back(current->id);
        }
    }

    ~RecordManager() {
        boost::mutex::scoped_lock lock(records_mutex_);
        for (auto record : records_) {
            delete record;
        }
    }

private:
    boost::random::mt19937 rng_;
    int min_, max_;
    size_t current_ = 0;
    std::vector<std::unique_ptr<Record>> records_;
    mutable boost::thread_specific_mutex records_mutex_;
};

int main() {
    RecordManager manager(1, 10000, 42);
    std::vector<int> keys;

    for (size_t i = 0; i < 10; ++i) {
        auto record = manager.add();
        if (record) {
            keys.push_back(record->id);
        }
    }

    manager.keys(keys);

    for (auto id : keys) {
        manager.remove(id);
    }

    return 0;
}
```

