#include <openssl/aes.h>
#include <iostream>

const EVP_CIPHER* getTripleDES() {
    return EVP_aes_128_cbc(); // Triple DES can be implemented using AES-192 or AES-256 in CBC mode with three keys.
}

std::string encrypt(const std::string& plaintext, const std::string& key, const std::string& iv) {
    EVP_CIPHER_CTX ctx;
    int len = AES_BLOCKSIZE * ((plaintext.size() + AES_BLOCKSIZE - 1) / AES_BLOCKSIZE);
    unsigned char* ciphertext = new unsigned char[len];

    EVP_EncryptInit(&ctx, getTripleDES(), nullptr, reinterpret_cast<const unsigned char*>(key.c_str()), reinterpret_cast<const unsigned char*>(iv.c_str()));
    EVP_EncryptUpdate(&ctx, ciphertext, &len, reinterpret_cast<const unsigned char*>(plaintext.c_str()), plaintext.size());
    EVP_EncryptFinal_ex(&ctx, ciphertext + len, &len);

    std::string encrypted(reinterpret_cast<char*>(ciphertext), len);
    delete[] ciphertext;
    return Base64Encode(encrypted);
}

std::string decrypt(const std::string& base64Encoded, const std::string& key, const std::string& iv) {
    std::string encrypted = Base64Decode(base64Encoded);
    unsigned char* ciphertext = new unsigned char[encrypted.size()];
    std::copy(encrypted.begin(), encrypted.end(), ciphertext);

    EVP_CIPHER_CTX ctx;
    int len = AES_BLOCKSIZE * ((ciphertext.size() + AES_BLOCKSIZE - 1) / AES_BLOCKSIZE);
    unsigned char* plaintext = new unsigned char[len];

    EVP_DecryptInit(&ctx, getTripleDES(), nullptr, reinterpret_cast<const unsigned char*>(key.c_str()), reinterpret_cast<const unsigned char*>(iv.c_str()));
    EVP_DecryptUpdate(&ctx, plaintext, &len, ciphertext, ciphertext + encrypted.size());
    EVP_DecryptFinal_ex(&ctx, plaintext + len, &len);

    std::string decrypted(reinterpret_cast<char*>(plaintext), len);
    delete[] ciphertext;
    delete[] plaintext;
    return decrypted;
}
```

