[' Here's a simplified version of the requested function in C, using malloc, calloc, and realloc for memory management, and gsl's `gsl_rng` for random number generation. This code does not include a custom memory pool, logging, or detailed error handling, but it serves as a starting point for your project.

```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <gsl/gsl_rng.h>

typedef struct Record {
    char substring[MAX_LENGTH];
    int value;
    size_t buffer_size;
    char *buffer;
} Record;

Record* create_record_array(int n, const char *input, int min_value, int max_value, size_t buffer_size) {
    Record *records = (Record *)malloc(n * sizeof(Record));
    if (!records) {
        fprintf(stderr, "Memory allocation failed\n");
        return NULL;
    }

    gsl_rng *r = gsl_rng_alloc(gsl_rng_mt19937);

    for (int i = 0; i < n; ++i) {
        size_t substring_length = rand() % (strlen(input) + 1);
        strncpy(records[i].substring, input, substring_length);
        records[i].substring[substring_length] = '\0';

        records[i].value = min_value + rand() % (max_value - min_value + 1);

        records[i].buffer_size = buffer_size;
        records[i].buffer = calloc(records[i].buffer_size, sizeof(char));
        if (!records[i].buffer) {
            fprintf(stderr, "Memory allocation failed\n");
            for (int j = 0; j < i; ++j) free(records[j].buffer);
            free(records);
            return NULL;
        }
    }

    gsl_rng_free(r);
    return records;
}

void free_record_array(Record *records, int n) {
    for (int i = 0; i < n; ++i) {
        free(records[i].buffer);
    }
    free(records);
}
```

