void read_and_allocate(FILE* file, size_t** doubles, size_t** strings, Data*** datas, size_t* count) {
    size_t current = 0;
    double temp_double;
    char temp_char[256];

    while (fscanf(file, "%lf", &temp_double) == 1) {
        (*doubles)[current] = malloc(sizeof(double));
        if ((*doubles)[current] == NULL) {
            fprintf(stderr, "Out of memory\n");
            exit(EXIT_FAILURE);
        }
        (*doubles)[current++] = &temp_double;
    }
    *doubles = realloc(*doubles, current * sizeof(double*));
    *count = current;

    current = 0;
    while (fgets(temp_char, sizeof(temp_char), file) != NULL) {
        size_t len = strlen(temp_char);
        if (len > 255 || temp_char[len - 1] != '\n') {
            fprintf(stderr, "String too long\n");
            exit(EXIT_FAILURE);
        }
        (*strings)[current] = malloc(len + 1);
        if ((*strings)[current] == NULL) {
            fprintf(stderr, "Out of memory\n");
            exit(EXIT_FAILURE);
        }
        memcpy((*strings)[current], temp_char, len + 1);
        (*strings)[current++][len] = '\0';
    }
    *strings = realloc(*strings, current * sizeof(char*));
    *count += current;

    current = 0;
    Data temp_data;
    while (fscanf(file, "%lf%s%p", &temp_data.d, temp_data.str, &temp_data.data) == 3) {
        temp_data.data = malloc(sizeof(Data));
        if (temp_data.data == NULL) {
            fprintf(stderr, "Out of memory\n");
            exit(EXIT_FAILURE);
        }
        memcpy(temp_data.data, &temp_data, sizeof(Data));
        (*datas)[current++] = temp_data.data;
    }
    *datas = realloc(*datas, current * sizeof(Data*));
    *count += current;
}

void free_memory(size_t* doubles, size_t* strings, Data** datas, size_t count) {
    for (size_t i = 0; i < count; ++i) {
        if (doubles[i]) free(doubles[i]);
        if (strings[i]) free(strings[i]);
        if (datas[i]) free(datas[i]);
    }
    free(doubles);
    free(strings);
    free(datas);
}

void transform_data(size_t* doubles, size_t* strings, Data** datas, size_t count) {
    for (size_t i = 0; i < count; ++i) {
        Data* data = datas[i];
        data->d *= i + 1;
    }
}
