#include <forward_list>
#include <string>
#include <iostream>
#include <cstdlib>
#include <cstring>
#include <system_error>

constexpr size_t MAX_LENGTH = 100;

struct Node {
    std::string data;
    Node* next;

    Node(const std::string& str) : data(str), next(nullptr) {
        if (data.length() > MAX_LENGTH) {
            data.resize(MAX_LENGTH);
            data.back() = '\0'; // null-terminate the string
        }
    }
};

class ForwardList {
public:
    void insertAfterUniqueString(const std::string& target, const std::string& newData) {
        Node* current = head.next;
        Node* previous = &head;

        while (current != nullptr) {
            if (current->data == target) {
                Node* newNode = new Node(newData);
                previous->next = newNode;
                newNode->next = current;
                break;
            }
            previous = current;
            current = current->next;
        }

        if (current == nullptr) { // target not found, append to the end
            Node* newNode = new Node(newData);
            previous->next = newNode;
        }
    }

private:
    Node head{""};
};
```

This code defines a `ForwardList` class that manages a forward list of nodes, each containing a string. The `insertAfterUniqueString` function searches for the target string in the list and inserts the new data after it if found. If not found, it appends the new data to the end of the list. Each node's string content is null-terminated, and excess length is truncated if necessary.

