        if ($length < 4) {
            throw new Exception("The specified length must be greater than or equal to 4.");
        }

        $randomString = '';
        for ($i = 0; $i < $length; $i++) {
            $category = array_rand([
                'uppercase' => 1,
                'lowercase' => 1,
                'digits' => rand(1, floor($length / 4)),
                'special' => rand(0, floor($length / 8))
