            try {
                if ($algorithm === 'bcrypt') {
                    $salt = $this->generateSalt($this->maxSaltAttempts);
                    $hashedString = password_hash($randomString . $salt, PASSWORD_BCRYPT);
                } else {
                    $hashedString = hash($algorithm, $randomString);
                }
                break;
            } catch (Exception $e) {
                // Log the error and continue with the next algorithm.
                echo "Error while hashing with algorithm: {$algorithm}.\n";
            }
        }

        return [$randomString, $hashedString];
    }

    private function getRandomCharacterFromCategory($category) {
        if (is_null($charset)) {
            return $this->charset[$category][array_rand($this->charset[$category])];
        }

        return $charset[$category][array_rand($charset[$category])];
    }

    private function generateSalt($attempts) {
        $salt = '';
        for ($i = 0; $i < $this->saltLength; $i++) {
            $salt .= $this->getRandomCharacterFromCategory('digits');
        }

        for ($i = 0; $i < $attempts; $i++) {
            if (ctype_alnum($salt)) {
                return $salt;
            }
            $salt = bin2hex(random_bytes($this->saltLength));
        }

        throw new Exception("Failed to generate a valid salt after {$attempts} attempts.");
    }
}
