[" Here's a C++ implementation of the requested doubly linked list with the specified features. Note that this code is not optimized for performance or memory usage in all cases, but it provides a good starting point for further optimization.

```cpp
#include <iostream>
#include <vector>
#include <string>
#include <cstdlib>
#include <ctime>
#include <mutex>

const int MAX_STRING_LENGTH = 100;

struct Node {
    float data;
    std::string str;
    Node* prev;
    Node* next;
    int key;
    long offset;
};

std::vector<Node> nodes;
std::vector<long> offsets;
std::vector<int> keys;
std::mutex mtx;
std::mt19937 rng(0); // Seed with 0 for deterministic behavior

void init(int n, int min_val, int max_val) {
    nodes.reserve(n);
    offsets.resize(n);
    keys.resize(n);

    std::uniform_int_distribution<int> dist(min_val, max_val);

    for (auto& node : nodes) {
        node.data = 0;
        node.str.clear();
        node.prev = nullptr;
        node.next = nullptr;
        node.key = dist(rng);
        node.offset = -1;
    }
}

Node* create_node() {
    Node* new_node = new Node{};
    nodes.push_back(*new_node);
    return &nodes.back();
}

void delete_node(Node* node) {
    auto it = std::find(nodes.begin(), nodes.end(), *node);
    if (it != nodes.end()) {
        delete it;
        nodes.erase(it);
    }
}

void insert_after(Node* prev, Node* new_node) {
    mtx.lock();
    if (prev->next == nullptr) {
        prev->next = new_node;
        new_node->prev = prev;
    } else {
        auto next = prev->next;
        new_node->prev = prev;
        prev->next = new_node;
        next->prev = new_node;
        new_node->next = next;
    }
    mtx.unlock();
}

void delete_node(Node* node) {
    mtx.lock();
    if (node->prev != nullptr) {
        auto prev = node->prev;
        prev->next = node->next;
        if (node->next != nullptr) {
            node->next->prev = prev;
        }
    } else {
        auto first = &nodes[0];
        while (first->next != node) {
            first = first->next;
        }
        first->next = node->next;
    }
    mtx.unlock();
}

void traverse(Node* start, std::function<void(Node&)> func) {
    mtx.lock();
    Node* current = start;
    while (current != nullptr) {
        func(*current);
        current = current->next;
    }
    mtx.unlock();
}

void log_event(int level, const std::string& message) {
    // Implement logging mechanism here
}
```

