record* initialize_data_structures(size_t chunk_size, size_t max_memory_usage, size_t *offsets, size_t *keys, bool validate_memory) {
    if (chunk_size <= 0 || max_memory_usage == 0) {
        fprintf(stderr, "Invalid parameters: chunk_size and max_memory_usage must be positive.\n");
        return NULL;
    }

    size_t total_records = *keys + 1; // Account for the last record not being initialized yet
    size_t memory_usage = total_records * sizeof(record);

    if (memory_usage > max_memory_usage) {
        fprintf(stderr, "Insufficient memory to allocate data structures.\n");
        return NULL;
    }

    record* records = malloc(chunk_size * sizeof(record));
    if (!records) {
        perror("Memory allocation failed.");
        return NULL;
    }

    size_t allocated_memory = chunk_size * sizeof(record);

    for (size_t i = 0; i < total_records && allocated_memory <= max_memory_usage; ++i) {
        records[i].value = generate_random(1, 100);
        offsets[i] = i * 5;
        keys[i] = i + 10;

        if (validate_memory && i > 0 && offsets[i - 1] + sizeof(record) >= allocated_memory) {
            fprintf(stderr, "Memory overflow detected.\n");
            free(records);
            return NULL;
        }

        allocated_memory += sizeof(record);
    }

    record* result = realloc(records, memory_usage);
    if (!result) {
        perror("Memory reallocation failed.");
        free(records);
        return NULL;
    }

    return result;
}
