const sanitizeAttributeValue = (value) => {
  return value.replace(/[<>&'"]/g, (char) => {
    switch (char) {
      case '<': return '&lt;';
      case '>': return '&gt;';
      case "'": return '&#039;';
      case '"': return '&quot;';
      default: return char;
    }
  });
}

const fetchExternalResource = async (url, fallbackUrl) => {
  try {
    const response = await fetch(url);
    if (!response.ok) throw new Error(`Failed to load external resource: ${url}`);
    return await response.text();
  } catch (error) {
    console.warn(`Error loading external resource "${url}". Falling back to "${fallbackUrl}"...`);
    return fetchExternalResource(fallbackUrl, fallbackUrl);
  }
}

const generateLinks = (links, dependencies = new Map()) => {
  let html = '';

  links.forEach((link) => {
    const { id, rel, href, media, as, attributes, priority, conditionalInclude, fallbackUrl, externalResources } = link;

    if (!conditionalInclude || (conditionalInclude && conditionalInclude())) {
      let content = '';

      if (externalResources) {
        externalResources.forEach(async (url) => {
          content += await fetchExternalResource(url, fallbackUrl);
        });
      }

      html += `<link ${Object.keys(attributes || {}).map((key) => `${key}="${sanitizeAttributeValue(attributes[key])}"`).join(' ')} rel="${rel}" href="${sanitizeAttributeValue(href)}" media="${media}" as="${as}" ${priority ? `priority="${priority}"` : ''}>\n`;

      if (dependencies.has(id)) {
        dependencies.get(id).forEach((dep) => {
          if (!dependencies.has(dep)) {
            dependencies.set(dep, [id]);
            generateLinks(links.filter((l) => l.id === dep), dependencies);
          }
        });
      }
    }
  });

