```c
#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <time.h>

typedef struct Record {
    long offset;
    int key;
    float value;
} Record;

struct MemoryPool {
    void* data;
    size_t capacity;
    size_t allocated;
};

struct MemoryPool* create_memory_pool(size_t n, size_t m, size_t p) {
    const size_t max_size = 1024 * 1024; // Max memory limit (1MB)
    void* data = malloc(n * sizeof(long) + m * sizeof(int) + p * sizeof(float));

    if (!data || (sizeof(long) + sizeof(int) + sizeof(float)) * (n + m + p) > max_size) {
        free(data);
        return NULL;
    }

    struct MemoryPool* pool = malloc(sizeof(struct MemoryPool));
    if (!pool) {
        free(data);
        return NULL;
    }

    pool->data = data;
    pool->capacity = (n + m + p) * (sizeof(long) + sizeof(int) + sizeof(float));
    pool->allocated = 0;

    return pool;
}

void init_records(struct MemoryPool* pool, size_t count, Record* records) {
    for (size_t i = 0; i < count; ++i) {
        records[i].offset = i;
        records[i].key = i;
        records[i].value = rand() % 2 ? -1.0f + (float)(rand() / RAND_MAX) : 1.0f - (float)(rand() / RAND_MAX);
    }
}

pthread_mutex_t lock;
void set_offset_and_key(struct MemoryPool* pool, size_t index, Record* record) {
    pthread_mutex_lock(&lock);
    record->offset = index;
    record->key = index;
    pthread_mutex_unlock(&lock);
}

float get_random_value() {
    static const float cache[1024]; // Cache for frequently requested random numbers
    static size_t cache_index = 0;

    if (cache_index < 1024) {
        cache[cache_index++] = rand() % 2 ? -1.0f + (float)(rand() / RAND_MAX) : 1.0f - (float)(rand() / RAND_MAX);
    }

    return cache[cache_index++ % 1024];
}

void validate_memory(struct MemoryPool* pool) {
    if (pool->allocated > pool->capacity) {
        printf("Memory usage exceeded the limit\n");
    }
}

void destroy_memory_pool(struct MemoryPool* pool) {
    free(pool->data);
    free(pool);
}
```

