#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <sys/types.h>
#include <sys/stat.h>
#include <fcntl.h>
#include <unistd.h>
#include <pthread.h>

typedef struct {
    char* content;
    enum { INFO, WARNING, ERROR } category;
} Event;

void sort_events(Event** events, size_t count) {
    qsort(events, count, sizeof(Event*), compare_events);
}

int compare_events(const void* a, const void* b) {
    return strcmp(((Event*)a)->content, ((Event*)b)->content);
}

void* process_log_chunk(void* arg) {
    char buffer[4096];
    ssize_t bytes_read;
    FILE* file = (FILE*)arg;
    Event events[128]; // Adjust the size based on your needs
    size_t event_count = 0;

    while ((bytes_read = getline(&buffer, sizeof(buffer), file)) != -1) {
        if (strstr(buffer, "ERROR_KEYWORD")) {
            events[event_count].content = strdup(buffer);
            events[event_count].category = ERROR;
            event_count++;
            continue;
        }
        if (strstr(buffer, "WARNING_KEYWORD")) {
            events[event_count].content = strdup(buffer);
            events[event_count].category = WARNING;
            event_count++;
            continue;
        }
        events[event_count].content = strdup(buffer);
        events[event_count].category = INFO;
        event_count++;
    }

    if (event_count > 0) {
        Event* result = malloc(event_count * sizeof(Event));
        memcpy(result, events, event_count * sizeof(Event));
        free(events); // Free the local buffer to avoid memory leaks
        pthread_exit(result);
    }

    pthread_exit(NULL);
}

int process_log_file(const char* path) {
    FILE* file = fopen(path, "r");
    if (!file) return -1; // Handle error and return appropriate code

    pthread_t threads[4]; // Adjust the number of threads based on your needs
    size_t total_event_count = 0;
    Event* events = NULL;

    for (size_t i = 0; i < sizeof(threads) / sizeof(pthread_t); ++i) {
        if (fseek(file, ftell(file), SEEK_SET)) { // Seek to the start of the file for each thread
            fclose(file);
            return -1; // Handle error and return appropriate code
        }

        size_t bytes_read = fread(buffer, 1, sizeof(buffer), file);
        if (pthread_create(&threads[i], NULL, process_log_chunk, file)) {
            return -1; // Handle error and return appropriate code
        }

        total_event_count += bytes_read / sizeof(buffer[0]);
    }

    for (size_t i = 0; i < sizeof(threads) / sizeof(pthread_t); ++i) {
        Event* result;
        if (pthread_join(threads[i], (void**)&result)) {
            return -1; // Handle error and return appropriate code
        }

        if (events) {
            size_t event_count = total_event_count - bytes_read / sizeof(buffer[0]);
            Event* merged = realloc(events, (event_count + total_event_count) * sizeof(Event));
            if (!merged) return -1; // Handle error and return appropriate code

            memcpy(merged + event_count, result, total_event_count * sizeof(Event));
            free(result);
        } else {
            events = result;
        }
    }

    sort_events(events, total_event_count);

    printf("INFO: %ld\n", count_events(events, INFO));
    printf("WARNING: %ld\n", count_events(events, WARNING));
    printf("ERROR: %ld\n", count_events(events, ERROR));

    free(events);
    fclose(file);
    return 0;
}

size_t count_events(Event* events, enum { INFO, WARNING, ERROR } category) {
    size_t count = 0;
    for (size_t i = 0; i < event_count; ++i) {
        if (events[i].category == category) ++count;
    }
    return count;
}
```

