```cpp
#include <iostream>
#include <string>
#include <vector>
#include <boost/filesystem.hpp>
#include <boost/thread/mutex.hpp>
#include <cstdio>
#include <cstring>

constexpr size_t MAX_FILENAME_LENGTH = 255;
constexpr char DEFAULT_FILE_EXTENSION[] = ".txt";

class UniqueFilenameGenerator {
public:
    UniqueFilenameGenerator(const std::string& baseDir) : _baseDir(baseDir), _mutex(), _counter(0) {}

    std::string generateUniqueFilename(const std::string& originalFilename, size_t maxLength, const char* defaultExtension = DEFAULT_FILE_EXTENSION) {
        if (originalFilename.length() > MAX_FILENAME_LENGTH - maxLength) {
            return "";
        }

        boost::filesystem::path path(_baseDir);
        path /= originalFilename;

        std::string newFilename(originalFilename);
        size_t suffixStart = newFilename.length();

        // Synchronize access to shared resources
        std::unique_lock<std::mutex> lock(_mutex);

        int counter = _counter++;
        while (boost::filesystem::exists(path.string() + std::to_string(counter) + defaultExtension)) {
            counter++;
        }

        // Format the numeric suffix based on the length of the original filename and the first character of the filename
        char suffix[10];
        snprintf(suffix, sizeof(suffix), "%0*d", static_cast<int>(suffixStart), counter);
        newFilename.insert(suffixStart, suffix, suffix + strlen(suffix));
        newFilename += defaultExtension;

        lock.unlock();
        return newFilename;
    }

private:
    std::string _baseDir;
    boost::mutex _mutex;
    int _counter;
};

int main() {
    UniqueFilenameGenerator gen("/path/to/your/directory");

    // Test concurrent calls
    std::vector<std::thread> threads;
    for (size_t i = 0; i < 10; ++i) {
        threads.emplace_back([&]() { gen.generateUniqueFilename("longfilename", 20); });
    }
    for (auto& thread : threads) {
        thread.join();
    }

    return 0;
}
