The example in the `main()` function demonstrates how to use the `UniqueFilenameGenerator` class to generate unique filenames concurrently without introducing race conditions.']

[' Here's a simplified C++ implementation using a `std::unordered_map` for efficient lookup of connections, `boost::lockfree::queue` for concurrent access, and `std::atomic` for thread-safe updates. The code includes basic support for connection management, logging, and health monitoring.

```cpp
#include <iostream>
#include <unordered_map>
#include <chrono>
#include <boost/lockfree/queue.hpp>
#include <atomic>
#include <memory>

struct Connection {
    int id;
    enum class State { IDLE, ESTABLISHED, CLOSED } state;
    std::chrono::steady_clock::time_point establishment_ts;
    std::chrono::steady_clock::time_point last_activity_ts;
    int error_count;

    Connection(int id) : id(id), state(State::IDLE), establishment_ts(std::chrono::steady_clock::now()), last_activity_ts(establishment_ts) {}
};

struct LoggingSystem {
    void log_connection_establishment(Connection* conn) const { std::cout << "Established connection: " << conn->id << std::endl; }
    void log_connection_close(Connection* conn) const { std::cout << "Closed connection: " << conn->id << std::endl; }
};

class ConnectionManager {
public:
    ConnectionManager(int max_connections, int inactivity_threshold_minutes, int error_threshold, LoggingSystem& logging_system)
        : max_connections_(max_connections), inactivity_threshold_(inactivity_threshold_minutes * 60), error_threshold_(error_threshold),
          logging_system_(logging_system), connection_queue_(max_connections_) {}

    Connection* establish_connection(int id) {
        auto it = connections_.find(id);
        if (it != connections_.end()) return it->second.get();

        std::unique_ptr<Connection> conn(new Connection(id));
        if (!connection_queue_.push(conn.get())) {
            std::cerr << "Failed to allocate memory for connection queue" << std::endl;
            return nullptr;
        }
        connections_[id] = std::move(conn);
        return connections_[id].get();
    }

    void close_connection(Connection* conn) {
        auto it = connections_.find(conn->id);
        if (it == connections_.end()) {
            std::cerr << "Invalid connection ID" << std::endl;
            return;
        }

        it->second->state = Connection::State::CLOSED;
        it->second->last_activity_ts = std::chrono::steady_clock::now();
        logging_system_.log_connection_close(it->second.get());
        connection_queue_.push(it->second.release());
        connections_.erase(it);
    }

    Connection* query_connection(int id) {
        auto it = connections_.find(id);
        if (it == connections_.end()) return nullptr;
        it->second->last_activity_ts = std::chrono::steady_clock::now();
        return it->second.get();
    }

    void monitor() {
        auto now = std::chrono::steady_clock::now();
        for (auto& [id, conn] : connections_) {
            if (conn->state == Connection::State::ESTABLISHED &&
                (std::chrono::duration_cast<std::chrono::minutes>(now - conn->last_activity_ts).count() > inactivity_threshold_ ||
                    conn->error_count >= error_threshold_)) {
                close_connection(conn.get());
            }
        }
    }

private:
    int max_connections_;
    int inactivity_threshold_;
    int error_threshold_;
    LoggingSystem& logging_system_;
    boost::lockfree::queue<Connection*> connection_queue_;
    std::unordered_map<int, std::unique_ptr<Connection>> connections_;
};
```

This implementation uses a lock-free queue for concurrent access and atomic operations to ensure thread safety without introducing performance bottlenecks. The `ConnectionManager` class handles connection establishment, closure, querying, monitoring, and logging. It also supports an optional health monitoring feature that automatically closes unhealthy connections based on user-defined thresholds for inactivity and error rates.']

