#include <stdio.h>
#include <stdlib.h>
#include <time.h>

typedef struct {
    int timestamp; // optional, can be replaced with long if needed
    int unique_id; // required
    char* message; // required
} LogEntry;

int create_log_entries(LogEntry** log_entries, size_t num_entries, size_t timestamp_size, size_t message_size) {
    size_t total_size = sizeof(LogEntry) * num_entries + (timestamp_size * num_entries) + (message_size * num_entries);

    if (total_size > (size_t)LONG_MAX || total_size > (size_t)RLIM_INFINITY * RLIM_RSS) {
        fprintf(stderr, "Error: Allocating memory for %zu bytes exceeds system limits.\n", total_size);
        return -1;
    }

    *log_entries = (LogEntry*)calloc(num_entries, sizeof(LogEntry));
    if (*log_entries == NULL) {
        fprintf(stderr, "Error: Failed to allocate memory for log entries.\n");
        return -1;
    }

    char* timestamp_buffer = (char*)malloc(timestamp_size * num_entries);
    if (timestamp_buffer == NULL) {
        free(*log_entries);
        fprintf(stderr, "Error: Failed to allocate memory for timestamps.\n");
        return -1;
    }

    char* message_buffer = (char*)malloc(message_size * num_entries);
    if (message_buffer == NULL) {
        free(timestamp_buffer);
        free(*log_entries);
        fprintf(stderr, "Error: Failed to allocate memory for messages.\n");
        return -1;
    }

    for (size_t i = 0; i < num_entries; ++i) {
        LogEntry* entry = &((*log_entries)[i]);
        entry->unique_id = i + 1; // assign unique id to each log entry

        if (timestamp_size > 0) {
            entry->timestamp = *(long*)(timestamp_buffer + (i * timestamp_size));
        }

        size_t message_length = rand() % message_size + 1; // generate random message length within the specified range
        memcpy((*log_entries)[i].message, message_buffer + (i * message_size), message_length);
        (*log_entries)[i].message[message_length] = '\0'; // null-terminate the message
    }

    free(timestamp_buffer);
    free(message_buffer);

    return 0;
}
```

