#include <unistd.h>

typedef struct {
    int value;
} record;

int process_file(const char *filename, size_t offset_size, size_t key_size, size_t record_size) {
    FILE *file = fopen(filename, "r");
    if (!file) {
        perror("Error opening file");
        return 0;
    }

    long *offsets = malloc(offset_size * sizeof(long));
    int *keys = malloc(key_size * sizeof(int));
    record *records = malloc(record_size * sizeof(record));
    size_t line_count = 0;
    size_t valid_line_count = 0;
    char **lines = NULL;
    size_t capacity = 0;
    size_t current_index = 0;

    srand(time(NULL));

    for (size_t i = 0; i < record_size; ++i) {
        records[i].value = rand() % INT_MAX;
    }

    while ((capacity == 0 || lines[capacity - 1]) && (lines = realloc(lines, capacity ? capacity * 2 : 16))) {
        size_t len = getline(&lines[capacity], sizeof(lines[capacity]) - 1, file);
        if (len > 0) {
            lines[capacity][len - 1] = '\0';
            ++capacity;
        }
    }

    for (size_t i = 0; i < capacity; ++i) {
        char **fields = NULL;
        char *token = strtok(lines[i], ",");

        if (!token || sscanf(token, "%ld", &offsets[current_index]) != 1) {
            fprintf(stderr, "Warning: Invalid line format at line %zu\n", i + 1);
            continue;
        }

        current_index = offsets[current_index];

        if (current_index >= key_size || current_index < 0) {
            fprintf(stderr, "Warning: Out of bounds access at line %zu\n", i + 1);
            continue;
        }

        token = strtok(NULL, ",");
        if (!token || sscanf(token, "%d", &keys[current_index]) != 1) {
            fprintf(stderr, "Warning: Invalid line format at line %zu\n", i + 1);
            continue;
        }

        token = strtok(NULL, ",");
        if (!token || sscanf(token, "%d", &records[current_index].value) != 1) {
            fprintf(stderr, "Warning: Invalid line format at line %zu\n", i + 1);
            continue;
        }

        if (current_index > 0 && current_index < key_size - 1) {
            int last = records[current_index - 2].value;
            int second_last = records[current_index - 1].value;
            double average = ((double)second_last + (double)last) / 2.0;
            records[current_index].value = (int)average;
        }

        ++valid_line_count;
    }

    fclose(file);
    free(lines);
    for (size_t i = 0; i <= current_index; ++i) {
        printf("%d,%d,%d\n", keys[i], records[i].value, records[current_index].value);
    }

    free(offsets);
    free(keys);
    free(records);

    return valid_line_count;
}
```

