[' Here's a simplified C++ example that addresses some of the requirements you've mentioned. Note that this is a basic implementation and may need further optimization for specific use cases or resource-constrained environments.

```cpp
#include <iostream>
#include <fstream>
#include <sstream>
#include <vector>
#include <cstdlib>
#include <ctime>
#include <stdexcept>
#include <string>

struct Record {
    int value;
    std::string text;
    double average;
};

int read_and_process(const std::string& filename, std::vector<Record>& records) {
    int line_count = 0;
    std::ifstream file(filename);
    if (!file.is_open()) {
        throw std::runtime_error("Could not open file: " + filename);
    }

    std::string line;
    while (std::getline(file, line)) {
        line_count++;
        std::istringstream iss(line);
        Record record;
        if (!(iss >> record.value >> record.text)) {
            std::cerr << "Error processing line " << line_count << ": Invalid format" << std::endl;
            continue;
        }

        record.average = static_cast<double>(record.value) / 2; // Assuming two fields per line
        if (record.text.empty()) {
            std::cerr << "Error processing line " << line_count << ": Empty text field" << std::endl;
            continue;
        }

        record.text += ", average: " + std::to_string(record.average);
        records.push_back(record);
    }

    file.close();
    return line_count - records.size(); // Return the number of errors
}

void free_records(std::vector<Record>& records) {
    for (auto& record : records) {
        delete[] const_cast<char*>(record.text.c_str());
    }
    records.clear();
}

int main() {
    srand(time(nullptr));
    std::vector<Record> records;
    int error_count = read_and_process("input.txt", records);
    if (error_count > 0) {
        std::cerr << "Encountered errors while processing: " << error_count << std::endl;
    }

    for (const auto& record : records) {
        std::cout << record.value << ", \"" << record.text << "\", average: " << record.average << std::endl;
    }

    free_records(records);
    return 0;
}
```

