[' Here is a C function that meets your requirements. I've used `gmp` library for handling large integers and `getline` from `getopt` for reading input lines. This code does not block the main thread as it uses non-blocking I/O for reading input.

```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <getopt.h>
#include <gmp.h>
#include <unistd.h>
#include <sys/types.h>
#include <fcntl.h>
#include <sys/stat.h>
#include <errno.h>

typedef enum { DECIMAL, HEXADECIMAL, BINARY } base_t;

struct number {
    base_t base;
    size_t len;
    char *str;
    gmp_uint64_t u;
    gmp_int64_t s;
};

void free_number(struct number *n) {
    if (n->base == DECIMAL || n->base == BINARY)
        free(n->str);
    free(n);
}

struct number *parse_number(const char *str, base_t base) {
    struct number *n = malloc(sizeof(*n));
    n->base = base;
    if (base == DECIMAL) {
        gmp_set_str(n->u, str, 10);
        n->s = 0;
    } else if (base == BINARY) {
        size_t len = strlen(str);
        n->len = len / 2 + (len % 2 != 0);
        n->str = malloc((n->len + 1) * sizeof(*(n->str)));
        for (size_t i = 0; i < len; ++i) {
            if (str[i] == '1')
                n->str[n->len - i - 1] = '1';
            else if (str[i] != '0') {
                free_number(n);
                return NULL;
            }
        }
        n->str[n->len] = '\0';
        gmp_init2(n->u, n->len * sizeof(*(n->u)));
        for (size_t i = 0; i < n->len; ++i) {
            if (n->str[i] == '1')
                gmp_setbit(n->u, n->len - i - 1);
        }
        n->s = 0;
    } else if (base == HEXADECIMAL) {
        size_t len = strlen(str);
        if (len & 1) {
            free_number(n);
            return NULL;
        }
        n->len = len / 2;
        n->str = malloc((n->len + 1) * sizeof(*(n->str)));
        for (size_t i = 0; i < len; ++i) {
            if ((str[i] >= '0' && str[i] <= '9') ||
                (str[i] >= 'a' && str[i] <= 'f') ||
                (str[i] >= 'A' && str[i] <= 'F')) {
                n->str[n->len - i / 2 - 1] = str[i];
            } else {
                free_number(n);
                return NULL;
            }
        }
        n->str[n->len] = '\0';
        gmp_init2(n->u, n->len * sizeof(*(n->u)));
        for (size_t i = 0; i < len; ++i) {
            if (str[i] >= 'a' && str[i] <= 'f')
                gmp_setbit(n->u, i / 2, 1 + (str[i] - 'a'));
            else if (str[i] >= 'A' && str[i] <= 'F')
                gmp_setbit(n->u, i / 2, 1 + (str[i] - 'A'));
            else
                gmp_setbit(n->u, i / 2, str[i] - '0');
        }
        n->s = 0;
    }
    return n;
}

void free_numbers(struct number **arr, size_t len) {
    for (size_t i = 0; i < len; ++i)
        free_number(arr[i]);
    free(arr);
}

int read_line(FILE *stream, char **lineptr, size_t *n, size_t bufsize) {
    char *buf = realloc(*lineptr, bufsize);
    if (!buf)
        return -1;
    *lineptr = buf;
    ssize_t len = getline(lineptr, &bufsize, stream);
    if (len == -1)
        return -1;
    (*n) += len;
    return 0;
}

int read_numbers(FILE *stream, struct number ***arr, size_t *len) {
    char *line = NULL;
    size_t n = 0;
    while (read_line(stream, &line, &n, BUFSIZ) != -1) {
        base_t base = DECIMAL;
        if (*line == '0' && line[1] == 'x') {
            base = HEXADECIMAL;
            line += 2;
        } else if (*line == '0b') {
            base = BINARY;
            line += 3;
        }
        struct number *num = parse_number(line, base);
        if (!num)
            return -1;
        struct number **arr_ptr = realloc(*arr, (*len + 1) * sizeof(*(*arr)));
        if (!arr_ptr) {
            free_number(num);
            free_numbers(*arr, *len);
            return -1;
        }
        (*arr_ptr)[*len] = num;
        (*len)++;
    }
    return 0;
}

gmp_uint64_t max(const gmp_uint64_t a, const gmp_uint64_t b) {
    if (a > b)
        return a;
    return b;
}

int find_max(struct number *arr, size_t len, gmp_uint64_t *max) {
    if (!len)
        return -1;
    *max = arr[0]->u;
    for (size_t i = 1; i < len; ++i)
        *max = max(arr[i]->u, *max);
    return 0;
}

