                fprintf(stderr, "Usage: %s [-f file]\n", argv[0]);
                return EXIT_FAILURE;
        }
    }
    if (filename) {
        stream = fopen(filename, "r");
        if (!stream) {
            perror("fopen");
            return EXIT_FAILURE;
        }
    } else {
        stream = stdin;
    }

    struct number **numbers = NULL;
    size_t len = 0;
    if (read_numbers(stream, &numbers, &len) != 0) {
        perror("read_numbers");
        return EXIT_FAILURE;
    }

    gmp_uint64_t max = 0;
    if (find_max(numbers, len, &max) != 0) {
        perror("find_max");
        free_numbers(numbers, len);
        return EXIT_FAILURE;
    }

    printf("The largest number is: %" GMP_UI64_FORMAT "\n", max);

    free_numbers(numbers, len);
    fclose(stream);
    return EXIT_SUCCESS;
}
```

