    return `Range: ${this._min} - ${this._max}`;
  }
}

class LinkObject {
  constructor({
    id,
    rel,
    href,
    media,
    as,
    attributes,
    priority,
    fallbackUrl,
    externalResources,
    conditionalInclude,
    dependency,
  }) {
    this.id = id;
    this.rel = rel;
    this.href = href;
    this.media = media;
    this.as = as;
    this.attributes = attributes || {};
    this.priority = priority || 0;
    this.fallbackUrl = fallbackUrl;
    this.externalResources = externalResources || [];
    this.conditionalInclude = conditionalInclude || false;
    this.dependency = dependency || null;
  }
}

class LinkManager {
  constructor(usePreferredLinks) {
    this._links = [];
    this._usePreferredLinks = usePreferredLinks;
  }

  addLink(linkObj) {
    this._links.push(linkObj);
  }

  generateHeader() {
    const links = document.createElement('head');

    this._links.forEach((link) => {
      if (link.conditionalInclude && !this._usePreferredLinks[link.rel]) return;

      let linkElement = document.createElement('link');
      linkElement.setAttribute('rel', link.rel);

      if (link.href) linkElement.setAttribute('href', link.href);
      if (link.media) linkElement.setAttribute('media', link.media);
      if (link.as) linkElement.setAttribute('as', link.as);

      Object.keys(link.attributes).forEach((attr) => {
        linkElement.setAttribute(attr, link.attributes[attr]);
      });

      if (link.priority) linkElement.setAttribute('priority', link.priority);

      if (link.fallbackUrl && !linkElement.href) {
        linkElement.setAttribute('href', link.fallbackUrl);
      }

      if (link.dependency) {
        this._resolveDependency(link, linkElement);
      } else {
        links.appendChild(linkElement);
      }
    });

    document.head.appendChild(links);
  }

  _resolveDependency(link, linkElement) {
    const dependency = this._links.find((depLink) => depLink.dependency === link.id);

    if (dependency) {
      this._resolveDependency(dependency, linkElement);
    } else {
      setTimeout(() => {
        fetch(link.dependency)
          .then((response) => response.text())
          .then((text) => {
            linkElement.innerHTML = text;
            document.head.appendChild(linkElement);
          })
          .catch((error) => {
            if (link.fallbackUrl) {
              linkElement.setAttribute('href', link.fallbackUrl);
              document.head.appendChild(linkElement);
            }
          });
      }, 0);
    }
  }
}
```

