[' Here's a C implementation of the given programming task, using the `stdio.h`, `stdlib.h`, `string.h`, and `time.h` libraries for file handling, memory allocation, string manipulation, and random number generation respectively. The code is modular, scalable, and includes error handling as per your requirements.

```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>

typedef struct {
    int value;
} record;

void error_log(const char *message) {
    fprintf(stderr, "Warning: %s\n", message);
}

int read_line(FILE *file, char **buffer, size_t *size) {
    char c;
    size_t current_size = *size;
    while (current_size > 0 && (*buffer)[current_size - 1] != '\0') current_size--;

    while ((c = fgetc(file)) != EOF && c != '\n') {
        if (current_size == *size) {
            size_t new_size = *size + 16; // Increase buffer size by 16 each time
            char *new_buffer = realloc(*buffer, new_size);
            if (!new_buffer) return -1; // Memory allocation failure
            *buffer = new_buffer;
            current_size = new_size;
        }
        (*buffer)[current_size++] = c;
    }

    if (c == EOF && current_size == 0) return -1; // End of file with no data read
    (*buffer)[current_size] = '\0';
    return 0;
}

int process_line(char *line, int min_fields, record **records, long *offsets, int *keys, size_t *num_records) {
    char *token = strtok(line, ",");
    int field_count = 0;

    while (token != NULL && field_count < min_fields + 1) {
        if (field_count == min_fields) { // Calculate and append average of last two fields
            long offset1 = atol(token);
            long offset2 = (*offsets)[*num_records - 1] - offset1;
            double avg = ((double)(offset2 - offset1 + 1) / 2) * (long)((double)(*records)[*num_records - 1].value / (offset2 - offset1 + 1));
            char avg_str[32];
            sprintf(avg_str, "%ld", (long)avg);
            token = &line[strlen(line) - strlen(token) - strlen(avg_str) - 1]; // Move to the position after the last field
            strcpy(token, avg_str);
        }

        if (field_count == min_fields - 1) { // Allocate memory for record and initialize with random value
            record *new_record = malloc(sizeof(record));
            if (!new_record) return -1; // Memory allocation failure
            new_record->value = rand() % 100 + 1;
            *records = realloc(*records, (*num_records + 1) * sizeof(record));
            if (!*records) {
                free(new_record);
                return -1; // Memory allocation failure
            }
            (*records)[*num_records++] = *new_record;
        }

        long offset = ftell(stdin);
        *offsets = realloc(*offsets, (*num_records) * sizeof(long));
        if (!*offsets) return -1; // Memory allocation failure
        (*offsets)[*num_records - 1] = offset;

        field_count++;
        token = strtok(NULL, ",");
    }

    if (field_count < min_fields) error_log("Invalid line format");
    return 0;
}

int main(int argc, char *argv[]) {
    srand(time(NULL));

    FILE *file = fopen(argv[1], "r");
    if (!file) {
        perror("Error opening file");
        return 1;
    }

    long *offsets = NULL;
    int *keys = NULL;
    record *records = NULL;
    size_t num_records = 0;

    char buffer[4096]; // Buffer for reading individual lines
    while (read_line(file, &buffer, sizeof(buffer)) == 0) {
        if (process_line(buffer, 3, &records, &offsets, &keys, &num_records) < 0) break;
    }

    fclose(file);

    for (size_t i = 0; i < num_records; i++) {
        printf("%ld,%d,%d,%d\n", offsets[i], keys[i], records[i].value, records[i].value + *(records + num_records - 1)->value);
    }

    free(offsets);
    free(keys);
    free(records);

    return 0;
}
```

