            break;
        }
        ++record_ptr;
    }

    if (record_ptr == &pool->records[pool->size]) {
        fprintf(stderr, "Memory pool is full\n");
        pthread_mutex_unlock(&pool->lock);
        return NULL;
    }

    record_ptr->offset = (long) (record_ptr - pool->records);
    record_ptr->client_id = client_id;
    record_ptr->last_activity = time(NULL);
