    record_ptr->record = record;
    record_ptr->string = (char *)mem_alloc(string_length + 1);
    strncpy(record_ptr->string, "", string_length + 1);
    record_ptr->status = 'A'; // Custom status code

    pthread_mutex_unlock(&pool->lock);
    return record_ptr;
}

void log_allocation_failure(const char *message) {
