class MemoryPool {
public:
    MemoryPool(size_t blockSize) : _blockSize(blockSize), _freeList(nullptr) {}

    void* allocate() {
        if (_freeList == nullptr) {
            _allocateMore();
        }
        auto current = _freeList;
        _freeList = _freeList->next;
        return current;
    }

    void free(void* block) {
        new (block) char; // Construct a dummy char to clear the memory
        auto current = static_cast<MemoryBlock*>(block);
        current->next = _freeList;
        _freeList = current;
    }

private:
    struct MemoryBlock {
        size_t size;
        void* data;
        MemoryBlock* next;
    };

    size_t _blockSize;
    MemoryBlock* _freeList;

    void _allocateMore() {
        auto newBlock = static_cast<MemoryBlock*>(std::malloc(_blockSize));
        if (newBlock == nullptr) {
            log("Failed to allocate memory");
            throw std::bad_alloc();
        }
        newBlock->size = _blockSize;
        newBlock->next = _freeList;
        _freeList = newBlock;
    }
};

