```java
import java.io.*;
import java.net.URL;
import java.nio.charset.StandardCharsets;
import java.security.MessageDigest;
import java.util.ArrayList;
import java.util.List;
import java.util.concurrent.ExecutorService;
import java.util.concurrent.Executors;
import java.util.concurrent.TimeUnit;

public class UrlProcessor {
    private static final int MAX_REDIRECTS = 5;
    private static final int SHA256_HASH_LENGTH = 64;
    private static final String SAFE_SEQUENCE = "SAFE";
    private static final long CACHE_TTL_MILLIS = TimeUnit.DAYS.toMillis(1);

    private Map<String, Long> metadataCache;
    private ExecutorService executor;

    public UrlProcessor() {
        metadataCache = new HashMap<>();
        executor = Executors.newCachedThreadPool();
    }

    public String processUrls(List<String> urls) {
        if (urls == null) return "Input cannot be null";

        List<Future<String>> results = new ArrayList<>();

        for (String url : urls) {
            Callable<String> callable = () -> processUrl(url);
            results.add(executor.submit(callable));
        }

        executor.shutdown();
        try {
            executor.awaitTermination(Long.MAX_VALUE, TimeUnit.NANOSECONDS);
        } catch (InterruptedException e) {
            Thread.currentThread().interrupt();
        }

        StringBuilder response = new StringBuilder();
        for (Future<String> result : results) {
            try {
                String processedUrl = result.get();
                if (!processedUrl.isEmpty()) {
                    response.append(processedUrl).append("\n");
                }
            } catch (Exception e) {
                response.append("Error processing URL: ").append(e.getMessage()).append("\n");
            }
        }

        return response.toString();
    }

    private String processUrl(String url) {
        try {
            URL normalizedUrl = normalizeUrl(url);
            if (normalizedUrl == null) return "";

            long lastModified = getLastModified(normalizedUrl);
            if (lastModified <= metadataCache.getOrDefault(normalizedUrl.toString(), 0L)) return "";

            String sanitizedUrl = sanitizeUrl(normalizedUrl.toString());
            metadataCache.put(sanitizedUrl, System.currentTimeMillis());

            URLConnection connection = normalizedUrl.openConnection();
            connection.setRequestProperty("User-Agent", "Mozilla/5.0");
            connection.setConnectTimeout(5000);
            connection.connect();

            int redirectCount = 0;
            while (connection instanceof HttpURLConnection && ((HttpURLConnection) connection).getResponseCode() / 100 != 2) {
                if (redirectCount >= MAX_REDIRECTS) {
                    logWarning("Redirect chain exceeded the limit");
                    return "";
                }
                connection = ((HttpURLConnection) connection).getURL().openConnection();
                redirectCount++;
            }

            InputStream inputStream = connection.getInputStream();
            byte[] contentBytes = StreamUtils.copyToByteArray(inputStream);
            MessageDigest messageDigest = MessageDigest.getInstance("SHA-256");
            messageDigest.update(contentBytes);
            byte[] hashBytes = messageDigest.digest();
            StringBuilder hash = new StringBuilder(bytesToHex(hashBytes));
            if (hash.length() > SHA256_HASH_LENGTH) {
                hash = hash.substring(0, SHA256_HASH_LENGTH);
            }

            return hash.toString();
        } catch (Exception e) {
            logError("Error processing URL: " + url, e);
            return "";
        }
    }

    // Helper methods for normalization, sanitization, logging, and hex encoding omitted for brevity
}
```

This code uses various Java libraries such as `java.net`, `java.nio.charset`, `java.security`, `java.util.concurrent`, and `org.apache.commons.io`. The helper methods for normalization, sanitization, logging, and hex encoding are not included in this snippet but can be found in the original task description.']

