Record* init_records(int num_offsets, int (*compression_fn)(void*)) {
    Record* records = NULL;
    long* offsets = NULL;
    int* keys = NULL;

    if (!(offsets = calloc(num_offsets, sizeof(long)))) {
        log_failure("Failed to allocate memory for offsets.");
        goto cleanup;
    }

    if (!(keys = calloc(num_offsets, sizeof(int)))) {
        free(offsets);
        log_failure("Failed to allocate memory for keys.");
        goto cleanup;
    }

    records = calloc(num_offsets, sizeof(Record));
    if (!records) {
        free(keys);
        free(offsets);
        log_failure("Failed to allocate memory for records.");
        goto cleanup;
    }

    pthread_t threads[num_offsets];

    for (int i = 0; i < num_offsets; ++i) {
        offsets[i] = i * 5;
        keys[i] = i + 10;
        generate_random(&(records[i].value), 1, 100);

        if (compression_fn) {
            pthread_create(&threads[i], NULL, compression_fn, &records[i]);
        }
    }

    for (int i = 0; i < num_offsets; ++i) {
        pthread_join(threads[i], NULL);
    }

    log_success("Successfully allocated and initialized memory.");
    return records;

cleanup:
    if (records) free(records);
    if (keys) free(keys);
    if (offsets) free(offsets);

    return NULL;
}
```

