[' Here's a high-level design for the requested C function using a custom memory pool, red-black tree for efficient insertion and retrieval, and thread-safe operations with minimal locking overhead. The code is not compiled or tested, but it should give you a good starting point.

```c
#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <stdbool.h>
#include <time.h>
#include <sys/mman.h>
#include <logservice.h> // Logging service interface
#include <datasource.h> // External data source interface

typedef struct node {
    int key;
    double value;
    struct node *left, *right, *parent;
    bool is_red;
} Node;

typedef struct rb_tree {
    Node* root;
    size_t size;
    pthread_mutex_t lock;
    void* memory_pool;
} RBTree;

RBTree* create_rb_tree(size_t initial_capacity) {
    RBTree* tree = malloc(sizeof(RBTree));
    tree->root = NULL;
    tree->size = 0;
    pthread_mutex_init(&tree->lock, NULL);
    tree->memory_pool = memalign(64, initial_capacity * sizeof(Node)); // Align to 64 bytes for better cache locality
    return tree;
}

void destroy_rb_tree(RBTree* tree) {
    free(tree->memory_pool);
    pthread_mutex_destroy(&tree->lock);
    free(tree);
}

Node* create_node(int key, double value) {
    Node* node = malloc(sizeof(Node));
    node->key = key;
    node->value = value;
    node->left = NULL;
    node->right = NULL;
    node->parent = NULL;
    node->is_red = true;
    return node;
}

void insert_rb(RBTree* tree, Node* node) {
    pthread_mutex_lock(&tree->lock);

    Node** n = &tree->root;
    Node* parent = NULL;

    while (*n != NULL) {
        parent = *n;
        if (node->key < (*n)->key)
            n = &((*n)->left);
        else
            n = &((*n)->right);
    }

    node->parent = parent;
    if (parent == NULL) {
        tree->root = node;
    } else {
        if (node->key < parent->key)
            parent->left = node;
        else
            parent->right = node;
    }

    node->is_red = true;
    insert_balance(tree, node);

    pthread_mutex_unlock(&tree->lock);
}

Node* find_rb(RBTree* tree, int key) {
    pthread_mutex_lock(&tree->lock);
    Node* current = tree->root;

    while (current != NULL) {
        if (key < current->key)
            current = current->left;
        else if (key > current->key)
            current = current->right;
        else
            break;
    }

    pthread_mutex_unlock(&tree->lock);
    return current;
}

void* get_memory(RBTree* tree, size_t size) {
    void* memory = mmap(NULL, size, PROT_READ | PROT_WRITE, MAP_PRIVATE | MAP_ANONYMOUS, -1, 0);
    if (memory == MAP_FAILED) {
        log_error("Failed to allocate memory");
        exit(EXIT_FAILURE);
    }
    return memory;
}

void free_memory(RBTree* tree, void* memory, size_t size) {
    munmap(memory, size);
}

Node* create_and_insert(RBTree* tree, int key, double value) {
    Node* node = create_node(key, value);
    insert_rb(tree, node);
    return node;
}

void init_from_data_source(RBTree* tree, DataSource* data_source) {
    Node* nodes = get_memory(tree, data_source->size * sizeof(Node));
    data_source->read(nodes);

    for (size_t i = 0; i < data_source->size; ++i) {
        create_and_insert(tree, ((Node*)(nodes + i))->key, ((Node*)(nodes + i))->value);
    }

    free_memory(tree, nodes, data_source->size * sizeof(Node));
}
```

This code provides a basic implementation of a red-black tree with a custom memory pool for dynamic resizing and efficient allocation. The `RBTree` struct contains the root node, size, lock, and memory pool. The `create_rb_tree()` function initializes the tree with a given capacity, while `destroy_rb_tree()` frees all resources when the tree is no longer needed.

The `Node` struct represents each record in the data structure, containing the key, value, and pointers to its children and parent nodes. The red-black tree properties are maintained by the `insert_rb()` function, which also handles balancing after insertions. The `find_rb()` function searches for a node with a given key.

The `create_and_insert()` function creates a new node and inserts it into the tree, while `init_from_data_source()` initializes the tree from an external data source.']

