typedef struct Record {
    long offset;
    int key;
    float value;
} Record;

// Custom memory pool
struct Pool {
    void* data;
    size_t capacity;
    size_t allocated;
};

void* mempool_alloc(struct Pool* pool, size_t size) {
    if (pool->allocated + size > pool->capacity) return NULL;

    void* result = ((char*)pool->data + pool->allocated);
    pool->allocated += size;
    return result;
}

// Lock for thread safety
pthread_mutex_t lock;

void init_lock() {
    pthread_mutex_init(&lock, NULL);
}

Record* init_records(int n, int m, int p) {
    Record* records = (Record*)mempool_alloc(&pool, sizeof(Record) * n);
    if (!records) return NULL;

    for (int i = 0; i < n; ++i) {
        pthread_mutex_lock(&lock);
        records[i].offset = i;
        records[i].key = i;
        records[i].value = rand() / (RAND_MAX + 1.0f) * 2 - 1;
        pthread_mutex_unlock(&lock);
    }

    return records;
}

void validate_memory(struct Pool pool) {
    size_t total_allocated = pool.capacity - pool.allocated;
    // Add overhead and alignment requirements here
    if (total_allocated > 1024 * 1024) printf("Memory usage exceeded 1MB limit\n");
}

