    char *line = NULL;
    ssize_t read;

    size_t offset_capacity = 10;
    long *offsets = malloc(offset_capacity * sizeof(long));
    if (!offsets) goto error; // Handle memory allocation error

    size_t key_capacity = 10;
    int *keys = malloc(key_capacity * sizeof(int));
    if (!keys) goto error; // Handle memory allocation error

    size_t record_capacity = 10;
    Record *records = calloc(record_capacity, sizeof(Record));
    if (!records) goto error; // Handle memory allocation error

    int num_fields = 0;
    while ((read = getline(&line, &line_size, file)) != -1) {
        char **fields = my_split_line(line);
        if (fields == NULL || fields[num_fields] == NULL) {
            fprintf(stderr, "Warning: Invalid line skipped\n");
            continue;
        }

        if (num_fields < 3) {
            free(line);
            break;
        }

        long offset = *offsets ? *(offsets + num_fields - 1) : 0;
        int key = atoi(fields[0]);
        records[offset].value = rand() % 100; // Random number within range 0-99

        if (num_fields > offset_capacity) {
            long *temp_offsets = realloc(offsets, (offset_capacity *= 2) * sizeof(long));
            if (!temp_offsets) goto error; // Handle memory allocation error
            offsets = temp_offsets;
        }
        offsets[num_fields] = offset + 1;

        if (num_fields > key_capacity) {
            int *temp_keys = realloc(keys, (key_capacity *= 2) * sizeof(int));
            if (!temp_keys) goto error; // Handle memory allocation error
            keys = temp_keys;
        }
        keys[num_fields] = key;

        num_fields++;

        if (num_fields > record_capacity - 1) {
            Record *temp_records = realloc(records, (record_capacity *= 2) * sizeof(Record));
            if (!temp_records) goto error; // Handle memory allocation error
            records = temp_records;
        }
    }

    free(line);
    my_fclose(file);

    // Process the last two fields and average them, append as final field in a comma-separated format.
    // This logic can be added based on your specific requirements.

    return;

error:
    fprintf(stderr, "Error: Failed to allocate memory\n");
    if (file) my_fclose(file);
    if (line) free(line);
    if (offsets) free(offsets);
    if (keys) free(keys);
    if (records) free(records);
}
