```javascript
const generateRandom = (min, max) => Math.floor(Math.random() * (max - min + 1)) + min;

const CHUNK_SIZE = 1024;
const MAX_MEMORY_USAGE = 10 * 1024 * 1024; // 10 MB
let allocatedMemory = 0;

function initializeDataStructures(chunkSize, maxMemoryUsage, validateMemory, ...params) {
  if (maxMemoryUsage <= 0 || chunkSize <= 0) {
    throw new Error('Invalid parameters: maxMemoryUsage and chunkSize must be positive values.');
  }

  const recordsBuffer = Buffer.allocUnsafe(chunkSize * params.length);
  let offsetsBuffer = Buffer.allocUnsafe(params.length);
  let keysBuffer = Buffer.allocUnsafe(params.length);

  for (let i = 0; i < params.length; ++i) {
    const record = {};
    record.value = generateRandom(1, 100);
    record.offset = recordsBuffer.writeInt32BE(i * 5, i * 4);
    record.key = keysBuffer.writeInt32LE(i + 10, i * 4 + 4);
    recordsBuffer.writeInt32LE(record.value, record.offset);

    if (validateMemory) {
      const offsetValue = recordsBuffer.readInt32BE(record.offset);
      const keyValue = keysBuffer.readInt32LE(record.key);

      if (offsetValue !== i * 5 || keyValue !== i + 10) {
        throw new Error('Memory validation failed.');
      }
    }

    allocatedMemory += record.value + 8; // 8 bytes for offset and key

    if (allocatedMemory > maxMemoryUsage) {
      break;
    }
  }

  const records = Array.from({ length: params.length }, (_, i) => {
    const offset = recordsBuffer.readInt32BE(i * 4);
    const key = recordsBuffer.readInt32LE(i * 4 + 4);
    return { value: recordsBuffer.readInt32LE(offset), offset, key };
  });

  if (records.length < params.length) {
    // Free previously allocated memory
    for (let i = 0; i < records.length; ++i) {
      recordsBuffer.writeInt32BE(0, i * 4);
      keysBuffer.writeInt32LE(0, i * 4 + 4);
    }

    // Reset allocated memory counter
    allocatedMemory = 0;

    return [];
  }

  return records;
}
```

