#include <ctime>

struct Record {
    int key;
    float value;
    std::string* str;
    std::tm timestamp;
    int version;
};

class MemoryPool {
public:
    virtual Record* allocate() = 0;
    virtual void deallocate(Record* record) = 0;
};

class ThreadSafeMemoryPool : public MemoryPool {
private:
    boost::lockfree::slist<Record> freeList;
    boost::container::static_vector<Record, 1024> buffer;

public:
    Record* allocate() override {
        if (!freeList.empty()) {
            auto record = freeList.pop_front();
            return &record;
        }

        if (buffer.size() > 0) {
            auto index = buffer.size() - 1;
            Record* record = &buffer[index];
            buffer.pop_back();
            return record;
        }

        // Allocate new memory if necessary
        auto record = static_cast<Record*>(std::malloc(sizeof(Record)));
        new (record) Record();
        return record;
    }

    void deallocate(Record* record) override {
        record->~Record();
        freeList.push_back(*record);
    }
};

