[' I'll provide you with the C function for managing network connections and a Java method for computing MD5 hashes.

C Function: Connection Manager (using pthreads and a linked list)

```c
#include <pthread.h>
#include <stdio.h>
#include <stdlib.h>
#include <time.h>

typedef struct {
    int id;
    enum { IDLE, ESTABLISHED, CLOSED } state;
    time_t establishment_ts;
    time_t last_activity_ts;
    int error_count;
    void* metadata; // Additional metadata
    pthread_mutex_t lock;
} Connection;

typedef struct Node {
    Connection conn;
    struct Node* next;
} Node;

Node* head = NULL;
pthread_mutex_t list_lock = PTHREAD_MUTEX_INITIALIZER;

void connection_establish(Connection* conn, void* metadata) {
    if (conn->id < 0 || conn->state != ESTABLISHED) {
        fprintf(stderr, "Invalid input: %d\n", conn->id);
        return;
    }

    pthread_mutex_init(&conn->lock, NULL);
    conn->state = ESTABLISHED;
    conn->establishment_ts = time(NULL);
    conn->last_activity_ts = conn->establishment_ts;
    conn->error_count = 0;
    conn->metadata = metadata;
}

void connection_close(int id) {
    Node* current = head;
    Node* previous = NULL;

    pthread_mutex_lock(&list_lock);
    while (current != NULL && current->conn.id != id) {
        previous = current;
        current = current->next;
    }

    if (current == NULL) {
        fprintf(stderr, "Connection not found: %d\n", id);
        pthread_mutex_unlock(&list_lock);
        return;
    }

    free(previous); // Free the previous node
    Connection* conn = &current->conn;
    pthread_mutex_destroy(&conn->lock);

    if (head == current) {
        head = current->next;
    } else {
        previous->next = current->next;
    }

    free(current);
}

Connection* connection_query(int id) {
    Node* current = head;
    Connection* result = NULL;

    pthread_mutex_lock(&list_lock);
    while (current != NULL && current->conn.id != id) {
        current = current->next;
    }

    if (current == NULL) {
        result = NULL;
    } else {
        pthread_mutex_lock(&current->conn.lock);
        result = &current->conn;
    }

    pthread_mutex_unlock(&list_lock);
    return result;
}

// Monitoring function with optional thresholds for inactivity and error rates
void monitor_connections(int inactivity_threshold, int error_threshold) {
    Node* current = head;
    while (current != NULL) {
        Connection* conn = &current->conn;
        pthread_mutex_lock(&conn->lock);

        if (conn->state == ESTABLISHED && time(NULL) - conn->last_activity_ts > inactivity_threshold) {
            connection_close(conn->id);
        }

        if (conn->error_count >= error_threshold) {
            connection_close(conn->id);
        }

        pthread_mutex_unlock(&conn->lock);
        current = current->next;
    }
}

// Add a new connection to the list
void add_connection(Connection conn) {
    Node* new_node = malloc(sizeof(Node));
    if (new_node == NULL) {
        fprintf(stderr, "Out of memory\n");
        return;
    }

    new_node->conn = conn;
    new_node->next = head;
    head = new_node;
}
```

Java MD5 Hash Method:

```java
import java.math.BigInteger;
import java.util.Arrays;

public class MD5 {
    private static BigInteger[] K = new BigInteger[64];
    static {
        for (int i = 0; i < 16; ++i) {
            K[i] = new BigInteger(32, RANDOM);
        }
        for (int i = 16; i < 64; ++i) {
            K[i] = K[i - 16].shiftLeft(8).or(K[i - 7].rotateRight(6));
        }
    }

    private static final BigInteger[] F = new BigInteger[256];
    static {
        for (int i = 0; i < 256; ++i) {
            int a = i / 32;
            int b = i % 32;
            F[i] = (BigInteger.valueOf(a + ((b <= 15) ? ROTATE_LEFT_019 : ROTATE_LEFT_064)) & 0xFFFFFFFFL).toString(16);
        }
    }

    private static final BigInteger[] ROTATE_LEFT_019 = new BigInteger[]{
            new BigInteger("1"), new BigInteger("2"), new BigInteger("3"), new BigInteger("4"),
            new BigInteger("5"), new BigInteger("6"), new BigInteger("7"), new BigInteger("8"),
            new BigInteger("9"), new BigInteger("10"), new BigInteger("11"), new BigInteger("12"),
            new BigInteger("13"), new BigInteger("14"), new BigInteger("15"), new BigInteger("16")
    };

    private static final BigInteger[] ROTATE_LEFT_064 = new BigInteger[]{
            new BigInteger("1"), new BigInteger("2"), new BigInteger("3"), new BigInteger("4"),
            new BigInteger("5"), new BigInteger("6"), new BigInteger("7"), new BigInteger("8"),
            new BigInteger("9"), new BigInteger("10"), new BigInteger("11"), new BigInteger("12"),
            new BigInteger("13"), new BigInteger("14"), new BigInteger("15"), new BigInteger("16"),
            new BigInteger("17"), new BigInteger("18"), new BigInteger("19"), new BigInteger("20"),
            new BigInteger("21"), new BigInteger("22"), new BigInteger("23"), new BigInteger("24"),
            new BigInteger("25"), new BigInteger("26"), new BigInteger("27"), new BigInteger("28"),
            new BigInteger("29"), new BigInteger("30"), new BigInteger("31"), new BigInteger("32")
    };

    public static byte[] computeMD5(byte[] data) {
        if (data == null || data.length == 0) {
            throw new IllegalArgumentException("Data cannot be null or empty");
        }

        int blockSize = 64;
        int dataLength = data.length;
        int numberOfBlocks = ((dataLength + blockSize - 1) / blockSize);
        byte[][] blocks = new byte[numberOfBlocks][blockSize];

        for (int i = 0; i < dataLength; ++i) {
            blocks[i / blockSize][i % blockSize] = data[i];
        }

        int[] A = new int[]{0x67452301, 0xefcdab89, 0x98badcfe, 0x10325476};
        int[] B = new int[]{0x67452301, 0xefcdab89, 0x98badcfe, 0x10325476};
        int[] C = new int[]{0x67452301, 0xefcdab89, 0x98badcfe, 0x10325476};
        int[] D = new int[]{0x67452301, 0xefcdab89, 0x98badcfe, 0x10325476};

        for (int blockIndex = 0; blockIndex < numberOfBlocks; ++blockIndex) {
            processBlock(blocks[blockIndex], A, B, C, D);
        }

        int[] finalA = new int[]{A[0] + A[1] + A[2] + A[3]};
        int[] finalB = new int[]{B[0] + B[1] + B[2] + B[3]};
        int[] finalC = new int[]{C[0] + C[1] + C[2] + C[3]};
        int[] finalD = new int[]{D[0] + D[1] + D[2] + D[3]};

        byte[] result = new byte[16];
        for (int i = 0; i < 4; ++i) {
            for (int j = 0; j < 4; ++j) {
                result[(i * 4) + j] = (byte) finalA[i] & 0xFF;
                result[(i * 4) + j + 4] = (byte) finalB[i] & 0xFF;
                result[(i * 4) + j + 8] = (byte) finalC[i] & 0xFF;
                result[(i * 4) + j + 12] = (byte) finalD[i] & 0xFF;
            }
        }

        return result;
    }

    private static void processBlock(byte[] block, int[] A, int[] B, int[] C, int[] D) {
        int[] Ft = new int[16];
        for (int i = 0; i < 16; ++i) {
            BigInteger temp = new BigInteger(1, Arrays.copyOfRange(block, i * 4, (i + 1) * 4));
            Ft[i] = F[(temp.xor(BigInteger.valueOf(0x80000000L)).intValue() & 0xFF)].intValue();
        }

        int[] tempA = new int[]{A[0], A[1], A[2], A[3]};
        int[] tempB = new int[]{B[0], B[1], B[2], B[3]};
        int[] tempC = new int[]{C[0], C[1], C[2], C[3]};
        int[] tempD = new int[]{D[0], D[1], D[2], D[3]};

        for (int i = 0; i < 64; ++i) {
            if ((i <= 15) || (i >= 64 - 15)) {
                tempA[Ft[i] & 3] += (K[i].xor(tempB[(i + 6) & 15]).and(tempC).or(tempD)).intValue();
            } else {
                tempA[Ft[i] & 3] = rol(tempA[(Ft[i - 2] & 3)], 5) + ((tempA[(Ft[i - 7] & 3)] ^ tempB[(Ft[i - 15] & 3)]) << 3)
                        .or((tempA[(Ft[i - 16] & 3)] ^ tempC[(Ft[i - 19] & 3)]) >>> 6);
            }
        }

        A[0] += tempA[0];
        A[1] += tempA[1];
        A[2] += tempA[2];
        A[3] += tempA[3];
    }

    private static int rol(int value, int shift) {
        return (value << shift) | (value >>> 32 - shift);
    }
}
