```cpp
#include <iostream>
#include <string>
#include <boost/filesystem.hpp>
#include <boost/lockfree/queue.hpp>
#include <chrono>
#include <cstdlib>
#include <system_error>

namespace bfs = boost::filesystem;
namespace blf = boost::lockfree;

constexpr size_t max_identifier_length = 64;
constexpr size_t average_filename_length = 20; // Adjust this value based on your directory's file names
constexpr size_t chunk_size = 1024 * 1024; // 1 MB chunks for reading large files efficiently

struct FileData {
    bfs::path path;
    std::string identifier;
};

blf::queue<FileData> file_data_queue;
std::mutex log_mutex;

void process_file(const FileData& data) {
    std::ifstream file(data.path, std::ios::binary);
    if (!file) {
        std::lock_guard<std::mutex> lock(log_mutex);
        std::cerr << "Error opening file: " << data.path.string() << '\n';
        return;
    }

    unsigned long long file_size = 0;
    auto start = std::chrono::high_resolution_clock::now();
    char buffer[chunk_size];
    while (file.read(buffer, chunk_size)) {
        file_size += chunk_size;
    }
    auto end = std::chrono::high_resolution_clock::now();
    auto duration = std::chrono::duration_cast<std::chrono::milliseconds>(end - start).count();

    auto timestamp = std::chrono::system_clock::to_time_t(file.last_mod_time());
    char timestamp_str[20];
    ctime_s(timestamp_str, sizeof(timestamp_str), &timestamp);
    timestamp_str[strlen(timestamp_str) - 1] = '\0'; // Remove newline character

    data.identifier.resize(std::min(max_identifier_length, average_filename_length + 24 + std::to_string(file_size).length() + std::to_string(duration).length()));
    auto it = data.identifier.begin();
    it = std::copy(data.path.filename().string().begin(), data.path.filename().string().end(), it);
    it = std::copy(timestamp_str, timestamp_str + strlen(timestamp_str), it);
    it = std::copy(std::to_string(file_size).begin(), std::to_string(file_size).end(), it);
    it = std::copy(std::to_string(duration).begin(), std::to_string(duration).end(), it);

    std::lock_guard<std::mutex> lock(log_mutex);
    std::cout << "Processing file: " << data.path.string() << ", size: " << file_size << ", duration: " << duration << "ms\n";
}

void walk_directory(const bfs::path& path) {
    for (auto & entry : bfs::recursive_directory_iterator(path)) {
        if (bfs::is_regular_file(entry)) {
            FileData data{entry, ""};
            file_data_queue.enqueue(data);
        }
    }
}

void process_files() {
    while (!file_data_queue.empty()) {
        FileData data;
        if (file_data_queue.try_dequeue(data)) {
            process_file(data);
        }
    }
}

int main(int argc, char* argv[]) {
    if (argc != 2) {
        std::cerr << "Usage: " << argv[0] << " <directory>\n";
        return EXIT_FAILURE;
    }

    try {
        bfs::path directory(argv[1]);
        walk_directory(directory);
        process_files();
    } catch (const std::exception& e) {
        std::cerr << "Error: " << e.what() << '\n';
        return EXIT_FAILURE;
    }

    return EXIT_SUCCESS;
}
```

