int count_path_length(const char *path) {
    int length = 0;
    for (; *path != '\0'; ++path) {
        if (*path == '/')
            ++length;
    }
    return length > 10 ? 10 : length;
}

int get_extension_counter(int path_length, int max_digits) {
    int counter = 0;
    for (int i = 0; i < max_digits; ++i) {
        counter = counter * 10 + (path_length + i);
    }
    return counter % NUM_EXTENSIONS;
}

char* process_filename(const char *filename, int extension_counter) {
    size_t len = strlen(filename);
    if (len > 255) {
        fprintf(stderr, "Filename exceeds the maximum length of 255 characters.\n");
        return NULL;
    }

    char *processed_filename = malloc(len + NUM_EXTENSIONS);
    strcpy(processed_filename, filename);
    snprintf(processed_filename + len - NUM_EXTENSIONS, NUM_EXTENSIONS, ".ext%d", extension_counter);
    return processed_filename;
}

void rename_file(const char *old_filename, const char *new_filename) {
    if (rename(old_filename, new_filename)) {
        perror("Error renaming file");
    }
}

void directory_traversal(const char *path, int *counter, pthread_mutex_t *mutex) {
    DIR *dir = opendir(path);
    struct dirent *entry;

    if (dir != NULL) {
        pthread_mutex_lock(mutex);
        *counter += opendir(path); // Increment the counter for each directory traversed
        pthread_mutex_unlock(mutex);

        while ((entry = readdir(dir)) != NULL) {
            if (entry->d_type == DT_DIR) {
                continue;
            }

            int path_length = count_path_length(path);
            int extension_counter = get_extension_counter(path_length, path_length > 10 ? 10 : path_length);
            char *processed_filename = process_filename(entry->d_name, extension_counter);

            if (processed_filename != NULL) {
                char new_filename[256];
                snprintf(new_filename, sizeof(new_filename), "%s/%s", path, processed_filename);
                rename_file(entry->d_name, new_filename);
            }
        }
        closedir(dir);
    }
}

