#include <sys/stat.h>
#include <limits.h>

#define FILE_TYPE ".txt"
#define MAX_PATH 1024
#define MAX_NAME 256
#define MAX_EXT 8

char *generate_filename(const char *input) {
    size_t base_name_len = strlen(input);
    size_t ext_len = strlen(FILE_TYPE);
    size_t name_len = base_name_len + 1 + to_string_length(base_name_len) + ext_len;
    char *new_filename = malloc(MAX_PATH);
    memset(new_filename, 0, MAX_PATH);

    // Validate input filename and directory path
    const char *dir_start = strchr(input, '/');
    if (!dir_start || dir_start >= (input + base_name_len)) {
        free(new_filename);
        return NULL;
    }

    size_t dir_len = (size_t)(dir_start - input);
    if (dir_len > 100) {
        dir_len = 99;
        strncpy(new_filename, input, dir_len);
        new_filename[dir_len] = '\0';
        strcat(new_filename, "/...");
    } else {
        strncpy(new_filename, input, dir_len + 1);
        new_filename[dir_len + 1] = '\0';
    }

    size_t base_name_start = dir_len + 1;
    if (base_name_start >= base_name_len) {
        strncpy(new_filename + strlen(new_filename), FILE_TYPE, ext_len);
        return new_filename;
    }

    size_t base_name_end = base_name_start;
    while (base_name_end < base_name_len && isalnum(input[base_name_end])) {
        base_name_end++;
    }

    char num_str[16];
    snprintf(num_str, sizeof(num_str), "%zu", base_name_end - base_name_start);
    strncat(new_filename + strlen(new_filename), num_str, name_len - base_name_len - ext_len);
    strncat(new_filename + strlen(new_filename), FILE_TYPE, ext_len);

    // Check for existing file and generate unique filename if necessary
    char temp_path[MAX_PATH];
    snprintf(temp_path, sizeof(temp_path), "%s%s", new_filename, FILE_TYPE);
    struct stat st;
    if (stat(temp_path, &st) == 0) {
        time_t now = time(NULL);
        char timestamp[21];
        snprintf(timestamp, sizeof(timestamp), "%lu", now);
        strncat(new_filename + strlen(new_filename), "_", name_len - base_name_len - ext_len);
        strncat(new_filename + strlen(new_filename), timestamp, strlen(timestamp));
        snprintf(temp_path, sizeof(temp_path), "%s%s", new_filename, FILE_TYPE);
    }

    return new_filename;
}

size_t to_string_length(unsigned int num) {
    size_t len = 1;
    while (num >= 10) {
        num /= 10;
        len++;
    }
    return len;
}
```

This function generates a new filename based on the given constraints. It validates the input, handles potential race conditions, and ensures uniqueness in the event of multiple files with the same base name. The file type can be easily updated by modifying the `FILE_TYPE` constant.']

