        {
            _logger.LogError(ex, $"An error occurred while processing directory '{directoryPath}'.");
            semaphore.Release();
            return null;
        }
    }

    private bool CheckPermissions(string path)
    {
        try
        {
            var fileAttributes = File.GetAttributes(path);
            if ((fileAttributes & FileAttributes.ReadOnly) == FileAttributes.ReadOnly)
                File.SetAttributes(path, fileAttributes ^ FileAttributes.ReadOnly);

            return true;
        }
        catch (Exception ex)
        {
            _logger.LogError(ex, $"Failed to check permissions for path '{path}'.");
            return false;
        }
    }

