} record;

sem_t mutex;
unsigned long total_memory = 0;
const unsigned long MAX_MEMORY = 1024 * 1024 * 10; // 10 MB limit

void log_memory() {
    printf("Current memory usage: %lu bytes\n", total_memory);
}

void* resize(void* ptr, size_t size) {
    void* new_ptr = mmap(NULL, size, PROT_READ | PROT_WRITE, MAP_PRIVATE | MAP_ANONYMOUS, -1, 0);
    if (new_ptr == MAP_FAILED) {
        perror("mmap");
        exit(EXIT_FAILURE);
    }
    memcpy(new_ptr, ptr, total_memory < size ? total_memory : size);
    munmap(ptr, total_memory);
    total_memory = size;
    return new_ptr;
}

record* create_record() {
    sem_wait(&mutex);
    record* records = (record*)resize(records, total_memory + sizeof(record));
    sem_post(&mutex);
    return &records[total_memory / sizeof(record)];
}

