class MemoryManager {
public:
    MemoryManager(size_t maxRecords, bool useFixedSeed) : _maxRecords(maxRecords), _useFixedSeed(useFixedSeed) {
        if (_useFixedSeed) {
            std::random_device rd;
            _gen.seed(rd());
        } else {
            std::random_device rd;
            _gen.seed(std::chrono::system_clock::now().time_since_epoch().count());
        }
