    Record* allocateRecord() {
        auto record = std::make_unique<Record>();
        record->value = _gen(_dist);
        _records.push_back(std::move(record));
        return _records.back().get();
    }

    int allocateKey(Record* record) {
        std::lock_guard<std::mutex> lock(_keysMutex);
        auto key = ++_nextKey;
        _keys[key] = record;
        return key;
    }

    long allocateOffset(int key) {
        std::lock_guard<std::mutex> lock(_offsetsMutex);
        auto offset = _nextOffset++;
        _offsets[offset] = key;
        return offset;
    }

    void deallocate(Record* record, long offset) {
        std::lock_guard<std::mutex> lock(_offsetsMutex);
        assert(_offsets.find(offset) != _offsets.end());
        auto key = _offsets[offset];
        _keys[_keys.erase(key)->second] = nullptr;
        _offsets.erase(offset);

        std::lock_guard<std::mutex> lock(_keysMutex);
        if (_keys.find(key) == _keys.end()) {
            assert(false && "Record not found in keys");
        }
        _records[_records.size() - 1].reset();
        _keys.erase(key);
    }

    void cleanup() {
        for (auto& record : _records) {
            if (record) {
                deallocate(record.get(), record->value);
            }
        }
        _records.clear();
    }

    std::vector<long> getOffsets() const { return _offsets; }
    std::vector<int> getKeys() const { return _keys; }
    std::vector<Record*> getRecords() const { return _records; }

private:
    size_t _maxRecords;
    bool _useFixedSeed;
    std::random_device _rd;
    std::mt19937 _gen;
    std::uniform_int_distribution<int> _dist{0, 100}; // Adjust the range as needed
    std::vector<std::unique_ptr<Record>> _records;
    std::map<int, Record*> _keys;
    std::map<long, int> _offsets;
    std::atomic<int> _nextKey{0};
    std::atomic<long> _nextOffset{0};
    std::mutex _keysMutex;
    std::mutex _offsetsMutex;
};
