```cpp
#include <iostream>
#include <vector>
#include <random>
#include <memory>
#include <algorithm>

struct record_t {
    key_t key;
    value_t value;
    std::unique_ptr<record_t> next;
};

class Cache {
public:
    Cache(size_t size) : metadata(size, 0), keys(size, 1), records(size) {}

    int createHandle() {
        for (size_t i = 0; i < metadata.size(); ++i) {
            if (!metadata[i]) {
                metadata[i] = 1;
                auto& head = records[i];
                head.key = keys[i];
                head.value = rand() % (max_value - min_value + 1) + min_value;
                head.next.reset(new record_t{});
                return i;
            }
        }
        throw std::runtime_error("Cache is full");
    }

    void insert(int handle, key_t key, value_t value) {
        auto& head = records[handle];
        while (head->next && head->next->key != key) {
            head = head->next.get();
        }

        if (!head->next) {
            head->next.reset(new record_t{key, value, std::unique_ptr<record_t>{}});
        } else {
            auto new_node = std::make_unique<record_t>(key, value, std::move(head->next));
            head->next.swap(new_node);
        }
    }

    void retrieve(int handle, record_t& result) const {
        auto head = records[handle].get();
        while (head && head->key != keys[handle]) {
            head = head->next.get();
        }
        if (!head) {
            throw std::runtime_error("Record not found");
        }
        result = *head;
    }

    void update(int handle, key_t key, value_t new_value) {
        auto& head = records[handle];
        while (head && head->key != key) {
            head = head->next.get();
        }
        if (!head) {
            throw std::runtime_error("Record not found");
        }
        head->value = new_value;
    }

    void remove(int handle) {
        auto& head = records[handle];
        if (head->next) {
            head->next.reset(head->next.get()->next.release());
        } else {
            metadata[handle] = 0;
        }
    }

private:
    std::vector<offset_t> metadata;
    std::vector<key_t> keys;
    std::vector<record_t> records;
};
```

