#include <iostream>
#include <vector>
#include <unordered_map>
#include <thread>
#include <mutex>
#include <random>

const int MAX_MEMORY = 1024 * 1024; // Maximum memory in bytes
std::mutex mtx;
std::vector<long> offsets;
std::unordered_map<int, long> keys;
std::vector<int> records;
std::mt19937 rng(time(NULL)); // Default seed for random number generation

void* allocate(size_t size) {
    if (offsets.empty() || offsets.back() + size > MAX_MEMORY) {
        long new_offset = 0;
        std::lock_guard<std::mutex> lock(mtx);
        if (offsets.empty()) {
            new_offset = 0;
        } else {
            new_offset = offsets.back() + size;
        }
        void* mem = new char[new_offset];
        offsets.push_back(new_offset);
        return mem;
    }
    long available_offset = offsets.back() - size;
    std::lock_guard<std::mutex> lock(mtx);
    offsets.back() = available_offset;
    return offsets[offsets.size() - 1] + sizeof(long) * (offsets.size() - 1);
}

int getKey(int value) {
    int key;
    if (keys.find(value) != keys.end()) {
        key = keys[value];
    } else {
        std::lock_guard<std::mutex> lock(mtx);
        key = hash(value);
        while (keys.find(key) != keys.end()) {
            key = hash(value) + 1;
        }
        keys[value] = key;
    }
    return key;
}

int hash(int value) {
    std::hash<int> hasher;
    return hasher(value) % records.size();
}

void generateRandomRecord(int index) {
    int random_number = rng() % 100; // Generate a random number between 0 and 99
    records[index] = random_number;
}

void cleanup() {
    for (long offset : offsets) {
        delete[] static_cast<char*>(offset);
    }
    offsets.clear();
    keys.clear();
    records.clear();
}

int main() {
    int num_records = 10000;
    records.resize(num_records);

    std::vector<std::thread> threads;
    for (int i = 0; i < 4; ++i) {
        threads.push_back(std::thread(generateRandomRecord, 0));
    }

    for (auto& thread : threads) {
        thread.join();
    }

    // Add cleanup function call here to release all allocated resources before program exit

    return 0;
}
```

