[' I'll provide you with the C function for managing network connections and records, as well as a Java method for computing MD5 hashes.

C Function:
```c
#include <pthread.h>
#include <stdbool.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>

typedef struct {
    int id;
    enum { IDLE, ESTABLISHED, CLOSED } state;
    time_t establishment_ts;
    time_t last_activity_ts;
    int error_count;
    char label[256];
    pthread_mutex_t lock;
} Connection;

#define CONN_POOL_SIZE 1024
Connection conn_pool[CONN_POOL_SIZE];
int conn_pool_head = 0, conn_pool_tail = 0;

void init_conn(Connection* conn) {
    memset(conn, 0, sizeof(Connection));
    pthread_mutex_init(&conn->lock, NULL);
}

Connection get_conn() {
    if (conn_pool_head == conn_pool_tail) return NULL;
    int idx = (conn_pool_head + 1) % CONN_POOL_SIZE;
    Connection* conn = &conn_pool[idx];
    init_conn(conn);
    conn_pool_head = idx;
    return *conn;
}

void free_conn(Connection* conn) {
    pthread_mutex_destroy(&conn->lock);
    memset(conn, 0, sizeof(Connection));
    if (conn_pool_head == conn_pool_tail) return;
    int idx = (conn_pool_head - 1 + CONN_POOL_SIZE) % CONN_POOL_SIZE;
    conn_pool[idx] = *conn;
    conn_pool_head = idx;
}

Connection establish(int id, const char* label) {
    Connection conn = get_conn();
    if (!conn) return NULL;
    conn.id = id;
    strncpy(conn.label, label, sizeof(conn.label));
    conn.state = ESTABLISHED;
    conn.establishment_ts = time(NULL);
    conn.last_activity_ts = conn.establishment_ts;
    return conn;
}

void close(Connection* conn) {
    pthread_mutex_lock(&conn->lock);
    if (conn->state != ESTABLISHED) {
        pthread_mutex_unlock(&conn->lock);
        return;
    }
    conn->state = CLOSED;
    conn->last_activity_ts = time(NULL);
    log_connection_close(conn);
    pthread_mutex_unlock(&conn->lock);
}

bool is_idle(Connection* conn) {
    pthread_mutex_lock(&conn->lock);
    bool ret = (conn->state == IDLE || conn->state == CLOSED);
    pthread_mutex_unlock(&conn->lock);
    return ret;
}

void update_activity(Connection* conn) {
    pthread_mutex_lock(&conn->lock);
    conn->last_activity_ts = time(NULL);
    pthread_mutex_unlock(&conn->lock);
}

void increment_error(Connection* conn) {
    pthread_mutex_lock(&conn->lock);
    conn->error_count++;
    pthread_mutex_unlock(&conn->lock);
}

void set_label(Connection* conn, const char* label) {
    pthread_mutex_lock(&conn->lock);
    strncpy(conn->label, label, sizeof(conn.label));
    pthread_mutex_unlock(&conn->lock);
}
```

