4. Implement a function to compute the content hash:

```cpp
void computeHash(const std::string& filePath, FileInfo& info) {
    std::ifstream ifs(filePath, std::ios::binary | std::ios::ate);
    if (!ifs) return;

    uintmax_t size = ifs.tellg();
    ifs.seekg(0);

    char buffer[512];
    ifs.read(buffer, 512);

    info.strHash ^= boost::hash_range(buffer, buffer + 512);
    info.sizeHash ^= size;
}
```

