void getMetadata(const std::string& filePath, FileInfo& info) {
    boost::filesystem::path p(filePath);
    boost::system::error_code ec;

    info.size = boost::filesystem::file_size(p, ec);
    if (ec) return;

    info.mtime = boost::filesystem::last_write_time(p, ec);
    if (ec) return;
}
