void init_data(size_t num_records, size_t* offsets, int* keys, double* measurements, dataRecord** records) {
    *offsets = (long*)mempool_alloc(num_records * sizeof(long));
    if (*offsets == NULL) {
        log_error("Failed to allocate memory for offsets");
        return;
    }

    *keys = (int*)mempool_alloc(num_records * sizeof(int));
    if (*keys == NULL) {
        mempool_free(*offsets);
        log_error("Failed to allocate memory for keys");
        return;
