    *measurements = (double*)mempool_alloc(num_records * sizeof(double));
    if (*measurements == NULL) {
        mempool_free(*keys);
        mempool_free(*offsets);
        log_error("Failed to allocate memory for measurements");
        return;
    }

    *records = (dataRecord*)mempool_alloc(num_records * sizeof(dataRecord));
    if (*records == NULL) {
        mempool_free(*measurements);
        mempool_free(*keys);
        mempool_free(*offsets);
        log_error("Failed to allocate memory for records");
        return;
    }

    pthread_t tid;
    for (size_t i = 0; i < num_records; ++i) {
