#include <iostream>
#include <vector>
#include <algorithm>
#include <cstdlib>
#include <ctime>
#include <mutex>
#include <functional>
#include <string>

struct Record {
    int* data;
    long offset;
};

void compression_fn(std::vector<int>& keys, std::vector<Record>& records) {
    for (size_t i = 1; i < keys.size(); ++i) {
        if (keys[i] == keys[i - 1]) {
            records[records[i].offset].data[0]++;
        } else {
            records[i].data = &records[i].data[0];
            records[i].data[0] = keys[i];
        }
    }
}

void decompression_fn(std::vector<Record>& records) {
    for (auto& record : records) {
        if (record.data[0] > 1) {
            std::fill_n(record.data + 1, record.data[0], record.data[0]);
        }
    }
}

std::mutex mtx;

void initializeDataStructures(int num_offsets, int min_offset, int max_offset, int min_key, int max_key, int* compression_fn, std::function<void(const char*)> log_success, std::function<void(const char*)> log_failure) {
    if (num_offsets <= 0) {
        log_failure("Error: num_offsets must be greater than zero.");
        return;
    }

    std::vector<long> offsets(num_offsets);
    std::vector<int> keys(num_offsets);
    std::vector<Record> records(num_offsets);

    std::srand(std::time(nullptr));

    for (size_t i = 0; i < offsets.size(); ++i) {
        offsets[i] = static_cast<long>(std::rand()) % ((max_offset - min_offset + 1) - min_offset) + min_offset;
        keys[i] = static_cast<int>(std::rand()) % ((max_key - min_key + 1) - min_key) + min_key;
    }

    std::vector<int> tempKeys(keys);
    std::sort(tempKeys.begin(), tempKeys.end());
    auto uniqueKeysIt = std::unique(tempKeys.begin(), tempKeys.end());
    keys.resize(std::distance(tempKeys.begin(), uniqueKeysIt));

    if (compression_fn) {
        std::vector<int> tempRecords(records.size());
        std::copy(records.begin(), records.end(), tempRecords.begin());
        compression_fn(keys, tempRecords);
        records.swap(tempRecords);
    }

    for (size_t i = 0; i < records.size(); ++i) {
        records[i].offset = offsets[i];
        records[i].data = &keys[records[i].offset];
    }

    log_success("Data structures initialized successfully.");
}
```

