#include <time.h>

typedef struct {
    long offset;
    int key;
    float value;
} Record;

struct MemoryPool {
    void* data;
    size_t capacity;
    size_t allocated;
    pthread_mutex_t lock;
};

struct RandomGenerator {
    unsigned long seed;
    float min, max;
};

void init_random(struct RandomGenerator* rg, float min, float max) {
    rg->min = min;
    rg->max = max;
    rg->seed = time(NULL);
}

float generate_random(struct RandomGenerator* rg) {
    // Implement a fast random number generator here
    return (rand_r(&rg->seed) * (rg->max - rg->min)) + rg->min;
}

void init_memory_pool(struct MemoryPool* mp, size_t n_longs, size_t m_ints, size_t p_floats, size_t max_size) {
    // Initialize memory pool with the specified constraints
    mp->data = malloc(n_longs + m_ints + p_floats * sizeof(float) + sizeof(struct MemoryPool));
    if (!mp->data) {
        fprintf(stderr, "Memory allocation failed\n");
        return;
    }

    mp->capacity = max_size;
    mp->allocated = 0;
    pthread_mutex_init(&mp->lock, NULL);
}

Record* allocate_record(struct MemoryPool* mp) {
    Record* record;
    size_t offset = mp->allocated * sizeof(long) + mp->allocated * sizeof(int) + (mp->allocated - 1) * sizeof(float);

    pthread_mutex_lock(&mp->lock);
    if (offset + sizeof(Record) > mp->capacity) {
        fprintf(stderr, "Memory allocation exceeded the limit\n");
        pthread_mutex_unlock(&mp->lock);
        return NULL;
    }

    record = (Record*)((char*)mp->data + offset);
    mp->allocated++;
    pthread_mutex_unlock(&mp->lock);

    record->offset = mp->allocated - 1;
    record->key = mp->allocated - 1;
    record->value = generate_random(rg); // Assuming rg is a global random generator instance

    return record;
}

void free_record(struct MemoryPool* mp, Record* record) {
    pthread_mutex_lock(&mp->lock);
    if (record->offset >= 0 && record->key >= 0) {
        mp->allocated--;
        pthread_mutex_unlock(&mp->lock);
    }
}
```

