#include <iostream>
#include <string>
#include <ctime>
#include <algorithm>

std::string modifyFileNameExtension(const std::string& originalFilename) {
    // Check if the filename is empty
    if (originalFilename.empty()) {
        throw std::runtime_error("Empty filename provided.");
    }

    // Get the current timestamp
    auto timestamp = std::to_string(std::time(nullptr));

    // Find the last dot in the original filename to get the current extension
    size_t lastDotPos = originalFilename.find_last_of('.');

    // If no dot found, assume it's not a file and return the original name
    if (lastDotPos == std::string::npos) {
        return originalFilename;
    }

    // Create a new filename by replacing the old extension with the timestamp and a new extension (e.g., .tmp)
    std::string newExtension = ".tmp";
    std::string newFileName = originalFilename.substr(0, lastDotPos);
    newFileName += timestamp + newExtension;

    return newFileName;
}
```

