#include <iostream>
#include <vector>
#include <unordered_map>
#include <list>
#include <cstdlib>
#include <ctime>

struct EventData {
    long timestamp;
    int identifier;
    size_t payloadLength;
    std::list<EventData>::iterator iter; // Iterator to the current position in the linked list
};

struct Record {
    int value;
    EventData eventData;
};

class MemoryPool {
public:
    MemoryPool(size_t size) : buffer_(std::vector<Record>(size)), nextFree_(0) {}

    Record* allocate() {
        if (nextFree_ < buffer_.size())
            return &buffer_[nextFree_++];
        else
            throw std::runtime_error("Memory pool exhausted");
    }

    void deallocate(Record* record) {
        nextFree_ = static_cast<unsigned int>(std::min)(nextFree_, record - buffer_.data());
    }

private:
    std::vector<Record> buffer_;
    unsigned int nextFree_;
};

void initDataStructures(MemoryPool& pool, std::unordered_map<long, std::list<EventData>>& hashTable, const int range) {
    srand(time(nullptr));

    for (auto& [offset, records] : hashTable) {
        for (auto it = records.begin(); it != records.end(); ++it) {
            Record* record = pool.allocate();
            record->value = rand() % range;
            it->eventData.timestamp = offset++;
            it->eventData.iter = records.erase(it);
            it->eventData.payloadLength = 0;
            *it = *record;
        }
    }
}

void logError(const std::string& message) {
    std::cerr << "ERROR: " << message << std::endl;
}
```

