    long offset;
    int key;
    float value;
};

class DynamicRandomValueGenerator {
public:
    DynamicRandomValueGenerator() {
        srand(time(nullptr));
    }

    float generate() {
        return static_cast<float>(rand()) / RAND_MAX * 2.0f - 1.0f;
    }
};

std::unique_ptr<Record[]> allocateRecords(size_t n, size_t m) {
    auto memoryPool = std::make_unique<char[]>(MAX_MEMORY);
    Record* records = static_cast<Record*>(memoryPool.get());
    size_t offsetSize = sizeof(long) * n + sizeof(int) * m;
    if (offsetSize > MAX_MEMORY - sizeof(Record) * 100) {
        std::cerr << "Error: Allocation exceeds memory limit" << std::endl;
        return nullptr;
    }

    records += n + m; // Move to the first record position

    auto offsetIterator = reinterpret_cast<long*>(records);
    auto keyIterator = reinterpret_cast<int*>(records + n);

    for (size_t i = 0; i < n; ++i) {
        *offsetIterator++ = i;
    }
    for (size_t i = 0; i < m; ++i) {
        *keyIterator++ = i;
    }

    auto recordIterator = reinterpret_cast<Record*>(records);
    DynamicRandomValueGenerator generator;
    for (size_t i = 0; i < 100; ++i) {
        recordIterator[i].offset = offsetIterator - records;
        recordIterator[i].key = keyIterator - records;
        recordIterator[i].value = generator.generate();
        recordIterator++;
    }

    return memoryPool;
}

void validateMemoryUsage(std::unique_ptr<char[]> memoryPool) {
    if (memoryPool->get_allocator().max_size() > MAX_MEMORY) {
        std::cerr << "Error: Allocated memory exceeds limit" << std::endl;
        exit(EXIT_FAILURE);
    }
}

void deallocateMemory(std::unique_ptr<char[]> memoryPool) {
    if (memoryPool) {
        memoryPool->reset();
    }
}

int main() {
    auto records = allocateRecords(10, 20);
    if (!records) return EXIT_FAILURE;

    validateMemoryUsage(std::move(records));

    // Process the records in parallel using threads
    std::mutex mtx;
    const int numThreads = 4;
    std::vector<std::thread> threads;
    for (int i = 0; i < numThreads; ++i) {
        threads.emplace_back([&]() {
            for (size_t i = 0; i < 100; ++i) {
                std::unique_lock<std::mutex> lock(mtx);
                // Process the record here
                lock.unlock();
            }
        });
    }

    for (auto& thread : threads) {
        thread.join();
    }

    deallocateMemory(std::move(records));
    return EXIT_SUCCESS;
}
```

