// Define sensor_data struct
typedef struct {
    time_t timestamp;
    int id;
    double sensor_reading;
    float temperature;
    char status_code;
    unsigned long sequence_number;
    struct sensor_data* next;
    struct sensor_data* prev;
} sensor_data;

// Define memory pool struct
typedef struct {
    void* free_list;
    size_t allocated_size;
    size_t total_size;
} memory_pool;

// Function to initialize a memory pool
void init_memory_pool(memory_pool* pool, size_t initial_size, size_t block_size) {
    // Initialize the memory pool with the given parameters
    pool->free_list = malloc(initial_size);
    if (!pool->free_list) {
        fprintf(stderr, "Failed to allocate memory for memory pool\n");
        exit(EXIT_FAILURE);
    }
    pool->total_size = initial_size;
    pool->allocated_size = 0;

    // Initialize the free list by linking all blocks together
    void* current = pool->free_list;
    for (int i = 1; i < initial_size; ++i) {
        ((char*)current)[block_size] = ((char*)current + block_size);
        current = ((char*)current + block_size);
    }
    ((char*)current)[0] = NULL;
}

// Function to allocate a new sensor_data struct from the memory pool
sensor_data* alloc_sensor_data(memory_pool* pool) {
    if (pool->free_list) {
        void* block = pool->free_list;
        pool->free_list = ((char*)pool->free_list + sizeof(sensor_data));
        --pool->allocated_size;
        ++pool->total_size;

        return (sensor_data*)block;
    }

    // If the memory pool is empty, allocate a new block of memory and return a new sensor_data struct
    void* new_block = malloc(sizeof(sensor_data) + pool->total_size);
    if (!new_block) {
        fprintf(stderr, "Failed to allocate memory for new sensor_data\n");
        exit(EXIT_FAILURE);
    }

    sensor_data* new_sensor = (sensor_data*)new_block;
    // Initialize the free list by linking all blocks together
    new_sensor->next = ((char*)new_block + sizeof(sensor_data));
    new_sensor->prev = NULL;
    for (int i = 1; i < pool->total_size; ++i) {
        ((char*)new_sensor)[i*sizeof(sensor_data)] = ((char*)new_sensor + i*sizeof(sensor_data));
    }
    ((char*)new_sensor)[pool->total_size*sizeof(sensor_data)] = NULL;

    pool->free_list = (char*)new_block + sizeof(sensor_data);
    pool->allocated_size++;

    return new_sensor;
}

// Function to free a sensor_data struct and return it to the memory pool
void free_sensor_data(memory_pool* pool, sensor_data* data) {
    if (data == NULL) return;

    // Update the free list by linking the freed block to the previous and next blocks
    data->prev->next = data->next;
    if (data->next) data->next->prev = data->prev;
    else pool->free_list = data;

    --pool->allocated_size;
    ++pool->total_size;
}

// Function to dynamically allocate and initialize a flexible sensor data processing module
sensor_module* create_sensor_module(memory_pool* pool, size_t num_streams) {
    // Allocate memory for the sensor module header and linked list of sensor streams
    sensor_module* module = (sensor_module*)alloc_sensor_data(pool);
    if (!module) return NULL;

    // Initialize the sensor module header
    module->num_streams = num_streams;
    module->head = NULL;
    module->tail = NULL;

    // Allocate and initialize each sensor stream
    for (int i = 0; i < num_streams; ++i) {
        sensor_data* new_stream = alloc_sensor_data(pool);
        if (!new_stream) return NULL;

        // Initialize the sensor stream
        new_stream->timestamp = time(NULL);
        new_stream->id = i;
        new_stream->next = NULL;
        new_stream->prev = NULL;

        // If the list is empty, set both head and tail to the new stream
        if (!module->head && !module->tail) {
            module->head = new_stream;
            module->tail = new_stream;
        } else {
            // Otherwise, append the new stream to the end of the list
            module->tail->next = new_stream;
            new_stream->prev = module->tail;
            module->tail = new_stream;
        }
    }

    return module;
}
```

