[' Here's a C function for managing network connections and records, with the specified features:

```c
#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <time.h>

typedef struct {
    int id;
    enum { IDLE, ESTABLISHED, CLOSED } state;
    time_t establishment_ts;
    time_t last_activity_ts;
    int error_count;
    char label[256];
    pthread_mutex_t lock;
} Record;

typedef struct {
    Record* records;
    size_t capacity;
    size_t count;
    pthread_mutex_t records_lock;
} RecordsPool;

RecordsPool records_pool;

void init_records_pool(size_t capacity) {
    records_pool.capacity = capacity;
    records_pool.count = 0;
    records_pool.records = malloc(sizeof(Record) * capacity);
    for (size_t i = 0; i < capacity; ++i) {
        Record* record = &records_pool.records[i];
        record->id = i;
        record->state = IDLE;
        record->establishment_ts = 0;
        record->last_activity_ts = 0;
        record->error_count = 0;
        strcpy(record->label, "");
        pthread_mutex_init(&record->lock, NULL);
    }
    pthread_mutex_init(&records_pool.records_lock, NULL);
}

Record* find_record(int id) {
    pthread_mutex_lock(&records_pool.records_lock);
    for (size_t i = 0; i < records_pool.count; ++i) {
        if (records_pool.records[i].id == id) {
            pthread_mutex_unlock(&records_pool.records_lock);
            return &records_pool.records[i];
        }
    }
    pthread_mutex_unlock(&records_pool.records_lock);
    return NULL;
}

Record* establish_connection(int id) {
    Record* record = find_record(id);
    if (!record || record->state != IDLE) return NULL;

    pthread_mutex_lock(&record->lock);
    record->state = ESTABLISHED;
    record->establishment_ts = time(NULL);
    record->last_activity_ts = record->establishment_ts;
    record->error_count = 0;
    strcpy(record->label, "");
    pthread_mutex_unlock(&record->lock);

    if (id < records_pool.capacity) {
        pthread_mutex_lock(&records_pool.records_lock);
        memmove(&records_pool.records[id + 1], &records_pool.records[id], sizeof(Record) * (records_pool.count - id - 1));
        --records_pool.count;
        pthread_mutex_unlock(&records_pool.records_lock);
    }

    log_connection_establishment(record);
    return record;
}

void close_connection(Record* record) {
    if (!record || record->state != ESTABLISHED) return;

    pthread_mutex_lock(&record->lock);
    record->state = CLOSED;
    record->last_activity_ts = time(NULL);
    ++record->error_count;
    strcpy(record->label, "ERROR");
    pthread_mutex_unlock(&record->lock);

    log_connection_close(record);
}

Record* query_record(int id) {
    Record* record = find_record(id);
    if (!record || record->state != ESTABLISHED) return NULL;
    return record;
}

void monitor_health(double inactivity_threshold, double error_rate_threshold) {
    pthread_mutex_lock(&records_pool.records_lock);
    for (size_t i = 0; i < records_pool.count; ++i) {
        Record* record = &records_pool.records[i];
        double inactivity_ratio = difftime(time(NULL), record->last_activity_ts) / (double)DIFF_TIME_DAY;
        double error_ratio = (double)record->error_count / records_pool.count;

        if (inactivity_ratio > inactivity_threshold || error_ratio > error_rate_threshold) {
            close_connection(record);
        }
    }
    pthread_mutex_unlock(&records_pool.records_lock);
}

