typedef struct {
    void* pool;
    size_t block_size;
    size_t num_blocks;
} MemoryPool;

MemoryPool create_memory_pool(size_t block_size, size_t num_blocks) {
    MemoryPool pool = {0};
    pool.block_size = block_size;
    pool.num_blocks = num_blocks;
    pool.pool = malloc(pool.num_blocks * pool.block_size);
    if (!pool.pool) {
        fprintf(stderr, "Failed to allocate memory for the memory pool\n");
        exit(EXIT_FAILURE);
    }
    return pool;
}

void* acquire_from_pool(MemoryPool* pool) {
    void* block = NULL;
    if (pool->num_blocks > 0) {
        block = pool->pool + (--pool->num_blocks) * pool->block_size;
    }
    return block;
}

void release_to_pool(MemoryPool* pool, void* block) {
    if (block) {
        pool->num_blocks++;
    }
}
```

2. Hash Table:

```c
typedef struct {
    size_t capacity;
    size_t num_elements;
    EventData** table;
} HashTable;

HashTable create_hash_table(size_t capacity) {
    HashTable table = {0};
    table.capacity = capacity;
    table.num_elements = 0;
    table.table = calloc(capacity, sizeof(EventData*));
    if (!table.table) {
        fprintf(stderr, "Failed to allocate memory for the hash table\n");
        exit(EXIT_FAILURE);
    }
    return table;
}

size_t hash(HashTable* table, int key) {
    return key % table->capacity;
}

EventData* find(HashTable* table, int key) {
    size_t index = hash(table, key);
    EventData** current = &table->table[index];
    while (*current && (*current)->key != key) {
        current = &(*current)->next;
    }
    return *current;
}

void insert(HashTable* table, EventData* record) {
    size_t index = hash(table, record->key);
    EventData** current = &table->table[index];
    while (*current) {
        current = &(*current)->next;
    }
    *current = record;
}
