    offset->keys = calloc(capacity, sizeof(Key*));
    offset->size = 0;
    return offset;
}

void offset_push(Offset* offset, Key* key) {
    if (offset->size == offset->keys->capacity) {
        offset->keys = realloc(offset->keys, offset->size * 2 * sizeof(Key*));
    }
    offset->keys[offset->size++] = key;
}

Key* key_init(int id, time_t timestamp) {
