#include <stdio.h>
#include <stdlib.h>
#include <stdbool.h>
#include <time.h>

typedef struct Record {
    long* offset;
    int key;
} Record;

void init_offsets(long** offsets, size_t num_offsets) {
    *offsets = malloc(num_offsets * sizeof(long));
    for (size_t i = 0; i < num_offsets; ++i) {
        (*offsets)[i] = i;
    }
}

void init_keys(int* keys, size_t num_keys) {
    *keys = malloc(num_keys * sizeof(int));
    for (size_t i = 0; i < num_keys; ++i) {
        (*keys)[i] = rand() % 2001 - 1000;
    }
    bool used[2001] = {false};
    for (size_t i = 0; i < num_keys; ++i) {
        while (used[(*keys)[i]]) {
            (*keys)[i] = rand() % 2001 - 1000;
        }
        used[(*keys)[i]] = true;
    }
}

void init_records(Record* records, size_t num_records) {
    records = malloc(num_records * sizeof(Record));
    long* offsets = NULL;
    init_offsets(&offsets, num_offsets);
    for (size_t i = 0; i < num_records; ++i) {
        Record* record = &records[i];
        record->offset = bsearch(record, offsets, num_offsets, sizeof(long), compare_long_pointers);
        if (record->offset == NULL) {
            record->offset = malloc(sizeof(long));
            *record->offset = num_offsets++;
            offsets = realloc(offsets, num_offsets * sizeof(long));
        }
        int* keys = records[0].key;
        init_keys(&keys, num_keys);
        record->key = keys[rand() % num_keys];
        for (size_t j = 0; j < num_records; ++j) {
            if (i != j && records[j].key == record->key) {
                init_keys(&keys, num_keys);
                --num_keys;
                --i;
                break;
            }
        }
    }
}

int compare_long_pointers(const void* a, const void* b) {
    return (*(const long*)a - *(const long*)b);
}

void print_records(Record* records, size_t num_records) {
    for (size_t i = 0; i < num_records; ++i) {
        printf("Record %zu: offset=%ld, key=%d\n", i, *(records[i].offset), records[i].key);
    }
}

void free_memory(long* offsets, Record* records, size_t num_records, int* keys) {
    free(keys);
    for (size_t i = 0; i < num_records; ++i) {
        free(records[i].offset);
    }
    free(records);
    free(offsets);
}

int main() {
    srand(time(NULL));
    const size_t num_offsets = 1000;
    const size_t num_keys = 500;
    const size_t num_records = 1000;

    long* offsets = NULL;
    init_offsets(&offsets, num_offsets);

    Record* records = NULL;
    init_records(&records, num_records);

    int* keys = NULL;
    init_keys(&keys, num_keys);

    print_records(records, num_records);

    free_memory(offsets, records, num_records, keys);

    return 0;
}
```

