import json
from typing import Any, Dict, Type

class JSONObject:
    def __init__(self, data: Any = None):
        self._data = data or {} if data is not None else {}

    def to_json(self) -> str:
        return json.dumps(self._data)

    @staticmethod
    def from_json(json_str: str) -> 'JSONObject':
        return JSONObject(json.loads(json_str))

class JSONRegistry:
    _registry = {}

    @classmethod
    def register(cls, id: str, factory: Type['JSONObject']) -> None:
        cls._registry[id] = factory

    @classmethod
    def create(cls, id: str, **kwargs) -> 'JSONObject':
        if id not in cls._registry:
            raise ValueError(f"Unknown JSON object type '{id}'")

        return cls._registry[id](**kwargs)
